INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('c7c14ffe-80e9-46fb-a943-3be7e567675a', 'Standing Gluteus Medius Press (Stability Ball)', 'Core', 'Stability Ball', '{"Glutes"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this pressing movement that works your core. The standing position engages your core for stability. The stability ball adds an instability challenge that activates more stabilizer muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '100061201', '100061201-Standing-Gluteus-Medius-Press-against-Ball-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Position the stability ball as needed for Standing Gluteus Medius Press. 2. Begin in a standing position with good posture. 3. Execute the pressing motion for Standing Gluteus Medius Press, extending through the target muscles. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 64, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Gluteus Medius Press', 'lateral_raise, front_raise, rear_delt_fly, upright_row', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c7c8f9b6-4487-42ab-87b9-6cc16af0a138', 'Body Saw (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The TRX allows you to adjust difficulty by changing your body angle. Building core stability helps with everything from heavy deadlifts to daily activities.', '11101201', '11101201-Suspender-Body-Saw-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Body Saw. 2. Set up in the starting position for Suspender Body Saw. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Body Saw', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('c7d1d1d0-1e9d-4033-bb45-00f5ebf9867b', 'Leg Front Lift Jack', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements. Works well as both a primary exercise or accessory movement.', '55871201', '55871201-Leg-Front-Lift-Jack-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Set up in the starting position for Leg Front Lift Jack. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'leg_exercise', 'Leg Front Lift Jack', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('c7d2593d-e9cf-4338-a514-5acab71ce448', 'Pulsing Prayer Push', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'The Pulsing Prayer Push is a pushing exercise that targets your chest muscles. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '59951201', '59951201-Pulsing-Prayer-Push-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Set up in the starting position for Pulsing Prayer Push. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'boxing', 'Pulsing Prayer Push', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c7d68631-a538-4cf3-b1e4-c1f815f8e5b1', 'Single Leg Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Dumbbell Single Leg Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '4111201', '04111201-Dumbbell-Single-Leg-Squat_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'pistol_squat', 'Single Leg Squat', 'squat, bench_press, deadlift', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('c7e22f23-07b4-4df8-86f3-f99be5130987', 'Assisted Lying Leg Raise With Lateral Throw Down', 'Back', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Build a stronger core with the Assisted Lying Leg Raise With Lateral Throw Down, focusing on your abs. You''ll also feel your hip flexors working to support the movement. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '106891201', '106891201-Assisted-Lying-Leg-Raise-With-Lateral-Throw-Down-.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Lie down in the appropriate position for Assisted Lying Leg Raise With Lateral Throw Down. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'leg_raise', 'Assisted Lying Leg Raise With Lateral Throw Down', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c7e8d995-28c4-416a-bf83-aec80738c32a', 'Pigeon Pose', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'This stretch specifically works on your hips, promoting flexibility and reducing muscle tightness. Secondary activation of your glutes provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension.', '85921201', '85921201-Pigeon-Pose-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Move into the stretch position for Pigeon Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'hip_stretch', 'Pigeon Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c7f41e59-ea48-4ee2-99cc-c483aa2e436d', 'Heel To Heel Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Heel To Heel Tap builds reactive power and improves conditioning. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '58391201', '58391201-Heel-to-Heel-Tap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Set up in the starting position for Heel To Heel Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Heel To Heel Tap', 'crunch, bicycle_crunch, russian_twist', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c800807d-c7b4-4e60-8388-79a5e3e4f6f1', 'Bicep Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition. This is a great exercise for all fitness levels with proper scaling.', '91971201', '91971201-Dumbbell-Biceps-Curl-(VERSION-3)-(female)_Upper-Ar.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'bicep_curl', 'Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('c803ba68-6a7b-4319-9876-cf6a94156c74', 'Sumo Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Strong legs are the foundation for athletic performance and functional fitness.', '10631201', '10631201-Barbell-Sumo-Squat_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Sumo Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Sumo Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('c80f3110-6d44-4db2-965b-5821caac767c', 'Hamstring Bridge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Strengthen the back of your thighs with this bridging exercise. Your hamstrings work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '83581201', '83581201-Hamstring-Bridge-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 38, 7, 8, TRUE, TRUE, 'glute_bridge', 'Hamstring Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 68, 85, 85, 70),
('c819188d-f581-46c6-8e9d-7e8c24d02d22', 'Gorilla Row (Kettlebell)', 'Back', 'Kettlebell', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The kettlebell''s offset center of mass increases the stability challenge. A strong back improves posture, prevents injury, and balances pressing movements.', '72301201', '72301201-Kettlebell-Gorilla-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Select an appropriately weighted kettlebell for Kettlebell Gorilla Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Gorilla Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('c81d9478-faad-406a-991c-bc9527ba1670', 'Shoulder Grip Inverted Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Shoulder Grip Inverted Row is a rowing exercise that builds thickness in your upper back. Your biceps work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '106021201', '106021201-Shoulder-grip-Inverted-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Shoulder Grip Inverted Row', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c82578f2-4386-4640-adf8-44290edbb664', 'Max Speed Uppercut', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. Secondary activation of your shoulders, core provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '67311201', '67311201-Max-Speed-Uppercut-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Set up in the starting position for Max Speed Uppercut. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Max Speed Uppercut', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c82ac2f1-42ab-432d-9184-687d0b7451a4', 'Seated Single Leg Slow Raise (Chair)', 'Shoulders', 'Chair', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Build leg strength with this raising movement focusing on your core. Being seated provides stability, allowing you to focus on the working muscles. Leg training boosts metabolism and builds functional, real-world strength.', '104771201', '104771201-Seated-Single-Leg-Slow-Raise-on-Chair-(male)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a slow, controlled tempo throughout the entire range of motion. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'leg_exercise', 'Seated Single Leg Slow Raise On Chair', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('c82cfe3e-d5de-4b8e-a0e4-2a11e084b6f0', 'Lying Top Grab Front Grab', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'The Lying Top Grab Front Grab is a movement exercise that targets your chest muscles. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '90351201', '90351201-Lying-Top-Grab-Front-Grab-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Top Grab Front Grab. 2. Set up in the starting position for Lying Top Grab Front Grab. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'core_exercise', 'Lying Top Grab Front Grab', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c82f984c-171b-4dd5-9580-0e6d1f5c9a92', 'Uppercuts Step In Place', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. You''ll also feel your shoulders, core working to support the movement. Great for improving athletic performance, burning calories, and building conditioning.', '65261201', '65261201-Uppercuts-Step-in-Place-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Uppercuts Step In Place. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Uppercuts Step In Place', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c83bb5cb-3dfd-49d8-83fa-941d28c53b06', 'Low Chest Press (Band) - Alternating', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Band Low Alternate Chest Press, an effective pressing movement for upper body strength. You''ll also feel your triceps, front delts working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. A well-developed chest contributes to upper body strength and aesthetics.', '70341201', '70341201-Band-Low-Alternate-Chest-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Low Alternate Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'bench_press', 'Low Chest Press - Alternating', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('c84b495b-e819-45fc-b06d-100c506ee331', 'Standing T Spine Press (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{}'::text[], 'Build a stronger back with this pressing movement targeting your full body. Performing this standing challenges your balance and core engagement. Dumbbells allow each arm to work independently, helping correct imbalances. A strong back improves posture, prevents injury, and balances pressing movements.', '69641201', '69641201-Dumbbell-Standing-T-spine-Press-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing T Spine Press. 2. Begin in a standing position with good posture. 3. Execute the pressing motion for Dumbbell Standing T Spine Press, extending through the target muscles. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 84, 7, 8, TRUE, TRUE, 'cycling', 'Standing T Spine Press', 'lateral_raise, front_raise, rear_delt_fly, upright_row', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('c84cb956-5270-4abb-b368-7ab42cc1a67e', 'Forward Backward Lunge (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '86391201', '86391201-Barbell-Forward-Backward-Lunge-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Grip a barbell with hands at the appropriate width for Barbell Forward Backward Lunge. 2. Step backward, lowering your back knee toward the floor. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Forward Backward Lunge', 'split_squat, step_up, squat', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('c84f62c7-b5e5-4c9d-ba9f-af050070b0c7', 'Ring Incline Push Up (Gymnastic Rings)', 'Chest', 'Gymnastic Rings', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Ring Incline Push Up, an effective pushing movement for upper body strength. Your triceps, front delts work as secondary movers, adding to the training stimulus. Using an incline changes the angle of resistance for varied muscle recruitment. A well-developed chest contributes to upper body strength and aesthetics.', '78691201', '78691201-Ring-Incline-Push-up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 61, 7, 8, TRUE, TRUE, 'push_up', 'Ring Incline Push Up', 'bench_press, chest_fly, dip', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('c8534e86-a0a7-4de1-9920-4207b62e1355', 'Wide Stance Split Lunge Support (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. Leg training boosts metabolism and builds functional, real-world strength.', '87931201', '87931201-Wide-Stance-Split-Lunge-with-Chair-Support-(female.mp4', 'female', FALSE, '2025-12-03 23:26:40.146812+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'lunge', 'Wide Stance Split Lunge With Chair Support', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c85a0aab-40d8-4230-a297-574fc7f82c15', 'Dynamic Chest Stretch', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Dynamic Chest Stretch is a stretching exercise that targets your chest muscles. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '11671201', '11671201-Dynamic-Chest-Stretch-(male)_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Set up in the starting position for Dynamic Chest Stretch. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'chest_stretch', 'Dynamic Chest Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c85e6bfe-39d4-480f-9be7-ff4e67d87c08', 'Side Up Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Up Squat is an explosive exercise that combines cardiovascular training with dynamic squatting movements. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '60881201', '60881201-Side-Up-Squat-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control. Great for building strength in your quads. Variation: Side Up Squat.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Side Up Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c878e3a4-96d9-4996-9167-309ebc155eb3', 'Lying Double Leg Kick', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Performing this lying down removes momentum for stricter form. Include this in your routine for better mobility and reduced muscle tension.', '28511201', '28511201-Lying-Double-Leg-Kick-(female)_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Double Leg Kick. 2. Move into the stretch position for Lying Double Leg Kick. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Lying Double Leg Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c87928a7-bfa8-4794-875e-9614c8312ca9', 'Reverse Ab Rollout (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Suspender Reverse Ab Rollout is a core movement exercise that primarily targets your abs. You''ll also feel your lats, shoulders working to support the movement. Suspension training adds instability, increasing core activation throughout. Building core stability helps with everything from heavy deadlifts to daily activities.', '95041201', '95041201-Suspender-Reverse-Ab-Rollout_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Reverse Ab Rollout. 2. Set up in the starting position for Suspender Reverse Ab Rollout. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'ab_rollout', 'Suspender Reverse Ab Rollout', 'plank, crunch, dead_bug', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('c87ac907-8b64-4055-888f-b59409b54fa0', 'Seated Crossover Shoulders Stretch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{}'::text[], 'Target your chest with this stretching stretch that helps restore range of motion. Secondary activation of your front delts provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '82381201', '82381201-Seated-Crossover-Shoulders-Stretch-(female)_Stretc.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Crossover Shoulders Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'chest_fly', 'Seated Crossover Shoulders Stretch', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c87ea21b-2bc6-4316-ac08-1889e36c29e7', 'Overhead Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '42941201', '42941201-Bodyweight-Overhead-Squat_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Overhead Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c8911587-d953-4528-b298-b91ad4faf395', 'Commando Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Commando Pull Up is a pulling exercise that targets your latissimus dorsi for a wider back. Secondary activation of your biceps, upper back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements.', '47261201', '47261201-Commando-Pull-up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Commando Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c89c4cac-412d-4464-a7c2-a229e8b8d087', 'Glute Bridge Abduction (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '71981201', '71981201-Resistance-Band-Glute-Bridge-Abduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band Glute Bridge Abduction. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Abduction', 'hip_thrust, romanian_deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('c8ac0884-2b73-4a74-bcbf-d24901ae7bf1', 'Staggered Stance Hip Thrust (Barbell)', 'Legs', 'Barbell', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Develop your posterior chain with this thrusting movement that emphasizes the glutes. Secondary activation of your hamstrings provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Strong legs are the foundation for athletic performance and functional fitness.', '54761201', '54761201-Barbell-Staggered-Stance-Hip-Thrust_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Staggered Stance Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'hip_thrust', 'Staggered Stance Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('c8baa336-827e-4472-bcc4-4f9fbd875de5', 'Hack Squat (Machine)', 'Legs', 'Hack Squat Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '7431201', '07431201-Sled-Hack-Squat_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'hack_squat', 'Sled Hack Squat', 'leg_press, squat, leg_extension', TRUE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('c8bb2fd9-f6c8-4fc0-99a7-86bb057746b1', 'Star Plank Toe Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. Secondary activation of your shoulders, lower back provides additional muscle engagement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities. Aim for full range of motion on every rep.', '103961201', '103961201-Star-Plank-Toe-Tap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Keep your core engaged for stability. This exercise is excellent for abs development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Star Plank Toe Tap', 'side_plank, dead_bug, hollow_hold', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c8c1873e-75ce-4cc2-8c6d-06a3c80faf1f', '3 Leg Chaturanga Pose', 'Core', 'Bodyweight', '{"Core"}'::text[], '{}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. No equipment needed—your body provides all the resistance. Compound movements like this develop coordination, power, and overall fitness.', '59151201', '59151201-3-Leg-Chatarunga-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Set up in the starting position for 3 Leg Chaturanga Pose. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', '3 Leg Chaturanga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c8c2618a-6578-405b-bdc9-f8835ea28f09', 'Happy Baby Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your hips area and enhance overall flexibility. Your lower back, adductors work as secondary movers, adding to the training stimulus. Flexibility work like this enhances performance and prevents stiffness.', '59171201', '59171201-Happy-Baby-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Move into the stretch position for Happy Baby Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Happy Baby Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c8c26461-2aee-4c70-9fb8-a57a8b0c9f74', 'Animal Resting Yoga Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Flexibility work like this enhances performance and prevents stiffness. Keep your core engaged throughout the exercise.', '43651201', '43651201-Animal-Resting-Yoga-Pose_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Move into the stretch position for Animal Resting Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Animal Resting Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c8c68ab4-9031-4016-867c-f627d2cf0680', 'Horizontal Pallof Press (Resistance Band)', 'Core', 'Resistance Band, Anchor Point', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Resistance Band Horizontal Pallof Press, focusing on your abs. Bands are joint-friendly and portable, perfect for any training environment. Core strength is foundational for athletic performance and injury prevention.', '42401201', '42401201-Resistance-Band-Horizontal-Pallof-Press_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Secure the resistance band appropriately for Resistance Band Horizontal Pallof Press. 2. Execute the pressing motion for Resistance Band Horizontal Pallof Press, extending through the target muscles. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'pallof_press', 'Horizontal Pallof Press', 'woodchop, plank, dead_bug', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('c8c70ab0-319b-4bb5-a2dd-816d065b0958', 'Lat Stretch (TRX)', 'Back', 'TRX', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Build lat width and pulling strength with this stretching movement. The TRX allows you to adjust difficulty by changing your body angle. Back development is crucial for pulling strength and overall upper body function.', '72781201', '72781201-Suspender-Lat-Stretch-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Lat Stretch. 2. Set up in the starting position for Suspender Lat Stretch. 3. Execute the movement with proper form, focusing on your lats. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 30, 2, 6, FALSE, TRUE, 'lat_stretch', 'Suspender Lat Stretch', 'stretch_hip, stretch_back', FALSE, 'trx', TRUE, 1, 30, 2, 68, 85, 85, 70),
('c8cc4745-2c4d-4e73-8d60-94644a81401b', 'Squat Side Up Hook Punch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Squat Side Up Hook Punch builds reactive power and improves conditioning. The shoulders, core assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '66621201', '66621201-Squat-Side-up-Hook-Punch-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat Side Up Hook Punch', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c8e53577-b812-439e-a075-b33a96b84fb1', 'Reverse Hyperextension (Machine)', 'Back', 'Lever Machine', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this extension movement that emphasizes the glutes. Secondary activation of your hamstrings, lower back provides additional muscle engagement. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '5931201', '05931201-Lever-Reverse-Hyperextension-(plate-loaded)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Reverse Hyperextension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'back_extension', 'Lever Reverse Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('c8f63ffa-fa23-4e2d-bbb5-6aafaa72a373', 'Standing Pronated Grip Inverted Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '92221201', '92221201-Standing-Pronated-Grip-Inverted-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand tall with your feet firmly planted. 2. Use an overhand (pronated) grip with palms facing down/away. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Pronated Grip Inverted Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c8fac4a0-fb65-4836-9ca7-f85fab86ac2f', 'Bent Over Row (Barbell)', 'Back', 'Barbell', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'The Barbell Bent Over Row is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, lats working to support the movement. The bent over position requires core engagement to maintain a neutral spine. Using a barbell provides stability for progressive overload. A strong back improves posture, prevents injury, and balances pressing movements.', '22421201', '22421201-Barbell-Bent-Over-Row-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', 'Row', 'Pull', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Standing (Hinged)', NULL, 'Overhand (Pronated)', 'Standard', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'bent_over_row', 'Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('c91c9951-cf58-4b5e-b140-ee04051da9cd', 'Overhead Sit Up (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Building core stability helps with everything from heavy deadlifts to daily activities.', '47481201', '47481201-Dumbbell-Overhead-Sit-up_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Overhead Sit Up. 2. Set up in the starting position for Dumbbell Overhead Sit Up. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'crunch', 'Overhead Sit Up', 'leg_raise, plank, russian_twist, v_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('c91d48fd-be02-4bbd-a095-b40af95fe09f', 'Mountain Climber Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this lunging exercise that develops speed, power, and coordination. Your hip flexors, shoulders work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '6291201', '06291201-Mountain-Climber-Lunge-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber Lunge', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('c923cff8-6161-4c3f-9e63-671faf88d9b2', 'Seated Calf Stretch', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted stretching exercise. The seated position helps isolate the target muscles by removing momentum. Strong legs are the foundation for athletic performance and functional fitness.', '49281201', '49281201-Seated-Calf-Stretch-(VERSION-2)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Calf Stretch. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'calf_stretch', 'Seated Calf Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c927a62e-9dce-4396-a8d5-db2cbaf2a87a', 'Sphinx Pose Look Up', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Include this in your routine for better mobility and reduced muscle tension. Perfect for including in both strength and hypertrophy programs. Listen to your body and adjust intensity as needed.', '82341201', '82341201-Sphinx-Pose-Look-Up-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Move into the stretch position for Sphinx Pose Look Up. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'back_stretch', 'Sphinx Pose Look Up', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c927af03-3c23-432b-b62b-b2ace7f8f8a2', 'Standing Double Knee Raise Side Step', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This dynamic raising movement gets your heart rate up while developing explosive strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Great for improving athletic performance, burning calories, and building conditioning.', '88381201', '88381201-Standing-Double-Knee-Raise-Side-Step-(female)_Plyo.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Set up a box or step platform at the appropriate height. 2. Stand tall with your feet firmly planted. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Standing Double Knee Raise Side Step', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('c93fa01e-ac2a-4134-93bd-c370ec2b93fc', 'Seated 45 Degrees Neck Stretch (Chair)', 'Neck', 'Chair', '{"Neck"}'::text[], '{"Traps"}'::text[], 'Designed to lengthen your neck, the Seated 45 Degrees Neck Stretch On A Chair helps improve mobility and prevent stiffness. Your upper back work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '104691201', '104691201-Seated-45-Degrees-Neck-Stretch-on-a-Chair-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated 45 Degrees Neck Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 27, 2, 6, FALSE, TRUE, 'neck_stretch', 'Seated 45 Degrees Neck Stretch On A Chair', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c94a7f0e-05f3-4b9e-9c15-10cff8b1779b', 'Elbow Plank Thigh Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention. Aim for full range of motion on every rep.', '103971201', '103971201-Elbow-Plank-Thigh-Tap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection. This exercise is excellent for abs development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Elbow Plank Thigh Tap', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c95fcb0e-8443-4a26-bcdc-a3e3878b6109', 'Single Leg Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Barbell Single Leg Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength.', '26341201', '26341201-Barbell-Single-Leg-Deadlift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Single Leg Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'deadlift', 'Single Leg Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('c963c9a2-1f39-42f6-8ac6-5b82e13a1e61', 'Side Lunge Hop', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Elevate your training with this lunging exercise that develops speed, power, and coordination. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '75261201', '75261201-Side-Lunge-Hop-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'lunge', 'Side Lunge Hop', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('c964c978-62db-4d6c-873e-a56ef079c943', 'Full Hack Squat (Machine)', 'Legs', 'Hack Squat Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes assist throughout the movement, making this a well-rounded exercise. Lower body strength improves everything from walking to heavy compound lifts.', '90071201', '90071201-Sled-Full-Hack-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. This variation specifically emphasizes the quads. Variation: Sled Full Hack Squat.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'hack_squat', 'Sled Full Hack Squat', 'leg_press, squat, leg_extension', TRUE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('c9658e59-106f-4b50-8e16-88744eaac05a', 'Mini Side Shuffles Slight Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Mini Side Shuffles Slight Knee Raise is an explosive exercise that combines cardiovascular training with dynamic raising movements. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '78581201', '78581201-Mini-Side Shuffles-Slight-Knee-Raise-(male)_Plyome.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'leg_raise', 'Mini Side Shuffles Slight Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('c970338b-0de6-47a7-941a-28cd4a071a61', 'Feet Front Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Feet Front Tap is an explosive exercise that combines cardiovascular training with dynamic movement movements. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '77601201', '77601201-Feet-Front-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Set up in the starting position for Feet Front Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Feet Front Tap', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c9741fc7-537b-4174-a177-4f8c9929109c', 'Lying Hip Adduction', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Lying Hip Adduction is a lower body movement exercise that targets your adductors. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '71301201', '71301201-Lying-Hip-Adduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Hip Adduction. 2. Set up in the starting position for Lying Hip Adduction. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_adduction', 'Lying Hip Adduction', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c97e490f-6349-42a9-9b40-cc116497e845', 'Seated Knee Tuck (Chair) - Alternating', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Alternate Knee Tuck On A Chair, focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. A strong core improves posture, protects your spine, and enhances all other lifts.', '76311201', '76311201-Sitting-Alternate-Knee-Tuck-on-a-Chair-(female)_Wa.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Alternate between sides/arms/legs with each repetition. 4. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Knee Tuck On A Chair - Alternating', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c9819a2f-ec84-471f-a624-05b6a8b67d75', 'Double Knee Raise - Underhand', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Underhand Double Knee Raises is an explosive exercise that combines cardiovascular training with dynamic raising movements. Your hip flexors work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '67811201', '67811201-Underhand-Double-Knee-Raises-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Use an underhand (supinated) grip with palms facing up/toward you. 2. Raise the weight in the prescribed direction for Underhand Double Knee Raises. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Underhand Double Knee Raise', 'Double Knee Raises - Underhand', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('c9878350-e276-4cbc-9440-b8ec316daf5e', 'Seated Calf Raise - Single Leg (Machine)', 'Legs', 'Machine', '{"Calves"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted pressing exercise. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. The machine guides your movement path for safer, more controlled repetitions. Leg training boosts metabolism and builds functional, real-world strength.', '71091201', '71091201-Lever-Seated-Single-Leg-Squat-Calf-Raise-on-Leg-Press-Machine-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Single Leg Squat Calf Raise On Leg Press Machine. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Position your feet on the platform and release the safety. 4. Lower the weight by bending your knees, then press back up powerfully. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 100, 5, 7, FALSE, TRUE, 'pistol_squat', 'Lever Seated Single Leg Squat Calf Raise On Leg Press', 'squat, bench_press, deadlift', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('c9a14a0c-e5f7-4f0f-9351-60ba373c0061', 'Bicep Curl - Close Grip (Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. Resistance bands provide accommodating resistance that increases through the range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '41381201', '41381201-Band-Close-Grip-Biceps-Curl_Upeer-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Secure the resistance band appropriately for Band Close Grip Biceps Curl. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting. Control the movement—avoid using momentum.', 'Curl', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Underhand', 'Standard', 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'bicep_curl', 'Biceps Curl - Close Grip', 'Biceps Curl - Close Grip', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('c9ac6653-6c78-4ccf-9622-aed3d0b0740b', 'Abduction Of Single Leg Flexion Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this flexion movement that develops leg drive and power. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '19061201', '19061201-Abduction-Of-One-Leg-Flexion-Stretch-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for Abduction Of One Leg Flexion Stretch. 3. Execute the movement with proper form, focusing on your quads. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 35, 2, 6, FALSE, TRUE, 'hip_abduction', 'Abduction Of Single Leg Flexion Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c9b5a6e2-a021-4791-85db-fdcdcde283bd', 'Incline Bench Press (Kettlebell)', 'Chest', 'Kettlebell, Incline Bench', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Kettlebell Incline Bench Press, an effective pressing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. Using an incline changes the angle of resistance for varied muscle recruitment. Kettlebells are excellent for building functional, real-world strength. A well-developed chest contributes to upper body strength and aesthetics.', '68171201', '68171201-Kettlebell-Incline-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Select an appropriately weighted kettlebell for Kettlebell Incline Bench Press. 2. Set the bench to an incline angle (30-45 degrees). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 96, 7, 8, TRUE, TRUE, 'incline_press', 'Incline Bench Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('c9b72d2a-b216-47aa-b057-b46c6fa8a2cd', 'Goblet Squat (Cable)', 'Legs', 'Cables', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Cable resistance creates smooth, continuous muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '82951201', '82951201-Cable-Goblet-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Adjust the cable machine to the correct height and attachment for Cable Goblet Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 95, 7, 8, TRUE, TRUE, 'goblet_squat', 'Goblet Squat', 'squat, front_squat, lunge', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('c9c37276-020e-49de-a52d-97035abdcd5a', 'Deadstop Row With Rack (Barbell)', 'Back', 'Barbell', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Using a barbell provides stability for progressive overload. A strong back improves posture, prevents injury, and balances pressing movements.', '41261201', '41261201-Barbell-Deadstop-Row-with-Rack-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Deadstop Row With Rack. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'general_exercise', 'Deadstop Row With Rack', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('c9c5a7ee-7690-4a52-af8b-e37e7cf3cbd5', 'Dynamic Butterfly Pose', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target your adductors with this flying stretch that helps restore range of motion. You''ll also feel your hips working to support the movement. Include this in your routine for better mobility and reduced muscle tension. A staple exercise that belongs in most training programs.', '84881201', '84881201-Dynamic-Butterfly-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. Don''t rush—quality over quantity. Works well for adductors activation.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 70, 2, 6, FALSE, TRUE, 'groin_stretch', 'Dynamic Butterfly Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('c9cd1f8d-72cd-450e-9567-8341ef7ab2c0', 'Seated Floor Crunch Knee Raise To To - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '104201201', '104201201-Sitting-Floor-Crunch-Alternating-Knee-Raise-to-To.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Position yourself on the floor for Seated Floor Crunch Alternating Knee Raise To To. 2. Sit on the floor with your legs positioned as required. 3. Raise the weight in the prescribed direction for Seated Floor Crunch Alternating Knee Raise To To. 4. Lower with control, maintaining tension throughout. 5. Alternate between sides/arms/legs with each repetition. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Floor Crunch Knee Raise To To - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('c9d03c7e-770b-48ee-870d-e1fce9ac162c', 'Pulse Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Pulse Row is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps, rear delts provides additional muscle engagement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '29231201', '29231201-Pulse-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. At the bottom or top, pulse up and down in small movements before completing the rep. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pulse', 'Pulse Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('c9de3bd5-5f31-4dc9-9b83-a6ccb818311a', 'Goblet Forward Backward Lunge (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The kettlebell''s offset center of mass increases the stability challenge. Leg training boosts metabolism and builds functional, real-world strength.', '86411201', '86411201-Kettlebell-Goblet-Forward-Backward-Lunge-(male)_Th.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Select an appropriately weighted kettlebell for Kettlebell Goblet Forward Backward Lunge. 2. Step backward, lowering your back knee toward the floor. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'goblet_squat', 'Goblet Forward Backward Lunge', 'squat, split_squat, step_up, leg_press', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('c9e14b61-a7b6-4ed4-9e04-3ad3314facc0', 'Single Arm Row (Kettlebell)', 'Back', 'Kettlebell', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. The kettlebell grip position adds a unique training stimulus. A strong back improves posture, prevents injury, and balances pressing movements.', '5411201', '05411201-Kettlebell-One-Arm-Row_back.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Select an appropriately weighted kettlebell for Kettlebell One Arm Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Single Arm Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('c9f42c39-b2eb-457b-85e2-096441d65dbf', 'Tabletop Reach And Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. Your hip flexors work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '78521201', '78521201-Tabletop-Reach-and-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Tabletop Reach And Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('c9fe6c4c-64de-45bf-ac49-b4f19700a23b', 'Lying Knee Hug', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Lying Knee Hug is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. The lying position provides back support and helps isolate the target muscles. Flexibility work like this enhances performance and prevents stiffness.', '72441201', '72441201-Lying-Knee-Hug-(female)_Stretching-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Knee Hug. 2. Move into the stretch position for Lying Knee Hug. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Knee Hug', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ca181589-94fb-48a1-ba56-e50421abaa5b', 'Bent Over Single Arm Crossover (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. The front delts assist throughout the movement, making this a well-rounded exercise. Bending over allows gravity to provide resistance in a different plane. Cable resistance creates smooth, continuous muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '70651201', '70651201-Cable-Bent-Over-Single-Arm-Crossover-(female)_Ches.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Adjust the cable machine to the correct height and attachment for Cable Bent Over Single Arm Crossover. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Complete all reps on one side, then switch to the other side. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'chest_fly', 'Bent Over Single Arm Crossover', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('ca252738-5a33-45cc-8da6-166a75e61774', 'Side Step Boxing Handroll', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. Secondary activation of your quads provides additional muscle engagement. Plyometric training builds explosive power that transfers to sports and daily activities. This variation is excellent for building mind-muscle connection.', '55361201', '55361201-Side-Step-Boxing-Handroll-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Boxing Handroll. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Side Step Boxing Handroll', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ca274cef-65e6-4836-9dc5-5aa87826f976', 'Jefferson Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength. Start with lighter weight to master the movement pattern.', '511201', '00511201-Barbell-Jefferson-Squat_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Jefferson Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 35, 7, 9, TRUE, FALSE, 'squat', 'Jefferson Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('ca2febc5-61ad-4d6f-a557-3428c90260b2', 'Janda Sit Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Janda Sit Up is a core movement exercise that primarily targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '30931201', '30931201-Janda-Sit-up-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Set up in the starting position for Janda Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Janda Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ca33b050-7a37-49e7-8b5f-b60369c5cba8', 'Box Assisted Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Secondary activation of your biceps, upper back provides additional muscle engagement. Back development is crucial for pulling strength and overall upper body function. This is a great exercise for all fitness levels with proper scaling.', '95111201', '95111201-Box-Assisted-Pull-up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Set up a box or step platform at the appropriate height. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Box Assisted Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ca3d4eb4-cfc4-4254-9632-e0cecaad25f9', 'Standing Plate Press (Plate)', 'Chest', 'Weight Plate', '{"Chest"}'::text[], '{}'::text[], 'The Standing Plate Press is a pressing exercise that targets your chest muscles. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '107161201', '107161201-Standing-Plate-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Plate Press', 'lateral_raise, front_raise, rear_delt_fly, upright_row', FALSE, 'plate', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ca52789d-dd40-443d-af6e-bf0dccae9c20', 'Seated Wrist Curl (Smith Machine)', 'Arms', 'Smith Machine', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. Your forearms work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. The fixed path allows you to focus purely on muscular effort. Arm strength supports grip, pulling, and pushing in compound movements.', '14261201', '14261201-Smith-Seated-Wrist-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Seated Wrist Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'wrist_curl', 'Smith Seated Wrist Curl', 'Seated Wrist Curl', FALSE, 'smith_machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('ca5e102f-42d6-4f6d-babb-67800a05847b', 'Ring Leg Curl (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'The Ring Leg Curl targets your hamstrings through a controlled curling motion. Secondary activation of your calves provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '48191201', '48191201-Ring-Leg-Curl_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Curl your heels toward your glutes by bending at the knees. 2. Squeeze your hamstrings at peak contraction. 3. Extend legs back out with control. 4. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 68, 7, 8, TRUE, TRUE, 'leg_curl', 'Ring Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('ca73898b-7e41-4198-9774-b8273f7bedd9', 'Inverted Row Under Table', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Inverted Row Under Table is a rowing exercise that builds thickness in your upper back. The biceps assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function.', '79291201', '79291201-Inverted-Row-under-Table-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Inverted Row Under Table', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ca7adfec-c932-430b-8eed-1d2d38de6e22', 'Seated Under Knee Clap (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Under Knee Clap On A Chair is a core movement exercise that primarily targets your abs. Being seated provides stability, allowing you to focus on the working muscles. Core strength is foundational for athletic performance and injury prevention.', '83051201', '83051201-Seated-Under-Knee-Clap-on-a-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction. This exercise is excellent for abs development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Under Knee Clap On A Chair', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ca7b261a-927a-4ddb-94ae-ccda74e45188', 'Bear Sit Kickout', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Bear Sit Kickout is a lower body kicking exercise that targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '82581201', '82581201-Bear-Sit-Kickout-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Set up in the starting position for Bear Sit Kickout. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Bear Sit Kickout', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ca8817e8-2fcd-4272-a852-30e8fe4685bf', 'Walking Knee Raise Sky Reach On Spot', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Walking Knee Raise Sky Reach On Spot (front Pov) ( is a core raising exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '92931201', '92931201-Walking-Knee-Raise-Sky-Reach-On-Spot-(front-POV)-(.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Raise the weight in front of you to shoulder height. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Cardio', 62, 5, 7, FALSE, TRUE, 'leg_raise', 'Walking Knee Raise Sky Reach On Spot  (', 'Walking Knee Raise Sky Reach On Spot (', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ca89792d-5e83-46df-81d9-7bed129b8399', 'Lying Hands On Side Upper Body Raise', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'The Lying Hands On Side Upper Body Raise is a lower body raising exercise that targets your delts. The upper back assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '95501201', '95501201-Lying-Hands-On-Side-Upper-Body-Raise-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie on your side with your body aligned. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lying Hands On Side Upper Body Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ca93896d-2ef0-4d1f-a3e4-8acd1456f045', 'Banded Wall Sit (Dumbbell)', 'Legs', 'Dumbbells, Wall', '{"Quads"}'::text[], '{"Glutes"}'::text[], 'Build stronger quads with this movement movement that develops leg drive and power. Secondary activation of your glutes provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '65581201', '65581201-Dumbbell-Banded-Wall-Sit-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Banded Wall Sit. 2. Position yourself at the appropriate distance from a wall. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'wall_sit', 'Banded Wall Sit', 'squat, leg_press, lunge', TRUE, 'dumbbell', TRUE, 3, 90, 4, 92, 90, 92, 90),
('ca977ae9-744a-462c-bb33-409c1b5d9918', 'Assisted Bulgarian Split Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '44421201', '44421201-Assisted-Bulgarian-Split-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Assisted Bulgarian Split Squat', 'split_squat, lunge, leg_press', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ca9d97de-c919-4adc-a04a-52ec82fb1d5f', 'Push Up (Resistance Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Resistance Band Push Up, an effective pushing movement for upper body strength. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The band creates increasing tension as it stretches, challenging the lockout. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '80891201', '80891201-Resistance-Band-Push-Up-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Push Up. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'push_up', 'Push Up', 'bench_press, chest_fly, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('ca9d9bb4-c7b1-40fb-b253-e2e2ce6f71b5', 'Atlas Swing (Kettlebell)', 'Core', 'Kettlebell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Kettlebell Atlas Swing, focusing on your abs. The kettlebell''s offset center of mass increases the stability challenge. Building core stability helps with everything from heavy deadlifts to daily activities.', '82931201', '82931201-Kettlebell-Atlas-Swing-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Select an appropriately weighted kettlebell for Kettlebell Atlas Swing. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Atlas Swing', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('caaf665c-54e0-416c-8dd1-979a08d8a458', 'Spin (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Dumbbell Spin, focusing on your abs. Dumbbells allow each arm to work independently, helping correct imbalances. Building core stability helps with everything from heavy deadlifts to daily activities.', '65071201', '65071201-Dumbbell-Spin_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Spin. 2. Set up in the starting position for Dumbbell Spin. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'cycling', 'Spin', 'running, elliptical, rowing_cardio', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('cab871ce-86e5-4b71-9b7c-6068d21350b3', 'Power Sled Push (Sled)', 'Legs', 'Sled', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pushing movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, calves working to support the movement. Leg training boosts metabolism and builds functional, real-world strength.', '44281201', '44281201-Power-Sled-Push-(male).mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Perform the concentric (lifting) phase explosively with maximum effort. 2. Set up in the starting position for Power Sled Push. 3. Execute the movement with proper form, focusing on your quads. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Power Sled Push', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cac6249c-704f-42bc-8880-d8efece6c204', 'Low Split Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '81041201', '81041201-Bodyweight-Low-Split-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears. Include this in your legs training.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Low Split Squat', 'lunge, bulgarian_split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cad36438-41c6-406f-bafc-8137fff2ddf5', 'Single Arm Snatch (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{"Quads","Shoulders"}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. You''ll also feel your quads, shoulders working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Full body exercises are time-efficient and build functional, real-world strength.', '57861201', '57861201-Dumbbell-One-Arm-Snatch-(female)_Weightlifting_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Explosively pull the weight from the floor/hang position. 3. As it rises, pull yourself under and catch it overhead with locked arms. 4. Stand to complete the lift. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 8, NULL, TRUE, NULL, 'Strength', 57, 7, 9, TRUE, FALSE, 'snatch', 'Single Arm Snatch', 'power_snatch, clean, overhead_press', FALSE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('cae3615c-9fbc-4213-908b-95a7abc91de5', 'Overhead Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build power and athleticism with this high-intensity raising exercise that challenges your entire body. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '87841201', '87841201-Overhead-Knee-Raise-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Raise the weight in the prescribed direction for Overhead Knee Raise. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Overhead Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('caec4a70-0d6c-4676-9144-498ae622f48a', 'Lying Hammer Press (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. The lying position provides back support and helps isolate the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '3401201', '03401201-Dumbbell-Lying-Hammer-Press_Chest-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Hammer Press. 2. Lie down in the appropriate position for Dumbbell Lying Hammer Press. 3. Use a hammer/neutral grip with palms facing each other throughout. 4. Lower the weight toward your chest with control. 5. Press the weight up until your arms are extended (don''t lock elbows). 6. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'squeeze_press', 'Lying Hammer Press', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('cb00b6a8-34a8-4fca-bca3-d9c57c0b4eab', 'Overhead Side Bend (Band)', 'Core', 'Resistance Band', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Your abs work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Building core stability helps with everything from heavy deadlifts to daily activities.', '72851201', '72851201-Band-Overhead-Side-Bend-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Overhead Side Bend. 2. Set up in the starting position for Band Overhead Side Bend. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'side_bend', 'Overhead Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('cb069c9d-37f0-4320-9e27-b472b73218da', 'Jump Twist', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'A challenging plyometric exercise, the Jump Twist builds reactive power and improves conditioning. The abs assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '59661201', '59661201-Jump-Twist-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Rotate your torso through the movement pattern for Jump Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'russian_twist', 'Jump Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('cb0d75c7-35c1-4db3-a02d-1ad200762150', 'Landmine Single Arm Press (Landmine)', 'Shoulders', 'Landmine Attachment, Barbell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Landmine Single Arm Press, an effective shoulder pressing exercise. Shoulder development enhances both performance and upper body aesthetics.', '107661201', '107661201-Landmine-Single-Arm-Press-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Start with the weight at shoulder level. 2. Press directly overhead until your arms are fully extended. 3. Lower back to shoulder level with control. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'arm_exercise', 'Landmine Single Arm Press', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('cb0e500e-24ee-4b78-ba69-da000c52d8d8', 'Neck Up Down Left Right', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'Strengthen your neck with this movement exercise for improved stability. This bodyweight exercise requires no equipment and can be done anywhere. Include this exercise in your routine for balanced strength development.', '56931201', '56931201-Neck-Up-Down-Left-Right-(female)_Neck_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Set up in the starting position for Neck Up Down Left Right. 2. Execute the movement with proper form, focusing on your neck. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'neck_exercise', 'Neck Up Down Left Right', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cb1b51c6-ebab-4c9c-92d3-90f3a3da34ac', 'Seated Chest Fly (Machine)', 'Chest', 'Fly Machine', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Lever Seated Fly, an effective flying movement for upper body strength. The front delts assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. The fixed path allows you to focus purely on muscular effort. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '5961201', '05961201-Lever-Seated-Fly_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Fly. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Lever Seated Fly', 'bench_press, incline_press, push_up', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('cb26f6fc-4804-4606-8542-3dd2ab57d032', 'Seated Overhead Stretch (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this stretching stretch that helps restore range of motion. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '91751201', '91751201-Sitting-Overhead-Stretch-on-a-Chair-(female)_Stret.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Overhead Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Overhead Stretch On A Chair', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cb303db9-e8c3-48c3-b33e-6793718e95b8', 'Seated Palms Up Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. Secondary activation of your forearms provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '4011201', '04011201-Dumbbell-Seated-Palms-Up-Wrist-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Palms Up Wrist Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'wrist_curl', 'Seated Palms Up Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('cb38d2e1-a554-4576-aca5-427f2efa92eb', 'Standing Arm Crossover And Elbow Pullback', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This pulling exercise focuses on your pectorals for improved chest strength and development. The front delts assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '94671201', '94671201-Standing-Arm-Crossover-And-Elbow-Pullback-(female).mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Arm Crossover And Elbow Pullback. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'chest_fly', 'Standing Arm Crossover And Elbow Pullback', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cb4f5d89-945c-4aa7-aad2-60fc2bad4ab9', 'Lying Elbow Swipes', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Elbow Swipes is a movement exercise that develops back strength and muscle. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function.', '73021201', '73021201-Lying-Elbow-Swipes-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Elbow Swipes. 2. Set up in the starting position for Lying Elbow Swipes. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Elbow Swipes', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cb66e30c-06f6-466a-aadc-2f8413d3f6ae', 'Ed Back Pulldown - Underhand (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Secondary activation of your biceps, upper back provides additional muscle engagement. Bands are joint-friendly and portable, perfect for any training environment. A strong back improves posture, prevents injury, and balances pressing movements. Quality repetitions are more important than quantity.', '107061201', '107061201-Band-Fixed-Back-Underhand-Pulldown-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Ed Back Underhand Pulldown. 2. Use an underhand (supinated) grip with palms facing up/toward you. 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Ed Back Underhand Pulldown', 'Ed Back Pulldown - Underhand', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('cb694677-21d3-4305-bee0-ade004914010', 'Countermovement Jump Arms On Hip', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity jumping exercise that challenges your entire body. You''ll also feel your quads, calves working to support the movement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '95141201', '95141201-Countermovement-Jump-Arms-on-Hip-(male)_Plyometric.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Set up in the starting position for Countermovement Jump Arms On Hip. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'glute_exercise', 'Countermovement Jump Arms On Hip', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('cb6abb35-8b3c-48f6-8e0d-fe3c817eab39', 'Weighted Standing Curl', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Weighted Standing Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '8531201', '08531201-Weighted-Standing-Curl_Forearms.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Stand with feet about shoulder-width apart. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'bicep_curl', 'Weighted Standing Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cb795354-a271-4692-865d-c810b69e6e62', 'Seated Windmill (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Windmill On Chair, focusing on your abs. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '90871201', '90871201-Sitting-Windmill-on-Chair-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'windmill', 'Seated Windmill On Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cb800781-5a17-457d-987f-a7a06664c600', 'Low Fly (Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Band Low Fly is a flying exercise that targets your chest muscles. You''ll also feel your front delts working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. A well-developed chest contributes to upper body strength and aesthetics.', '8981201', '08981201-Band-Low-Fly-(female)_Chest-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Low Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'chest_fly', 'Low Fly', 'bench_press, incline_press, push_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('cb828ba9-72b9-40ce-9429-62c01dcfe4ab', 'Hero Pose Virasana', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Hero Pose Virasana is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Include this in your routine for better mobility and reduced muscle tension.', '9541201', '09541201-Hero-Pose-Virasana-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Move into the stretch position for Hero Pose Virasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Hero Pose Virasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cb8e918d-7cb7-484d-a47e-6e0c7ac58d7f', 'Incline Press (Stability Ball, Dumbbell)', 'Chest', 'Dumbbells, Stability Ball, Incline Bench', '{"Upper Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Dumbbell Incline Press On Exercise Ball is a pressing exercise that targets your chest muscles. You''ll also feel your front delts, triceps working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12831201', '12831201-Dumbbell-Incline-Press-on-Exercise-Ball_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Press On Exercise Ball. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'incline_press', 'Incline Press On Exercise Ball', 'bench_press, shoulder_press, chest_fly', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('cb8ec990-decf-4f30-88d9-93be53dfb9e4', 'Knee Stand Kick Side Bend', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This stretch specifically works on your obliques, promoting flexibility and reducing muscle tightness. You''ll also feel your lats, lower back working to support the movement. Flexibility work like this enhances performance and prevents stiffness.', '83841201', '83841201-Knee-Stand-Kick-Side-Bend-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Move into the stretch position for Knee Stand Kick Side Bend. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', 'Knee Stand Kick Side Bend', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cb91c5cc-54ad-445f-b9c1-7f976ef65f27', 'Incline Bench Press - Reverse Grip (Barbell)', 'Chest', 'Barbell, Incline Bench', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Barbell Reverse Grip Incline Bench Press is a pressing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. Using a barbell provides stability for progressive overload. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12571201', '12571201-Barbell-Reverse-Grip-Incline-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 100, 7, 9, TRUE, FALSE, 'incline_press', 'Incline Bench Press - Reverse Grip', 'Incline Bench Press - Reverse Grip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('cb942842-d0ee-4d15-949d-5122169f2243', 'Bicep Curl (Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. The band creates increasing tension as it stretches, challenging the lockout. Dedicated arm training builds both strength and muscular definition.', '70421201', '70421201-Band-Standard-Biceps-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Standard Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standard Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('cb997310-509f-4c1c-afda-5ce89a5edf93', 'Lying Frog Push', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Frog Push is a lower body pushing exercise that targets your core. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '89301201', '89301201-Lying-Frog-Push-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Frog Push. 2. Set up in the starting position for Lying Frog Push. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Frog Push', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cb9a2add-3cab-476b-99bd-b2a64721f735', 'Arm Double Crossover', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your chest with the Arm Double Crossover, an effective movement movement for upper body strength. You''ll also feel your front delts working to support the movement. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '88831201', '88831201-Arm-Double-Crossover-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Set up in the starting position for Arm Double Crossover. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, 'Pull', 'Isolation', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, 'Neutral', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Arm Double Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cbab3c3e-d39f-48a9-8887-e5f0340905ad', 'Reverse Crunch (Resistance Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Resistance Band Reverse Crunch is a core crunching exercise that primarily targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Building core stability helps with everything from heavy deadlifts to daily activities.', '64191201', '64191201-Resistance-Band-Reverse-Crunch-(VERSION-2)-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Secure the resistance band appropriately for Resistance Band Reverse Crunch. 2. Lift your hips off the floor by contracting your lower abs. 3. Bring your knees toward your chest, then lower with control. 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'crunch', 'Reverse Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('cbac6e98-05bb-4f33-9826-eb78b6dfbf3e', 'Seated Curl To Shoulders Press (Chair)', 'Shoulders', 'Chair', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your biceps. Secondary activation of your forearms provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Strong shoulders improve overhead strength and support nearly all upper body movements.', '104801201', '104801201-Seated-Curl-to-Shoulders-Press-on-Chair-(male)_Sh.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'leg_curl', 'Seated Curl To Shoulders Press On Chair', 'romanian_deadlift, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cbbbca4e-c0b1-4a8f-92cf-01aa8c101aed', 'Triceps Kickback - Neutral Grip (Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'This kicking movement isolates your triceps for improved arm development. Your hamstrings work as secondary movers, adding to the training stimulus. The band creates increasing tension as it stretches, challenging the lockout. Dedicated arm training builds both strength and muscular definition.', '104051201', '104051201-Band-Triceps-Neutral-grip-Kickback_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Secure the resistance band appropriately for Band Triceps Neutral Grip Kickback. 2. Use a neutral grip with palms facing each other. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Triceps Kickback - Neutral Grip', 'Triceps Kickback - Neutral Grip', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('cbbec74b-4eab-4eaf-870e-07581d6257ab', 'Kneeling Triceps Extension (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Cable Kneeling Triceps Extension targets your triceps through a extension motion. The kneeling position adds a core stability challenge. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '1761201', '01761201-Cable-Kneeling-Triceps-Extension_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Triceps Extension. 2. Kneel on the floor (use a pad for comfort if needed). 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'tricep_extension', 'Kneeling Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('cbc26964-035a-40c4-80c2-b94e68a4532c', 'Single Arm Reverse Fly (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This flying exercise works your rear delts for improved shoulder strength and aesthetics. Secondary activation of your upper back provides additional muscle engagement. Cables provide constant tension throughout the full range of motion. Shoulder development enhances both performance and upper body aesthetics.', '41221201', '41221201-Cable-One-Arm-Reverse-Fly-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Reverse Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'rear_delt', 'Single Arm Reverse Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('cbc602ea-e938-44e6-bc39-07fb85783ca7', 'Straight Legs Sit Up Toe Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Secondary activation of your hip flexors provides additional muscle engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '72151201', '72151201-Straight-Legs-Sit-up-Toe-Tap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Set up in the starting position for Straight Legs Sit Up Toe Tap. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Straight Legs Sit Up Toe Tap', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cbf2e856-f98c-4147-aa47-b6cb98628531', 'Standing Back Wrist Curl (Barbell)', 'Arms', 'Barbell', '{"Forearms"}'::text[], '{}'::text[], 'The Barbell Standing Back Wrist Curl strengthens your forearms and grip through a curling motion. The forearms assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Barbells enable bilateral loading for building raw strength. Dedicated arm training builds both strength and muscular definition.', '1041201', '01041201-Barbell-Standing-Back-Wrist-Curl_Forearms.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Back Wrist Curl. 2. Stand with feet about shoulder-width apart. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', 'Isolation', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Overhand', 'Narrow', 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'wrist_curl', 'Standing Back Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('cc0a1742-0067-4325-9d17-d6cd456a2168', 'Pistol Squat (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes provides additional muscle engagement. Kettlebells are excellent for building functional, real-world strength. Strong legs are the foundation for athletic performance and functional fitness.', '5441201', '05441201-Kettlebell-Pistol-Squat-(male)_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Select an appropriately weighted kettlebell for Kettlebell Pistol Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'pistol_squat', 'Pistol Squat', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('cc150c96-7a79-46d6-98bf-ffb6da4e115f', 'Standing Double Opposite Vertical Open And Double', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Compound movements like this develop coordination, power, and overall fitness.', '94181201', '94181201-Standing-Double-Opposite-Vertical-Open-and-Double-.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Double Opposite Vertical Open And Double. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Double Opposite Vertical Open And Double', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cc22d74b-e8fd-4d52-8fc2-7f30229e7876', 'High Row - Narrow Grip (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps, rear delts provides additional muscle engagement. Resistance bands provide accommodating resistance that increases through the range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '41471201', '41471201-Band-Narrow-Grip-High-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Secure the resistance band appropriately for Band Narrow Grip High Row. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'close_grip_bench', 'High Row - Narrow Grip', 'High Row - Narrow Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('cc25ff7f-5585-4e8b-8df9-0c7445a74b74', 'Kneeling Knuckle Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '65941201', '65941201-Kneeling-Knuckle-Push-Up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Kneeling Knuckle Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cc2b85b1-5c1a-4720-95be-eeec79768ac2', 'Standing Lateral Raise (Bent Arms)', 'Shoulders', 'Bodyweight', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '87461201', '87461201-Standing-Lateral-Raise-(Bent-Arms)-(female)_Should.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'lateral_raise', 'Standing Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cc341ee0-7cf3-4b84-81e5-9b0615eb3024', 'Prone Triceps Kickback (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'This kicking movement isolates your triceps for improved arm development. You''ll also feel your hamstrings working to support the movement. Performing this lying down removes momentum for stricter form. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '49611201', '49611201-Dumbbell-Prone-Triceps-Kickback_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Prone Triceps Kickback. 2. Lie face down (prone position) for Dumbbell Prone Triceps Kickback. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Prone Triceps Kickback', 'tricep_pushdown, tricep_extension', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('cc3da17f-4fd8-4763-8ebb-e90616047684', 'Sled 45 Degrees Narrow Stance Leg Press (Machine)', 'Legs', 'Leg Press Machine', '{"Quads"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target the front of your thighs with this pressing exercise for quad development. Your glutes work as secondary movers, adding to the training stimulus. Strong legs are the foundation for athletic performance and functional fitness.', '36161201', '36161201-Sled-45-degrees-Narrow-Stance-Leg-Press-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Use a close/narrow grip (hands closer than shoulder-width). 2. Position your feet on the platform and release the safety. 3. Lower the weight by bending your knees, then press back up powerfully. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 80, 7, 9, TRUE, FALSE, 'leg_press', 'Sled 45 Degrees Narrow Stance Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('cc3e72c4-d71b-48fa-8088-8820840718cc', 'Good Morning Row', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'This rowing movement works your hamstrings for balanced leg development. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '58401201', '58401201-Bodyweight-Good-Morning-Row-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'back_extension', 'Good Morning Row', 'romanian_deadlift, back_extension, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cc5be970-0111-4898-8b01-613d85cc09b5', 'Incline Leg Hip Raise (leg Straight)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Using an incline changes the angle of resistance for varied muscle recruitment. Core strength is foundational for athletic performance and injury prevention.', '4911201', '04911201-Incline-Leg-Hip-Raise-(leg-straight)_waist.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Set up in the starting position for Incline Leg Hip Raise. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 73, 5, 7, FALSE, TRUE, 'leg_exercise', 'Incline Leg Hip Raise', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cc6ddfc9-7382-449a-9090-1ec013b4db84', 'Seated Prayer Chest Squeeze (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{"Triceps"}'::text[], 'The Seated Prayer Chest Squeeze On A Chair is a movement exercise that targets your chest muscles. Your triceps work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. A well-developed chest contributes to upper body strength and aesthetics.', '82001201', '82001201-Sitting-Prayer-Chest-Squeeze-on-a-Chair-(male)_Che.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 20, 7, 8, TRUE, TRUE, 'chest_exercise', 'Seated Prayer Chest Squeeze On A Chair', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cc6fecf0-7bd2-467f-bbaa-e01adb0ec10a', 'Bent Knee Lying Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This twisting exercise engages your abs for improved core stability and strength. Secondary activation of your abs provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '1321201', '01321201-Bent-knee-Lying-Twist-(female)_Waist-FIX2_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Lie down in the appropriate position for Bent Knee Lying Twist. 2. Rotate your torso through the movement pattern for Bent Knee Lying Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Bent Knee Lying Twist', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cc84703b-06ac-4b29-a25f-d9acd039098a', 'Y Lateral Raise (TRX)', 'Shoulders', 'TRX', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. The TRX allows you to adjust difficulty by changing your body angle. Strong shoulders improve overhead strength and support nearly all upper body movements.', '11071201', '11071201-Suspender-Y-Lateral-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Y Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'lateral_raise', 'Suspender Y Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('cc85544e-3f35-458f-b4f5-21b38e06c5ff', 'Upright Row (Smith Machine)', 'Shoulders', 'Smith Machine', '{Deltoids}'::text[], '{"Traps","Front Delts"}'::text[], 'Build stronger shoulders with this rowing movement focusing on your delts. Your traps work as secondary movers, adding to the training stimulus. The machine guides your movement path for safer, more controlled repetitions. Strong shoulders improve overhead strength and support nearly all upper body movements.', '7751201', '07751201-Smith-Upright-Row_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Upright Row. 2. Pull the weight straight up along your body, leading with your elbows. 3. Raise until elbows reach shoulder height, then lower with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'upright_row', 'Smith Upright Row', 'Upright Row', FALSE, 'barbell', FALSE, 4, 120, 4, 80, 75, 20, 88),
('cc887ec3-6d53-43b8-b870-d2a5630e9ab0', 'Single Leg Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '37661201', '37661201-Dumbbell-Single-Leg-Squat-(VERSION-2)-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'pistol_squat', 'Single Leg Squat', 'squat, bench_press, deadlift', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('cc949ec9-cf37-4017-9433-96b30626b2c2', 'Single Leg Split Squat (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '26701201', '26701201-Smith-Single-Leg-Split-Squat-(female)_Thighs-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Single Leg Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 88, 7, 9, TRUE, FALSE, 'split_squat', 'Smith Single Leg Split Squat', 'Single Leg Split Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('cc9df54f-a81b-4e20-8134-7c45906a7302', 'Roll Foot', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Roll Foot is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '54421201', '54421201-Roll-Foot-(female)_Feet_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Move into the stretch position for Roll Foot. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Engage your stabilizer muscles for better control. Ideal for full body strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Roll Foot', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ccac54fa-7ad2-475b-a7a6-174cdf7819df', 'Standing One Side Side Crunch And Raise', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Standing One Side Side Crunch And Raise builds reactive power and improves conditioning. You''ll also feel your abs working to support the movement. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '93501201', '93501201-Standing-One-Side-Side-Crunch-and-Raise-(female)_P.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Standing One Side Side Crunch And Raise', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ccbe0b56-beae-4101-b2d1-7f7ff8446191', 'Kneeling Single Slow Kickback', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Rear Delts"}'::text[], 'The Kneeling Single Slow Kickback is a hip-dominant kicking exercise that targets your glutes. Your hamstrings work as secondary movers, adding to the training stimulus. The kneeling position adds a core stability challenge. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '73471201', '73471201-Kneeling-Single-Slow-Kickback-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Use a slow, controlled tempo throughout the entire range of motion. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Kneeling Single Slow Kickback', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ccc18ffc-69f5-4e98-8e20-08296834b549', 'Weight Shift Side Punch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Your shoulders work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '92611201', '92611201-Weight-Shift-Side-Punch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Weight Shift Side Punch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Weight Shift Side Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cccc4b51-4d0f-452f-b9c0-5ee8f001fd4d', 'Standing Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Elevate your training with this raising exercise that develops speed, power, and coordination. Secondary activation of your hip flexors provides additional muscle engagement. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '57431201', '57431201-Standing-Knee-Raise-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Raise the weight in the prescribed direction for Standing Knee Raise. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Standing Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cccebb43-8ad5-4b83-a2e1-7391f0d079fd', 'Seated Figure 4 Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target your glutes with this stretching stretch that helps restore range of motion. Your hips work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Include this in your routine for better mobility and reduced muscle tension.', '90651201', '90651201-Seated-Figure-4-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Figure 4 Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Figure 4 Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('ccd263e8-162d-4f3b-969a-35bd9adcaa83', 'Low Windmill (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Dumbbells allow each arm to work independently, helping correct imbalances. Building core stability helps with everything from heavy deadlifts to daily activities.', '47461201', '47461201-Dumbbell-Low-Windmill_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Low Windmill. 2. Set up in the starting position for Dumbbell Low Windmill. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'windmill', 'Low Windmill', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('ccda5a3a-b03e-42f5-9f32-7ddc78e69993', 'Standing Single Leg Concentration Calf Raise', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts. This is a great exercise for all fitness levels with proper scaling.', '105481201', '105481201-Standing-Single-Leg-Concentration-Calf-Raise-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Stand tall with your feet firmly planted. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Single Leg Concentration Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cce40fbe-9f7a-405c-bf1a-4a5900ff94fa', 'Standing Up Straight Crossovers (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Cable Standing Up Straight Crossovers is a movement exercise that targets your chest muscles. The front delts assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Cables provide constant tension throughout the full range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '23871201', '23871201-Cable-Standing-Up-Straight-Crossovers-(female)_Che.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Up Straight Crossovers. 2. Begin in a standing position with good posture. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'chest_fly', 'Standing Up Straight Crossovers', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('ccfbbf46-f531-4812-b53b-5aba3040639d', 'Front And Side Knee Drive', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities. Aim for full range of motion on every rep.', '61731201', '61731201-Front-and-Side-Knee-Drive-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up in the starting position for Front And Side Knee Drive. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Front And Side Knee Drive', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cd077124-bda5-4667-9dfc-626961c0b01b', 'Glute Bridge Abduction (Against Wall)', 'Legs', 'Wall', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Glute Bridge Abduction Against Wall is a hip-dominant bridging exercise that targets your glutes. Your hamstrings work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '74911201', '74911201-Glute-Bridge-Abduction-against-Wall-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself at the appropriate distance from a wall. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Abduction Against Wall', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cd0a14e5-3033-4a20-93a5-e954c578d9d4', 'Power Clean', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'This full-body movement exercise challenges multiple muscle groups simultaneously. The quads, glutes, traps assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Compound movements like this develop coordination, power, and overall fitness.', '6481201', '06481201-Power-Clean_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Explosively pull the weight upward from the starting position. 2. Pull yourself under the weight and catch it at shoulder level. 3. Stand to complete the lift, then lower with control. 4. Perform the concentric (lifting) phase explosively with maximum effort. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'clean', 'Power Clean', 'clean, hang_clean, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cd16a86c-aba1-4538-9506-aa1abe55820c', 'Jump Lunge To Feet Jack', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Aim for full range of motion on every rep.', '5101201', '05101201-Jump-Lunge-To-Feet-Jack-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form. An effective movement for your cardio routine.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'lunge_jump', 'Jump Lunge To Feet Jack', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('cd176a26-b896-4281-9424-c4e4016cc919', 'Standing Elbow Raise And Squeeze', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'This raising exercise works your delts for improved shoulder strength and aesthetics. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '94241201', '94241201-Standing-Elbow-Raise-and-Squeeze-(female)_Shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Raise the weight in the prescribed direction for Standing Elbow Raise And Squeeze. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'general_exercise', 'Standing Elbow Raise And Squeeze', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cd19d618-74f0-4fc1-8e90-c4b08474e540', 'Elbow Lift To Prayer Push', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this pushing movement focusing on your delts. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '55711201', '55711201-Elbow-Lift-to-Prayer-Push-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Set up in the starting position for Elbow Lift To Prayer Push. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'boxing', 'Elbow Lift To Prayer Push', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cd1fcf4d-6f5a-4683-b515-703705464e23', 'Marching On Spot Press', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Marching On Spot Press builds reactive power and improves conditioning. The hip flexors assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '88321201', '88321201-Marching-on-Spot-Press-(VERSION-2)-(female)_Plyome.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Execute the pressing motion for Marching On Spot Press, extending through the target muscles. 2. Set up in the starting position for Marching On Spot Press. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'marching', 'Marching On Spot Press', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cd29377d-431d-449a-8606-53e45e59eb8c', 'Child Pose Cat Cow', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Target your back with this movement stretch that helps restore range of motion. The hips assist throughout the movement, making this a well-rounded exercise. Include this in your routine for better mobility and reduced muscle tension.', '82171201', '82171201-Child-Pose-Cat-Cow-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Move into the stretch position for Child Pose Cat Cow. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Child Pose Cat Cow', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cd2b02ac-4aa4-4c19-85ff-4c32e15b7dde', 'Single Arm Floor Fly (Dumbbell)', 'Chest', 'Dumbbells', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Dumbbell One Arm Floor Fly is a flying exercise that targets your chest muscles. The front delts assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '97501201', '97501201-Dumbbell-One-Arm-Floor-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Position yourself on the floor for Dumbbell One Arm Floor Fly. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'chest_fly', 'Single Arm Floor Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('cd2ba109-65d3-45c9-98a1-b6429952208c', 'Single Straight Leg Glute Bridge Hold (left)', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength. Keep your core engaged throughout the exercise.', '60011201', '60011201-Single-Straight-Leg-Glute-Bridge-Hold-(left)-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Hold the position for the prescribed time, maintaining tension. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Single Straight Leg Glute Bridge Hold', 'deadlift, leg_curl, hip_thrust', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('cd389f15-4a30-4349-a6e8-ce7f6e79bd9c', 'Rear Deltoid Stretch', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build stronger shoulders with this stretching movement focusing on your rear delts. You''ll also feel your upper back working to support the movement. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '6691201', '06691201-Rear-Deltoid-Stretch_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Set up in the starting position for Rear Deltoid Stretch. 2. Execute the movement with proper form, focusing on your rear delts. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'rear_delt', 'Rear Deltoid Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cd58ece0-e1ab-4762-a4a7-95e164f0b4f0', 'Half Kneeling Glute Stretch', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this stretching movement that emphasizes the glutes. Kneeling helps eliminate lower body momentum from the movement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '69731201', '69731201-Half-Kneeling-Glute-Stretch-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Get into a half-kneeling position (one knee down, opposite foot forward). 2. Set up in the starting position for Half Kneeling Glute Stretch. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'glute_stretch', 'Half Kneeling Glute Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cd5a8cf8-0286-45e4-98ec-a1702b4c33c7', 'Scissors', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Aim for full range of motion on every rep.', '28621201', '28621201-Scissors-(female)_Pilates.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Move into the stretch position for Scissors. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Scissors', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cd5c078e-76ff-4b2f-868d-10987eb92ea0', 'Crawl Switch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Crawl Switch, focusing on your abs. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '75951201', '75951201-Crawl-Switch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Set up in the starting position for Crawl Switch. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Crawl Switch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cd6726b8-fb2f-44a9-9be6-a3d0551fb31f', 'Half Kneeling Torso Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Half Kneeling Torso Twist targets your obliques through a twisting motion, building rotational core strength. The abs assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '105661201', '105661201-Half-Kneeling-Torso-Twist-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Get into a half-kneeling position (one knee down, opposite foot forward). 2. Rotate your torso through the movement pattern for Half Kneeling Torso Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Half Kneeling Torso Twist', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cd6bb2c3-926c-4a1e-a1f2-ad023b22ed86', 'Long Plank (Against Wall)', 'Core', 'Wall', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. Core strength is foundational for athletic performance and injury prevention.', '74471201', '74471201-Long-Plank-against-Wall-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Position yourself at the appropriate distance from a wall. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'plank', 'Long Plank Against Wall', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('cd859041-e755-43ab-afd0-6e65b715b7fa', 'Pendulum Squat (Machine)', 'Legs', 'Lever Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '57781201', '57781201-Lever-Pendulum-Squat-(plate-loaded)-(female)_Thigh.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Pendulum Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'squat', 'Lever Pendulum Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('cd8fa76f-21fc-46df-bbc0-0c0551438541', 'Bench Press - Close Grip (Smith Machine)', 'Chest', 'Smith Machine, Flat Bench', '{Triceps}'::text[], '{"Front Delts"}'::text[], 'Build stronger triceps with this pressing exercise for bigger arms. You''ll also feel your chest working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Dedicated arm training builds both strength and muscular definition.', '7511201', '07511201-Smith-Close-Grip-Bench-Press_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Close Grip Bench Press. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'close_grip_bench', 'Smith Bench Press - Close Grip', 'Bench Press - Close Grip', FALSE, 'smith_machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('cd90023f-4ef5-42b8-8514-33f17fe75bae', 'Seated Side To Side Bend (Stick)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The abs assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. A strong core improves posture, protects your spine, and enhances all other lifts.', '103541201', '103541201-Stick-Sitting-Side-to-Side-Bend-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Stick Seated Side To Side Bend. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', 'Stick Seated Side To Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cda090dc-b863-4b11-9eb7-bf5b35ee074c', 'Overhead Slam (Medicine Ball)', 'Full Body', 'Medicine Ball', '{"Full Body"}'::text[], '{"Core","Lats"}'::text[], 'Develop functional strength with the Medicine Ball Overhead Slam, a comprehensive movement exercise. Secondary activation of your core, lats provides additional muscle engagement. Compound movements like this develop coordination, power, and overall fitness.', '25451201', '25451201-Medicine-Ball-Overhead-Slam-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Overhead Slam. 2. Set up in the starting position for Medicine Ball Overhead Slam. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Medicine Ball Overhead Slam', 'squat, bench_press, deadlift', FALSE, 'medicine_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cdba06a3-1d96-41d6-8d65-819e348e9530', 'Side Lunge Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Designed to lengthen your quads, the Side Lunge Stretch helps improve mobility and prevent stiffness. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '87761201', '87761201-Side-Lunge-Stretch-(VERSION-2)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Side Lunge Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 6. Switch sides and repeat for equal time. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'hip_stretch', 'Side Lunge Stretch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cdbc97e0-0a98-4a51-b183-afbf07038d20', 'Feet And Ankles Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted stretching exercise. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts. Aim for full range of motion on every rep.', '42821201', '42821201-Feet-and-Ankles-Stretch-(male)_Calves.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Set up in the starting position for Feet And Ankles Stretch. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Feet And Ankles Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cdc60e78-60e0-4e5f-8ab7-4abdbc09f58d', 'Half Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '71801201', '71801201-Bodyweight-Half-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Maintain consistent tempo throughout the set. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Half Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cdcd861b-5686-4f4e-b5bc-b2a9f2f3c05d', 'Leg Raise - Alternating', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Alternate Leg Raise is a lower body raising exercise that targets your abs. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '16131201', '16131201-Alternate-Leg-Raise-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Alternate between sides/arms/legs with each repetition. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Leg Raise - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cdf361e0-452b-43d2-bde2-382757502b0e', 'Bent Over Row (Smith Machine)', 'Back', 'Smith Machine', '{Latissimus Dorsi}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps, lats provides additional muscle engagement. Bending over allows gravity to provide resistance in a different plane. Machine exercises are great for isolating muscles and training to failure safely. Back development is crucial for pulling strength and overall upper body function.', '7621201', '07621201-Smith-Bent-Over-Row-(VERSION-2)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'bent_over_row', 'Smith Bent Over Row', 'Bent Over Row', FALSE, 'barbell', FALSE, 4, 120, 4, 80, 75, 20, 88),
('cdf3c5da-542e-44f5-9536-0c9848c7b992', 'Head To Knee Janu Sirsasana Yoga Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Progress gradually by increasing resistance over time.', '67161201', '67161201-Head-To-Knee-Janu-Sirsasana-Yoga-Pose-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Move into the stretch position for Head To Knee Janu Sirsasana Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Head To Knee Janu Sirsasana Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cdfa34cd-c45f-4e93-a30e-337097ca6b66', 'Thruster (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Quads","Glutes"}'::text[], '{"Traps","Shoulders"}'::text[], 'Target your delts with the Kettlebell Thruster, an effective shoulder thrusting exercise. You''ll also feel your quads, shoulders working to support the movement. The kettlebell grip position adds a unique training stimulus. Shoulder development enhances both performance and upper body aesthetics.', '5501201', '05501201-Kettlebell-Thruster_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Select an appropriately weighted kettlebell for Kettlebell Thruster. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'thruster', 'Thruster', 'front_squat, shoulder_press, clean', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('ce056915-2ced-43cc-af59-f5c16a6a8349', 'Diamond Push Up (On Knees)', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing movement isolates your triceps for improved arm development. The chest assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Arm strength supports grip, pulling, and pushing in compound movements.', '11741201', '11741201-Diamond-Push-up-(on-knees)_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Keep the movement smooth and controlled. This exercise is excellent for triceps development.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Diamond Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ce1818e3-8b1a-496b-b626-31c85b268ac9', 'Criss Cross Arms Prayer Push', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'Build power and athleticism with this high-intensity pushing exercise that challenges your entire body. You''ll also feel your shoulders, core working to support the movement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '76391201', '76391201-Criss-Cross-Arms-Prayer-Push-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set up in the starting position for Criss Cross Arms Prayer Push. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'boxing', 'Criss Cross Arms Prayer Push', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ce2cafc8-caec-4b12-9f69-aa9bf77fdfbc', 'Seated Lotus Dynamic Side Stretch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Lotus Dynamic Side Stretch, focusing on your abs. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '61291201', '61291201-Sitting-Lotus-Dynamic-Side-Stretch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Lotus Dynamic Side Stretch. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'lat_stretch', 'Seated Lotus Dynamic Side Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('ce2ea809-af4f-4dd3-8b33-9601785aa6dd', 'Bent Over Face Pull (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Build stronger shoulders with this pulling movement focusing on your delts. Your upper back, rotator cuff work as secondary movers, adding to the training stimulus. The bent over position requires core engagement to maintain a neutral spine. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '56651201', '56651201-Dumbbell-Bent-Over-Face-Pull_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bent Over Face Pull. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the rope toward your face, separating your hands as you pull. 4. Squeeze your rear delts and upper back at peak contraction. 5. Return with control, maintaining cable tension. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'face_pull', 'Bent Over Face Pull', 'rear_delt_fly, bent_over_row, lateral_raise', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('ce318061-e7f5-4df8-9e0c-0e4b4d350a80', 'Twist Side (TRX)', 'Core', 'TRX', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Suspender Twist Side targets your obliques through a twisting motion, building rotational core strength. Secondary activation of your abs provides additional muscle engagement. The TRX allows you to adjust difficulty by changing your body angle. Building core stability helps with everything from heavy deadlifts to daily activities.', '11511201', '11511201-Suspender-Twist-Side-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Twist Side. 2. Rotate your torso through the movement pattern for Suspender Twist Side. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 40, 5, 7, FALSE, TRUE, 'russian_twist', 'Suspender Twist Side', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('ce4f6c7f-051c-49c1-9887-506bb9b2e2f6', 'Elbow Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger core with the Elbow Push Up, focusing on your abs. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '32661201', '32661201-Elbow-Push-up-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set. Ideal for abs strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Elbow Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ce57dfb7-8ef2-4866-8af1-b0663237d462', 'Flexion Leg Sit Up (Straight Arm)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Flexion Leg Sit Up (straight Arm), focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '42841201', '42841201-Flexion-Leg-Sit-up-(straight-arm)-(female)_waist.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Set up in the starting position for Flexion Leg Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Flexion Leg Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ce60fbae-88e8-487e-8dd2-bca647c053f8', 'Elevated Pike Push Up From Deficit With Parallett (Step Platform)', 'Chest', 'Step Platform', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps, front delts working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics. Can be modified for beginners or progressed for advanced athletes.', '77491201', '77491201-Elevanted-Pike-Push-up-from-deficit-with-parallett.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Elevanted Pike Push Up From Deficit With Parallett', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('ce804363-6e31-475b-8c79-1c7e92d48bd2', 'Reverse Fly Wake Up (TRX)', 'Shoulders', 'TRX', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build balanced shoulders by working the posterior delts with this flying exercise. Your upper back work as secondary movers, adding to the training stimulus. Suspension training adds instability, increasing core activation throughout. A strong back improves posture, prevents injury, and balances pressing movements.', '11301201', '11301201-Suspender-Reverse-Fly-Wake-up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Reverse Fly Wake Up. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'rear_delt', 'Suspender Reverse Fly Wake Up', 'bench_press, incline_bench_press, push_up', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('ce80a6ae-979d-495d-ab03-d795e934a882', 'Horizontal Pallof Press (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Cable Horizontal Pallof Press is a core pressing exercise that primarily targets your abs. Cable resistance creates smooth, continuous muscle engagement. Building core stability helps with everything from heavy deadlifts to daily activities.', '12021201', '12021201-Cable-horizontal-Pallof-Press_waist.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Adjust the cable machine to the correct height and attachment for Cable Horizontal Pallof Press. 2. Execute the pressing motion for Cable Horizontal Pallof Press, extending through the target muscles. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'pallof_press', 'Horizontal Pallof Press', 'woodchop, plank, dead_bug', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('ce82345a-9dca-4daf-82fe-7550ae62b25e', 'Wide Pulldown - Neutral Grip (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function. Start with lighter weight to master the movement pattern.', '93041201', '93041201-Cable-Neutral-Grip-Wide-Pulldown-(VERSION-3)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Adjust the cable machine to the correct height and attachment for Cable Neutral Grip Wide Pulldown. 2. Use a wide grip (wider than shoulder-width) for this variation. 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Wide Pulldown - Neutral Grip', 'Wide Pulldown - Neutral Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('ce82aca8-12c8-4292-a63c-87bf741e1433', 'Seated Leg Raise Crunch (Machine)', 'Core', 'Ab Machine', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Your hip flexors work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. The machine guides your movement path for safer, more controlled repetitions. Building core stability helps with everything from heavy deadlifts to daily activities.', '36471201', '36471201-Lever-Seated-Leg-Raise-Crunch-(plate-loaded)-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Leg Raise Crunch. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'leg_raise', 'Lever Seated Leg Raise Crunch', 'crunch, plank, v_up', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('ce87a4c0-be46-476f-88eb-fda98872823f', 'Deadlift From Deficit (Trap Bar)', 'Back', 'Trap Bar, Step Platform', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Trap Bar Deadlift From Deficit is a lower body hip hinge exercise that targets your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. Lower body strength improves everything from walking to heavy compound lifts.', '41051201', '41051201-Trap-Bar-Deadlift-from-Deficit-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Hinge at hips and bend knees to grip the weight. 2. Drive through your heels, extending hips and knees to stand. 3. Lower by reversing the movement with control. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'deadlift', 'Deadlift From Deficit', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('ce962037-eb99-4e7f-880c-4fd92cea6583', 'Crunch (Straight Leg Up)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts. Progress gradually by increasing resistance over time.', '2731201', '02731201-Crunch-(straight-leg-up)-(female)_waist.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Ensure full range of motion on each rep. Include this in your core training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Crunch', 'deadlift, leg_curl, hip_thrust', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ce9ed727-a3fc-4a66-854d-f5a5665bf497', 'Sideway Leg Lift (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your hip abductors. Lower body strength improves everything from walking to heavy compound lifts.', '84191201', '84191201-Sideway-Leg-Lift-with-a-Chair-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Sideway Leg Lift With A Chair. 3. Execute the movement with proper form, focusing on your hip abductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'side_bend', 'Sideway Leg Lift With A Chair', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cea1a572-4c26-41ce-ba64-5d49c37c7cbe', 'Standing Arm Rotation', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build a stronger back with this rotation movement targeting your full body. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '94041201', '94041201-Standing-Arm-Rotation-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Rotate your torso through the movement pattern for Standing Arm Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Arm Rotation', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cea598b3-46bd-4c27-8cf2-d583b6a45388', 'Roll Chest Lying On Floor', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this movement movement that develops pressing power. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '54161201', '54161201-Roll-Chest-Lying-on-Floor-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Chest Lying On Floor. 2. Lie down in the appropriate position for Roll Chest Lying On Floor. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'chest_exercise', 'Roll Chest Lying On Floor', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cec331ef-1ca9-4225-95c1-f4fe947b907c', 'Paused Bent Over Row (Barbell)', 'Back', 'Barbell', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, lats assist throughout the movement, making this a well-rounded exercise. The bent over position requires core engagement to maintain a neutral spine. The barbell allows you to handle heavier loads for maximum strength gains. Back development is crucial for pulling strength and overall upper body function.', '55781201', '55781201-Barbell-Paused-Bent-Over-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Grip a barbell with hands at the appropriate width for Barbell Paused Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Pause for 1-3 seconds at the bottom or peak of the movement before continuing. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'bent_over_row', 'Paused Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('cec84a8e-1ff7-46b5-b40c-426495d52c92', 'Diagonal Pick And Carry (woodchop)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Diagonal Pick And Carry (woodchop) targets your obliques through a movement motion, building rotational core strength. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '89041201', '89041201-Diagonal-Pick-and-Carry-(Woodchop)-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Set up in the starting position for Diagonal Pick And Carry. 2. Execute the movement with proper form, focusing on your obliques. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'woodchop', 'Diagonal Pick And Carry', 'russian_twist, pallof_press, cable_crunch', FALSE, 'bodyweight', TRUE, 3, 60, 4, 70, 88, 95, 65),
('cec8fe85-722c-4703-9796-6ed84b2f1bb6', 'Decline Sit Up (Band)', 'Core', 'Resistance Band, Decline Bench', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Declining shifts the emphasis to hit the muscles from a different angle. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '38401201', '38401201-Band-Decline-Sit-up-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Decline Sit Up. 2. Set up in the starting position for Band Decline Sit Up. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', 'Sit Up', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'crunch', 'Decline Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('cedfa19a-9ecd-49c5-9e9d-175cc0462819', 'Single Leg Split Squat With Low Box (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The kettlebell''s offset center of mass increases the stability challenge. Leg training boosts metabolism and builds functional, real-world strength.', '72401201', '72401201-Kettlebell-Single-Leg-Split-Squat-with-Low-Box_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Select an appropriately weighted kettlebell for Kettlebell Single Leg Split Squat With Low Box. 2. Set up a box or step platform at the appropriate height. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 88, 7, 8, TRUE, TRUE, 'split_squat', 'Single Leg Split Squat With Low Box', 'lunge, bulgarian_split_squat, squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('cef54ccc-38bc-45ec-8e46-febac8017fcb', 'Lying Rectus Abdominis Activation Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Rectus Abdominis Activation Crunch, focusing on your abs. You''ll also feel your hip flexors working to support the movement. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '67521201', '67521201-Lying-Rectus-Abdominis-Activation-Crunch-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Rectus Abdominis Activation Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'dynamic_warmup', 'Lying Rectus Abdominis Activation Crunch', 'plank, leg_raise, russian_twist, sit_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cefce744-8e9b-48ce-84b9-500663001e66', 'Incline Twisted Fly (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{"Abs"}'::text[], 'Target your chest with the Dumbbell Incline Twisted Fly, an effective flying movement for upper body strength. The abs assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '101721201', '101721201-Dumbbell-Incline-Twisted-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Twisted Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'russian_twist', 'Incline Twisted Fly', 'incline_bench_press, chest_fly, shoulder_press', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('cf041685-ddb0-4351-82e8-ac25f3c5de72', 'Lying Legs Extension Toes Flexion', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Legs Extension Toes Flexion is a lower body extension exercise that targets your core. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '95201201', '95201201-Lying-Legs-Extension-Toes-Flexion-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Legs Extension Toes Flexion. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_exercise', 'Lying Legs Extension Toes Flexion', 'leg_curl, squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cf06c3aa-52dd-481b-a58a-f70d08e37638', 'Sumo Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. Excellent for pre-exhausting the target muscle before compound lifts.', '10641201', '10641201-Sumo-Squat-(male)_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability. A solid choice for legs day.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Sumo Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cf1529c6-5f11-461a-8e95-f23c7028ed98', 'Elevated Lunge T Spine Rotation (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target your spine with this lunging stretch that helps restore range of motion. Your lower back work as secondary movers, adding to the training stimulus. Flexibility work like this enhances performance and prevents stiffness.', '103511201', '103511201-Elevated-Lunge-T-Spine-Rotation-(male)_Stretching.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Elevated Lunge T Spine Rotation. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Elevated Lunge T Spine Rotation', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cf1b1335-03dd-429f-ad2f-682100e0c803', 'Hopping Pendulum', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements. Works well as both a primary exercise or accessory movement.', '73411201', '73411201-Hopping-Pendulum-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Set up in the starting position for Hopping Pendulum. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Hopping Pendulum', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('cf247692-051f-484f-ba0e-11aef84d1b52', 'Jump Step Up (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Cardiovascular exercise improves heart health, endurance, and helps manage weight. This is a great exercise for all fitness levels with proper scaling.', '5151201', '05151201-Jump-Step-Up-(female)_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Set up a box or step platform at the appropriate height. 2. Step one foot onto the elevated surface. 3. Drive through that foot to lift your body up onto the platform. 4. Step back down with control and repeat. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'step_up', 'Jump Step Up', 'lunge, split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('cf2a5e4a-31f7-44eb-81b9-15600593a5b0', 'Standing Straight Arm Chest High Fly', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. Your front delts work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '79831201', '79831201-Bodyweight-Standing-Straight-Arm-Chest-High-Fly-(f.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Stand with feet about shoulder-width apart. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'chest_fly', 'Standing Straight Arm Chest High Fly', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cf36de81-44bb-4342-8da6-e691d9cf5dd3', 'Standing Bicep Curl - Wide Grip (EZ Bar)', 'Arms', 'EZ Bar', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. You''ll also feel your forearms working to support the movement. The standing position engages your core for stability. Barbells enable bilateral loading for building raw strength. Dedicated arm training builds both strength and muscular definition.', '70261201', '70261201-EZ-Barbell-Standing-Wide-Grip-Biceps-Curl-(female).mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Standing Wide Grip Biceps Curl. 2. Stand tall with your feet firmly planted. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'bicep_curl', 'EZ Standing Biceps Curl - Wide Grip', 'EZ Standing Biceps Curl - Wide Grip', FALSE, 'ez_bar', FALSE, 3, 60, 2, 95, 80, 65, 95),
('cf37dd33-9d18-4195-9778-8267aaa9894b', 'Overhead Triceps Stretch', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'Build stronger triceps with this stretching exercise for bigger arms. A versatile bodyweight movement perfect for home or gym training. Arm strength supports grip, pulling, and pushing in compound movements.', '56941201', '56941201-Overhead-Triceps-Stretch-(female)_Upper-Arms-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Set up in the starting position for Overhead Triceps Stretch. 2. Execute the movement with proper form, focusing on your triceps. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'tricep_stretch', 'Overhead Triceps Stretch', 'bicep_curl, dip', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cf380536-826b-4d70-ace5-39e8d819f4b1', 'Side Lunge And Kick - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'The Alternating Side Lunge And Kick is a lunging exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '97181201', '97181201-Alternating-Side-Lunge-and-Kick-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Side Lunge And Kick - Alternating', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cf387547-5f02-44db-8b97-40cf9633df12', 'Lying Glute Stretch', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this stretching movement that emphasizes the glutes. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '76941201', '76941201-Lying-Glute-Stretch-(male)_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Lie down in the appropriate position for Lying Glute Stretch. 2. Set up in the starting position for Lying Glute Stretch. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'glute_stretch', 'Lying Glute Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cf6b4202-9a7d-4b08-b56b-1359216e8a20', 'Shoulder Internal Rotation Test', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your shoulders with this rotation stretch that helps restore range of motion. Secondary activation of your upper back provides additional muscle engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '67911201', '67911201-Shoulder-Internal-Rotation-Test-(female)_Stretchin.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Rotate your torso through the movement pattern for Shoulder Internal Rotation Test. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Shoulder Internal Rotation Test. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Shoulder Internal Rotation Test', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cf719985-33e0-4f94-8d84-5c0c34449c8a', 'Butt Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts. Excellent for pre-exhausting the target muscle before compound lifts.', '8701201', '08701201-Butt-up_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Set up in the starting position for Butt Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Butt Up', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cf72c14b-5c7c-4a36-af20-ce02067c78fc', 'Glute Bridge Tip Toe - Alternating', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. You''ll also feel your hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts. Quality repetitions are more important than quantity.', '94411201', '94411201-Glute-Bridge-Alternating-Tip-Toe-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Tip Toe - Alternating', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cf7678ad-4689-4c8c-b570-0201ebe9393e', 'Seated Single Leg Hugging Knee Flexion (Towel)', 'Legs', 'Towel', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This flexion exercise engages your core for improved core stability and strength. Being seated provides stability, allowing you to focus on the working muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '105421201', '105421201-Seated-Single-Leg-Hugging-Knee-Flexion-with-Towel.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Complete all reps on one side, then switch to the other side. 3. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'leg_exercise', 'Seated Single Leg Hugging Knee Flexion With Towel', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cf8354ad-ee52-4683-bd56-9cdcc3b99026', 'Adductors Stretch Sagittal Plane', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'Build leg strength with this stretching movement focusing on your adductors. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '76901201', '76901201-Adductors-Stretch-Sagittal-Plane-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Set up in the starting position for Adductors Stretch Sagittal Plane. 2. Execute the movement with proper form, focusing on your adductors. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_adduction', 'Adductors Stretch Sagittal Plane', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('cf8462b6-4755-4940-873a-5c966aca7e1f', 'Lateral Raise Side Step', 'Shoulders', 'Bodyweight', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'A challenging plyometric exercise, the Lateral Raise Side Step builds reactive power and improves conditioning. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '89811201', '89811201-Lateral-Raise-Side-Step-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Set up a box or step platform at the appropriate height. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. Works well for lateral delts activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lateral Raise Side Step', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cf89e2c3-3b23-4952-aec1-ac47e96fa910', 'Standing Scissors Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This dynamic crunching movement gets your heart rate up while developing explosive strength. Secondary activation of your hip flexors provides additional muscle engagement. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '75741201', '75741201-Standing-Scissors-Crunch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand tall with your feet firmly planted. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Standing Scissors Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cf954c33-98e6-4f7b-b171-85a90751f243', 'Forward Raise (Cable)', 'Shoulders', 'Cables', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your delts for improved shoulder strength and aesthetics. Cables provide constant tension throughout the full range of motion. Shoulder development enhances both performance and upper body aesthetics.', '1611201', '01611201-Cable-Forward-Raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Adjust the cable machine to the correct height and attachment for Cable Forward Raise. 2. Raise the weight in the prescribed direction for Cable Forward Raise. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'general_exercise', 'Forward Raise', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('cf97697d-57e4-4b1d-89e7-47d33db2abec', 'Side Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'The Side Twist provides a deep stretch for your full body, ideal for recovery and mobility work. The abs assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '28661201', '28661201-Side-Twist-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Rotate your torso through the movement pattern for Side Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Side Twist. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 6. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Side Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cfa7e500-5a22-42f2-91eb-4ef9332384d5', 'Standing Russian Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Standing Russian Twist is an explosive exercise that combines cardiovascular training with dynamic twisting movements. Your abs work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '75801201', '75801201-Standing-Russian-Twist-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Standing Russian Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cfa7f18e-490a-4ad7-96e3-f012ace03124', 'Seated Side To Side Bend Along The Wall Stick (Wall)', 'Core', 'Wall', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this movement exercise that strengthens your obliques. Secondary activation of your abs provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Core strength is foundational for athletic performance and injury prevention.', '103571201', '103571201-Stick-Sitting-Side-to-Side-Bend-Along-the-Wall-(m.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Position yourself at the appropriate distance from a wall. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'side_bend', 'Stick Seated Side To Side Bend Along The Wall', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cfbcf9a0-26cd-4a67-9f94-9b03122c3b3d', 'Standing Top Clap Back Clap', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Shoulders"}'::text[], 'Use this stretch to open up your back area and enhance overall flexibility. The shoulders assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Include this in your routine for better mobility and reduced muscle tension.', '96141201', '96141201-Standing-Top-Clap-Back-Clap-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand tall with your feet firmly planted. 2. Move into the stretch position for Standing Top Clap Back Clap. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Top Clap Back Clap', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('cfc358c2-71b0-41a5-86e1-e742d3bed9ba', 'High Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition. Maintain proper breathing - exhale during the effort phase.', '74241201', '74241201-Dumbbell-High-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell High Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'High Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('cfc63ba8-0056-4121-b83b-45b1de060235', 'Strict Curl (EZ Bar)', 'Arms', 'EZ Bar', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. Using a barbell provides stability for progressive overload. Dedicated arm training builds both strength and muscular definition. Perfect for including in both strength and hypertrophy programs.', '59181201', '59181201-EZ-Barbell-Srtict-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Strict Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'EZ Strict Curl', 'EZ Strict Curl', FALSE, 'ez_bar', FALSE, 3, 60, 2, 95, 80, 65, 95),
('cfd05dc8-ff7a-4496-9ddc-49ef831f23d7', 'Hang Snatch Below The Knees (Barbell)', 'Full Body', 'Barbell', '{"Full Body"}'::text[], '{"Quads","Shoulders"}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. Your quads, shoulders work as secondary movers, adding to the training stimulus. The barbell allows you to handle heavier loads for maximum strength gains. Full body exercises are time-efficient and build functional, real-world strength.', '15231201', '15231201-Barbell-Hang-Snatch-Below-the-Knees_Weightlifts_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Grip a barbell with hands at the appropriate width for Barbell Hang Snatch Below The Knees. 2. Explosively pull the weight from the floor/hang position. 3. As it rises, pull yourself under and catch it overhead with locked arms. 4. Stand to complete the lift. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 8, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'snatch', 'Hang Snatch Below The Knees', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('cfdfbfda-4f1f-4d07-b3b2-a560ecdb744c', 'Upright Row (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'Build stronger shoulders with this rowing movement focusing on your delts. Secondary activation of your traps provides additional muscle engagement. Kettlebells are excellent for building functional, real-world strength. Strong shoulders improve overhead strength and support nearly all upper body movements.', '44081201', '44081201-Kettlebell-Upright-Row_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Select an appropriately weighted kettlebell for Kettlebell Upright Row. 2. Pull the weight straight up along your body, leading with your elbows. 3. Raise until elbows reach shoulder height, then lower with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'upright_row', 'Upright Row', 'lateral_raise, shoulder_press, shrug', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('cfec1236-d579-424b-947d-e948742065d9', 'Incline Shoulders Press (Barbell)', 'Legs', 'Barbell, Incline Bench', '{"Shoulders","Front Delts"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pressing movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. The barbell allows you to handle heavier loads for maximum strength gains. Strong legs are the foundation for athletic performance and functional fitness.', '68771201', '68771201-Barbell-Incline-Shoulders-Press-(inside-squat-cage.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Incline Shoulders Press (inside Squat Cage. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'squat', 'Incline Shoulders Press', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('cfef7986-b737-4247-9271-be018be127f7', 'Sumo Quarter Squat Tip Toe With Arms Curl', 'Legs', 'Bodyweight', '{"Quads","Glutes","Biceps","Calves"}'::text[], '{"Forearms"}'::text[], 'The Sumo Quarter Squat Tip Toe With Arms Curl is a curling exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '53251201', '53251201-Sumo-Quarter-Squat-Tip-Toe-with-Arms-Curl-(female).mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears. Great for building strength in your quads.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'calf_raise', 'Sumo Quarter Squat Tip Toe With Arms Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cffd5fc5-6994-478e-87d6-35520b7c1126', 'Criss Cross Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this raising movement focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '54911201', '54911201-Criss-Cross-Leg-Raises-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Criss Cross Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('cfff7bc4-ed56-4b80-a865-44dc7cb124f1', 'Standing Side Bend Stretch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Use this stretch to open up your obliques area and enhance overall flexibility. The lats, lower back assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Include this in your routine for better mobility and reduced muscle tension.', '85131201', '85131201-Standing-Side-Bend-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Stand tall with your feet firmly planted. 2. Move into the stretch position for Standing Side Bend Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'side_bend', 'Standing Side Bend Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d0031ed4-1283-40ae-ae5d-c050ef49499b', 'Shuffle Step With Squat And Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity squatting exercise that challenges your entire body. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '105321201', '105321201-Shuffle-Step-with-Squat-and-Jump-(male)_Plyometri.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Set up a box or step platform at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Explode upward from the bottom, jumping as high as possible. 5. Land softly with bent knees and immediately descend into the next rep. 6. Complete all reps with control before resting. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'shuffle', 'Shuffle Step With Squat And Jump', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d0081e21-f5c8-499b-9e0b-d9e689f59552', 'Kneeling Rotation Torso Rear Fly To Thread Through', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. The front delts assist throughout the movement, making this a well-rounded exercise. The kneeling position adds a core stability challenge. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '78951201', '78951201-Kneeling-Rotation-Torso-Rear-Fly-to-Thread-Through.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'rear_delt', 'Kneeling Rotation Torso Rear Fly To Thread Through', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d00c9e31-38b6-4ba9-b028-0b9ad71adef9', 'Hip Twist Supported Arms', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes"}'::text[], 'The Hip Twist Supported Arms provides a deep stretch for your hips, ideal for recovery and mobility work. Secondary activation of your glutes provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension.', '28451201', '28451201-Hip-Twist-Supported-Arms_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Rotate your torso through the movement pattern for Hip Twist Supported Arms. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Hip Twist Supported Arms. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Hip Twist Supported Arms', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d0114a42-6f8a-4aed-be36-efdef60b3a2d', 'Side Plank Twist', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{}'::text[], 'Work your side abdominals with this stabilization exercise that strengthens your obliques. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '71421201', '71421201-Side-Plank-Twist-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Side Plank Twist', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('d0168527-9ab6-4256-9e34-56fbd7a73d73', 'Single Arms Pullover (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger back with this pulling movement targeting your chest. The lats, triceps assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. A strong back improves posture, prevents injury, and balances pressing movements.', '69511201', '69511201-Dumbbell-Single-Arms-Pullover-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'pullover', 'Single Arms Pullover', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('d01872c7-05b7-4b28-bdcb-d5f0f4012c54', 'Incline Bicep Curl (Kettlebell)', 'Arms', 'Kettlebell, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Kettlebell Incline Biceps Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. The incline angle shifts emphasis toward the upper portion of the target muscles. The kettlebell grip position adds a unique training stimulus. Arm strength supports grip, pulling, and pushing in compound movements.', '68181201', '68181201-Kettlebell-Incline-Biceps-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Select an appropriately weighted kettlebell for Kettlebell Incline Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 91, 5, 7, FALSE, TRUE, 'bicep_curl', 'Incline Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('d0212161-52d0-473a-b691-845148435783', 'Sled Side Leg Press (Machine)', 'Legs', 'Leg Press Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pressing movement emphasizes your quadriceps for stronger, more powerful legs. The glutes assist throughout the movement, making this a well-rounded exercise. Lower body strength improves everything from walking to heavy compound lifts.', '86601201', '86601201-Sled-Side-Leg-Press-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Position your feet on the platform and release the safety. 2. Lower the weight by bending your knees, then press back up powerfully. 3. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 80, 7, 9, TRUE, FALSE, 'leg_press', 'Sled Side Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('d0669794-a2ca-4590-a2ae-041a11c3a4ce', 'Double Knee Elbow Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Double Knee Elbow Pull Up is an explosive exercise that combines cardiovascular training with dynamic pulling movements. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '64811201', '64811201-Double-Knee-Elbow-Pull-Up-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Double Knee Elbow Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d067e07a-0730-447a-82fe-fda8d84626b8', 'Standing Elbow Crossover Raise', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your delts for improved shoulder strength and aesthetics. Your front delts work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '64451201', '64451201-Standing-Elbow-Crossover-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Raise the weight in the prescribed direction for Standing Elbow Crossover Raise. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'chest_fly', 'Standing Elbow Crossover Raise', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d07eb091-b2fc-41cb-b297-c41d401e991c', 'Twisting Overhead Press (Cable)', 'Shoulders', 'Cables', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. Your triceps work as secondary movers, adding to the training stimulus. The cable setup allows you to adjust the angle of resistance. Shoulder development enhances both performance and upper body aesthetics.', '12091201', '12091201-Cable-twisting-overhead-press_shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Adjust the cable machine to the correct height and attachment for Cable Twisting Overhead Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'shoulder_press', 'Twisting Overhead Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('d080226f-5918-4f80-bc1b-678c2bdaa830', 'Floor Crunch Feet On Bench', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Floor Crunch Feet On Bench is a core crunching exercise that primarily targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Core strength is foundational for athletic performance and injury prevention.', '32791201', '32791201-Floor-Crunch-Feet-on-Bench-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Position yourself on the floor for Floor Crunch Feet On Bench. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'crunch', 'Floor Crunch Feet On Bench', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d0806079-cd5d-426c-8c69-0db1fd3e44ec', 'Single Arm Preacher Curl (Dumbbell)', 'Arms', 'Dumbbells, Preacher Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Single Arm Preacher Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '30841201', '30841201-Dumbbell-Single-Arm-Preacher-Curl-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'preacher_curl', 'Single Arm Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d08dd17b-e6b6-451e-94f4-26dd0a5b9d74', 'Lying Reverse Frog Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this crunching movement focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '62851201', '62851201-Lying-Reverse-Frog-Crunch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Reverse Frog Crunch. 2. Lift your hips off the floor by contracting your lower abs. 3. Bring your knees toward your chest, then lower with control. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Lying Reverse Frog Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d0903bff-a3ed-4e83-846b-c5c13e9c3a90', 'Incline Alternative Fly (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Dumbbell Incline Alternative Fly is a flying exercise that targets your chest muscles. Secondary activation of your front delts provides additional muscle engagement. The incline angle shifts emphasis toward the upper portion of the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. A well-developed chest contributes to upper body strength and aesthetics.', '93031201', '93031201-Dumbbell-Incline-Alternative-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Alternative Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'chest_fly', 'Incline Alternative Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d0acd1ae-94a7-43e2-893c-b6a016957c0b', 'Svend Press March', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This dynamic pressing movement gets your heart rate up while developing explosive strength. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '99061201', '99061201-Svend-Press-March-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Execute the pressing motion for Svend Press March, extending through the target muscles. 2. Set up in the starting position for Svend Press March. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'squeeze_press', 'Svend Press March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d0b9fae5-489a-4f8e-9b5b-b4784246b6e0', 'Seated Kickback (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'This kicking movement isolates your triceps for improved arm development. The hamstrings assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '34211201', '34211201-Dumbbell-Seated-Kickback-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Kickback. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 64, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Seated Kickback', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d0bf5e49-f738-47cf-87f6-ee913c3e7ed7', 'Standing Side To Cross Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Elevate your training with this crunching exercise that develops speed, power, and coordination. Secondary activation of your hip flexors provides additional muscle engagement. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '74871201', '74871201-Standing-Side-to-Cross-Crunch-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Begin in a standing position with good posture. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Standing Side To Cross Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d0c10498-7c23-4fda-a7c8-e8880c76c4a1', 'Straight Leg Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. The barbell allows you to handle heavier loads for maximum strength gains. Leg training boosts metabolism and builds functional, real-world strength.', '35941201', '35941201-Barbell-Straight-Leg-Deadlift-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Straight Leg Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Straight Leg Deadlift', 'deadlift, leg_curl, hip_thrust', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('d0c3512c-fd24-45f1-be91-11465ccc0e27', 'Standing Bent Knee Calf Raise Support (Chair)', 'Legs', 'Chair', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. The standing position engages your core for stability. Leg training boosts metabolism and builds functional, real-world strength.', '94091201', '94091201-Standing-Bent-Knee-Calf-Raise-with-a-Chair-Support.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Begin in a standing position with good posture. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Bent Knee Calf Raise With A Chair Support', 'calf_raise, seated_calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d0dd640a-420a-472a-81d6-66bf8b1d4ffe', 'Standing Single Arm Curl Over Incline Bench (Dumbbell)', 'Arms', 'Dumbbells, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '97251201', '97251201-Dumbbell-Standing-One-Arm-Curl-Over-Incline-Bench-.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Begin in a standing position with good posture. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'incline_press', 'Standing Single Arm Curl Over Incline Bench', 'bench_press, shoulder_press, chest_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d0e737d8-ace0-4bb3-8de1-a567ac9e9791', 'Calves Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Calves Stretch isolates your calf muscles through a stretching motion. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '9371201', '09371201-Calves-stretch-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Set up in the starting position for Calves Stretch. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Calves Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d0f98b1e-e134-4134-996f-71d8eafcfe99', 'Russian Twist With Legs Off Floor (Dumbbell)', 'Core', 'Dumbbells', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Dumbbell Russian Twist With Legs Floor Off (versio targets your obliques through a twisting motion, building rotational core strength. Your abs work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. A strong core improves posture, protects your spine, and enhances all other lifts.', '54631201', '54631201-Dumbbell-Russian-Twist-with-Legs-Floor-Off-(VERSIO.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Russian Twist With Legs Floor Off (versio. 2. Position yourself on the floor for Dumbbell Russian Twist With Legs Floor Off (versio. 3. Rotate your torso through the movement pattern for Dumbbell Russian Twist With Legs Floor Off (versio. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 39, 5, 7, FALSE, TRUE, 'russian_twist', 'Russian Twist With Legs Floor Off', 'crunch, plank, leg_raise, wood_chop', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d1076655-3406-446a-91a5-6cd49483e5f5', 'Glute Bridge Roll', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Glute Bridge Roll is a hip-dominant bridging exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '72971201', '72971201-Glute-Bridge-Roll-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. Great for building strength in your glutes.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Roll', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d11283b8-0882-43a8-92bd-7cd1da8c8420', 'Chest Fly Forearms', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '104731201', '104731201-Chest-Fly---Forearms-(WRONG-RIGHT)_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Chest Fly Forearms', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d1153236-4028-4498-b001-ee952bc351b0', 'Diagonal Reach (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Diagonal Reach On Chair, focusing on your abs. Core strength is foundational for athletic performance and injury prevention.', '66321201', '66321201-Diagonal-Reach-on-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Diagonal Reach On Chair. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Diagonal Reach On Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d11e94b6-75d8-422f-ae1a-18c6211fb1f8', 'Pull In (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Pull In (on Stability Ball), focusing on your abs. The stability ball adds an instability challenge that activates more stabilizer muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '6501201', '06501201-Pull-In-(on-stability-ball)_waist.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Position the stability ball as needed for Pull In. 2. Set up in the starting position for Pull In. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'general_exercise', 'Pull In', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d1231188-2b96-4314-9924-3cf243d24e52', 'Standing Side Leg Raise Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Standing Side Leg Raise Crunch builds reactive power and improves conditioning. Secondary activation of your glutes provides additional muscle engagement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '85201201', '85201201-Standing-Side-Leg-Raise-Crunch-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand tall with your feet firmly planted. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Standing Side Leg Raise Crunch', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d13f7dc4-3b56-48c6-a72c-63aad2c1c44b', 'Chair Squat (Smith Machine)', 'Legs', 'Smith Machine, Chair', '{Quadriceps}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Smith Chair Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '7501201', '07501201-Smith-Chair-Squat_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Chair Squat. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'squat', 'Smith Chair Squat', 'Chair Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('d14182ff-29fd-4129-aa50-ed5f788c5d2a', 'Sled 45 Degrees Deep Leg Press (Machine)', 'Legs', 'Leg Press Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this pressing movement that develops leg drive and power. Secondary activation of your glutes provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '107041201', '107041201-Sled-45-degrees-Deep-Leg-Press_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Position your feet on the platform and release the safety. 2. Lower the weight by bending your knees, then press back up powerfully. 3. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 80, 7, 9, TRUE, FALSE, 'leg_press', 'Sled 45 Degrees Deep Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('d15c977f-2b6f-4527-b299-cff251a96271', 'Plank March (Resistance Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Resistance Band Plank March is a lower body stabilization exercise that targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. The band creates increasing tension as it stretches, challenging the lockout. Strong legs are the foundation for athletic performance and functional fitness.', '25571201', '25571201-Resistance-Band-Plank-March-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Plank March. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'plank', 'Plank March', 'side_plank, dead_bug, hollow_hold', FALSE, 'band', TRUE, 3, 90, 4, 60, 85, 90, 50),
('d165992b-563d-4aa2-94b8-741fa578926d', 'Banded Bench Press (Barbell)', 'Chest', 'Barbell, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. A well-developed chest contributes to upper body strength and aesthetics. This variation is excellent for building mind-muscle connection.', '76201201', '76201201-Barbell-Banded-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'bench_press', 'Banded Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('d165fb7a-e900-4dc7-aca7-6cb2d749618e', 'Glute Bridge Hip Side Raise', 'Shoulders', 'Bodyweight', '{"Glutes"}'::text[], '{"Traps"}'::text[], 'This raising exercise isolates your glutes for improved hip strength and power. You''ll also feel your hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '94491201', '94491201-Glute-Bridge-Hip-Side-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_bridge', 'Glute Bridge Hip Side Raise', 'hip_thrust, romanian_deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d16959b3-0836-433f-ab2d-6d695d3b9ed7', 'Kickback (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'The Cable Kickback targets your triceps through a kicking motion. Secondary activation of your hamstrings provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '10681201', '10681201-Cable-kickback-II_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kickback. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Kickback', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('d17cb836-4a42-46a8-bce5-396f65709126', 'Explosive Bench Press (Barbell)', 'Chest', 'Barbell, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Barbell Explosive Bench Press is a pressing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Using a barbell provides stability for progressive overload. A well-developed chest contributes to upper body strength and aesthetics.', '88031201', '88031201-Barbell-Explosive-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Perform the concentric (lifting) phase explosively with maximum effort. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 97, 7, 8, TRUE, TRUE, 'bench_press', 'Explosive Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('d183b404-f451-4531-b9ff-10aa93f5e77a', 'Assisted Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Secondary activation of your biceps, upper back provides additional muscle engagement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '171201', '00171201-Assisted-Pull-up_Back.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Assisted Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d18cbbd4-ed71-4eb0-a57a-01ef193aa348', 'Sit Up Stand Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Sit Up Stand Up, focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '55101201', '55101201-Sit-up-Stand-up_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Set up in the starting position for Sit Up Stand Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Sit Up Stand Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d18e84cc-584b-440c-8432-8ca342fc43cb', 'Lying Legs Extension - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Alternating Legs Extension is a lower body extension exercise that targets your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '96601201', '96601201-Lying-Alternating-Legs-Extension-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Lie down in the appropriate position for Lying Alternating Legs Extension. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Alternate between sides/arms/legs with each repetition. 5. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_exercise', 'Lying Legs Extension - Alternating', 'leg_curl, squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d1a0816e-81c3-438e-aac1-249386dca701', 'Straight Back Seated High Row - Reverse Grip (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. The seated position helps isolate the target muscles by removing momentum. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '2081201', '02081201-Cable-Reverse-grip-Straight-Back-Seated-High-Row_Back.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a reverse grip (opposite of the standard grip for this exercise). 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'cable_row', 'Straight Back Seated High Row - Reverse Grip', 'Straight Back Seated High Row - Reverse Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('d1a7db4e-e700-401d-9c41-733be4f3d06d', 'Standing Leg Curl', 'Legs', 'Bodyweight', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Secondary activation of your calves provides additional muscle engagement. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '64001201', '64001201-Standing-Leg-Curl-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Curl your heels toward your glutes by bending at the knees. 3. Squeeze your hamstrings at peak contraction. 4. Extend legs back out with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'leg_curl', 'Standing Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d1b09240-6e87-4dbd-b99e-f81a28efaf7d', 'Half Frog Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Maintain proper breathing - exhale during the effort phase.', '61761201', '61761201-Half-Frog-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Move into the stretch position for Half Frog Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Half Frog Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d1b13c99-a335-49dd-83df-203975d64028', 'Scapular Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Secondary activation of your biceps, upper back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '6881201', '06881201-Scapular-Pull-Up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum. Beneficial for overall back development.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Scapular Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d1c01807-427a-41ab-b239-682b183a15ae', 'Bound Angle Yoga Pose Baddha Konasana', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Include this in your routine for better mobility and reduced muscle tension. This is a great exercise for all fitness levels with proper scaling.', '76081201', '76081201-Bound-Angle-Yoga-Pose-Baddha-Konasana-(female)_Str.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Move into the stretch position for Bound Angle Yoga Pose Baddha Konasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 15, 9, 8, TRUE, TRUE, 'yoga', 'Bound Angle Yoga Pose Baddha Konasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d1d8f9c2-fcdb-4f08-b572-8b44df434234', 'Seated Single Leg Knee Flexion', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this flexion movement focusing on your core. The seated position helps isolate the target muscles by removing momentum. Lower body strength improves everything from walking to heavy compound lifts. Works well as both a primary exercise or accessory movement.', '105341201', '105341201-Seated-Single-Leg-Knee-Flexion-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Complete all reps on one side, then switch to the other side. 3. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'leg_exercise', 'Seated Single Leg Knee Flexion', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d1ef839b-930e-40c7-a599-f4c9899dddf3', 'Single Leg Romanian Deadlift Leg Raise (Dumbbell)', 'Legs', 'Dumbbells', '{"Lower Abs"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Strengthen your midsection with this hip hinge movement that works your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Building core stability helps with everything from heavy deadlifts to daily activities.', '97541201', '97541201-Dumbbell-Single-Leg-Romanian-Deadlift-Leg-Raise-(m.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Single Leg Romanian Deadlift Leg Raise', 'deadlift, leg_curl, hip_thrust', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('d1f25c52-bf68-40bc-9b91-193f1078022b', 'Seated Hip Knee And Ankle Mobilization On A Stabi', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This movement exercise isolates your glutes for improved hip strength and power. Being seated provides stability, allowing you to focus on the working muscles. Leg training boosts metabolism and builds functional, real-world strength.', '92771201', '92771201-Sitting-Hip-Knee-and-Ankle-Mobilization-on-a-Stabi.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Hip Knee And Ankle Mobilization On A Stabi. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 38, 2, 6, FALSE, TRUE, 'mobility', 'Seated Hip Knee And Ankle Mobilization On A Stabi', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d1f6506b-00cc-4884-b83e-b7766c26b3c5', 'Ring Handstand To L Sit (Gymnastic Rings)', 'Core', 'Gymnastic Rings', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Ring Handstand To L Sit is a core movement exercise that primarily targets your abs. A strong core improves posture, protects your spine, and enhances all other lifts.', '75231201', '75231201-Ring-Handstand-to-L-Sit-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Set up in the starting position for Ring Handstand To L Sit. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'yoga', 'Ring Handstand To L Sit', 'squat, bench_press, deadlift', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('d201217c-c6f5-4339-bd6e-cd59a584633d', 'Elbow Up And Down Dynamic Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. You''ll also feel your shoulders, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities. A staple exercise that belongs in most training programs.', '29791201', '29791201-Elbow-Up-and-Down-Dynamic-Plank-(female).mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Keep your core engaged for stability. This exercise is excellent for abs development. Variation: Elbow Up And Down Dynamic Plank.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Elbow Up And Down Dynamic Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('d2143afe-53b0-4b50-af51-60095e26e68b', 'Elbow Touch To Outer Throw', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Elbow Touch To Outer Throw is a rowing exercise that targets your chest muscles. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '76581201', '76581201-Elbow-Touch-to-Outer-Throw-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction. Include this in your chest training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Elbow Touch To Outer Throw', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2146d2d-361b-4522-8412-2fcb3d26faac', 'Knee Cross Over (Against Wall) - Alternating', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Alternate Knee Cross Over Sit Against Wall is a movement exercise that primarily loads your quadriceps. Secondary activation of your glutes provides additional muscle engagement. Leg training boosts metabolism and builds functional, real-world strength.', '89631201', '89631201-Alternate-Knee-Cross-Over-Sit-agains-Wall-(male)_H.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Position yourself at the appropriate distance from a wall. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, 'Static', 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 7, 7, NULL, 5, 'Seated (Against Wall)', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'boxing', 'Knee Cross Over Against Wall - Alternating', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2244073-e7f3-4683-8545-9f1dd63af862', 'Kneeling Back Kick (Resistance Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Resistance Band Kneeling Back Kick is a lower body kicking exercise that targets your core. The kneeling position adds a core stability challenge. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '72081201', '72081201-Resistance-Band-Kneeling-Back-Kick-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Kneeling Back Kick. 2. Kneel on the floor (use a pad for comfort if needed). 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'back_exercise', 'Kneeling Back Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d22f8693-7036-4395-8ed5-48056856e32f', 'Wide Upright Row (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'The Kettlebell Wide Upright Row is a rowing exercise that targets your delts for shoulder development. Your traps work as secondary movers, adding to the training stimulus. The kettlebell''s offset center of mass increases the stability challenge. Strong shoulders improve overhead strength and support nearly all upper body movements.', '70231201', '70231201-Kettlebell-Wide-Upright-Row-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Select an appropriately weighted kettlebell for Kettlebell Wide Upright Row. 2. Use a wide grip (wider than shoulder-width) for this variation. 3. Pull the weight straight up along your body, leading with your elbows. 4. Raise until elbows reach shoulder height, then lower with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'upright_row', 'Wide Upright Row', 'lateral_raise, shoulder_press, shrug', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('d23330ba-cfcb-4fe4-873b-cc423e88aad2', 'Chaturanga Pose', 'Core', 'Bodyweight', '{"Core"}'::text[], '{}'::text[], 'The Chaturanga Pose provides a deep stretch for your full body, ideal for recovery and mobility work. Include this in your routine for better mobility and reduced muscle tension.', '58881201', '58881201-Chaturanga-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Move into the stretch position for Chaturanga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Chaturanga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d239956e-35a2-429e-a526-1996809a0512', 'Chin Tuck Hold', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Designed to lengthen your full body, the Chin Tuck Hold helps improve mobility and prevent stiffness. Flexibility work like this enhances performance and prevents stiffness.', '77901201', '77901201-Chin-Tuck-Hold-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Move into the stretch position for Chin Tuck Hold. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Chin Tuck Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('d23db21d-6958-40e1-99af-175c1f136d5e', 'Side Crunch (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Cable Side Crunch, focusing on your abs. Secondary activation of your abs provides additional muscle engagement. The cable setup allows you to adjust the angle of resistance. Core strength is foundational for athletic performance and injury prevention.', '2231201', '02231201-Cable-Side-Crunch_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Adjust the cable machine to the correct height and attachment for Cable Side Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'crunch', 'Side Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('d2409941-4fc8-4f8c-a63c-56f4bf8e6dec', 'Rollout (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your abs. Secondary activation of your lats, shoulders provides additional muscle engagement. The stability ball adds an instability challenge that activates more stabilizer muscles. Strong legs are the foundation for athletic performance and functional fitness.', '22961201', '22961201-Stability-Ball-Rollout-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Position the stability ball as needed for Stability Ball Rollout. 2. Set up in the starting position for Stability Ball Rollout. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'ab_rollout', 'Stability Ball Rollout', 'plank, crunch, dead_bug', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d240b3c8-b148-45ef-93d2-852de31113f3', 'Spider Curl (EZ Bar)', 'Arms', 'EZ Bar', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. You''ll also feel your forearms working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Dedicated arm training builds both strength and muscular definition.', '78671201', '78671201-EZ-Barbell-Spider-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Spider Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'EZ Spider Curl', 'EZ Spider Curl', FALSE, 'ez_bar', FALSE, 3, 60, 2, 95, 80, 65, 95),
('d26ddc39-e706-45bb-9040-e0d90edf7d20', 'Lying Front Raise', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'This raising exercise works your front delts for improved shoulder strength and aesthetics. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '89751201', '89751201-Lying-Front-Raise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Lie down in the appropriate position for Lying Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'front_raise', 'Lying Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d2707806-1ebd-4171-9a1a-ce1d8a466c33', 'Figure 8 (Kettlebell)', 'Core', 'Kettlebell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kettlebell Figure 8 is a core movement exercise that primarily targets your abs. Kettlebells are excellent for building functional, real-world strength. Core strength is foundational for athletic performance and injury prevention.', '5321201', '05321201-Kettlebell-Figure-8_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Select an appropriately weighted kettlebell for Kettlebell Figure 8. 2. Set up in the starting position for Kettlebell Figure 8. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Figure 8', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('d2799cb8-6188-4012-b327-cf157985098c', 'Inchworm To Cobra', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Inchworm To Cobra is a core movement exercise that primarily targets your abs. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '75371201', '75371201-Inchworm-to-Cobra-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Set up in the starting position for Inchworm To Cobra. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'inchworm', 'Inchworm To Cobra', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d285d4af-e90f-400a-a98d-651a93250515', 'Kneeling Thread The Needle', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your upper back, promoting flexibility and reducing muscle tightness. Your shoulders, thoracic spine work as secondary movers, adding to the training stimulus. Kneeling helps eliminate lower body momentum from the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '85451201', '85451201-Kneeling-Thread-the-Needle-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Thread The Needle. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Kneeling Thread The Needle', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d29235e2-be70-4bf1-9bae-f0a40c1be526', 'Walk Leg Kick', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build your aerobic capacity with this steady-state cardio movement. Regular cardio training builds the aerobic base for better overall fitness. Progress gradually by increasing resistance over time.', '107491201', '107491201-Walk-Leg-Kick-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walk Leg Kick. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Walk Leg Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2997cb7-6083-4afb-80a0-ad5f15dfa66a', 'Sprint', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Build your aerobic capacity with this steady-state cardio movement. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Can be modified for beginners or progressed for advanced athletes.', '52171201', '52171201-Sprint-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set up in the starting position for Sprint. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'sprint', 'Sprint', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2a113a5-2956-46d5-8e80-baef13df9415', 'Scissors Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity jumping exercise that challenges your entire body. Secondary activation of your quads, calves provides additional muscle engagement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '56771201', '56771201-Scissors-Jump-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Set up in the starting position for Scissors Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Scissors Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d2a56a3a-f3a5-4110-8888-1f0741bc4b4e', 'Hanging Flutter Kick (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Hanging Flutter Kick is a lower body kicking exercise that targets your abs. Secondary activation of your hip flexors, grip provides additional muscle engagement. The hanging position challenges your grip while targeting the primary muscles. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '47661201', '47661201-Hanging-Flutter-Kick_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Set up in the starting position for Hanging Flutter Kick. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_raise', 'Hanging Flutter Kick', 'crunch, plank, v_up', FALSE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2a707ae-f935-401c-a330-45f021156240', 'Heel Elevated Squat (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness. Start with lighter weight to master the movement pattern.', '75771201', '75771201-Bodyweight-Heel-Elevated-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout. Beneficial for overall legs development.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Heel Elevated Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2a93aaf-5cc1-47e8-b90d-3c47448f8661', 'Cat Cow Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Cat Cow Stretch provides a deep stretch for your spine, ideal for recovery and mobility work. The core assist throughout the movement, making this a well-rounded exercise. Flexibility work like this enhances performance and prevents stiffness.', '52521201', '52521201-Cat-Cow-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Move into the stretch position for Cat Cow Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your shoulders relaxed and away from your ears. A solid choice for stretching day.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Cat Cow Stretch', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d2a9cb35-3415-44cd-8823-02ed080e02e7', 'Self Assisted Pull Up (TRX)', 'Back', 'TRX', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. Suspension training adds instability, increasing core activation throughout. A strong back improves posture, prevents injury, and balances pressing movements.', '10941201', '10941201-Suspender-Self-assisted-Pull-up-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Self Assisted Pull Up. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'pull_up', 'Suspender Self Assisted Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('d2ad5090-ca60-484c-bf96-6eb3e99da568', 'Standing Side Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. The abs assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '58451201', '58451201-Standing-Side-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Stand tall with your feet firmly planted. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Standing Side Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d2ad53cd-b72d-4d40-a6b2-7b1e41149cad', 'Side Hip Abduction', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'Build leg strength with this movement movement focusing on your glute med/abductors. You''ll also feel your glutes working to support the movement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '7101201', '07101201-Side-Hip-Abduction_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Set up in the starting position for Side Hip Abduction. 2. Execute the movement with proper form, focusing on your glute med/abductors. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Side Hip Abduction', 'hip_adduction, glute_bridge, clamshell', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2b38f62-a54b-47b2-bba4-347f495fd15a', 'Landmine Push Up (Landmine)', 'Chest', 'Landmine Attachment, Barbell', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Landmine Push Up is a pushing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '67011201', '67011201-Landmine-Push-up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity. Ideal for chest strength and endurance.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Landmine Push Up', 'bench_press, chest_fly, dip', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('d2cb37cb-f154-4ce1-86f0-99b6e65a3da2', 'Wide Squat Hands Together', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness. This variation is excellent for building mind-muscle connection.', '86511201', '86511201-Bodyweight-Wide-Squat-Hands-Together-(male)_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Wide Squat Hands Together', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2cc0ae6-3a43-4bc7-9180-6f9b0d409ea2', 'Single Leg Deadlift With Knee Lift', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Single Leg Deadlift With Knee Lift is a lower body hip hinge exercise that targets your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '71581201', '71581201-Single-Leg-Deadlift-with-Knee-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Hinge at hips and bend knees to grip the weight. 2. Drive through your heels, extending hips and knees to stand. 3. Lower by reversing the movement with control. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'deadlift', 'Single Leg Deadlift With Knee Lift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2d073e7-6a0a-4637-a41b-c6b1115c485a', 'Lying Abduction Adduction', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your adductors. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '64311201', '64311201-Lying-Abduction-Adduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Abduction Adduction. 2. Set up in the starting position for Lying Abduction Adduction. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_adduction', 'Lying Abduction Adduction', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2dacef6-d384-41e2-ae69-781a9bcf0479', 'Standing Yin Yang Circles', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Standing Yin Yang Circles, an effective shoulder movement exercise. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '97101201', '97101201-Standing-Yin-Yang-Circles-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Yin Yang Circles. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Yin Yang Circles', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d2fd72a2-072c-4e90-9bf6-111668a7a120', 'Rear Delt Raise (Barbell)', 'Shoulders', 'Barbell', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This raising exercise works your rear delts for improved shoulder strength and aesthetics. Your upper back work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. Strong shoulders improve overhead strength and support nearly all upper body movements.', '751201', '00751201-Barbell-Rear-Delt-Raise_shoulder.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Grip a barbell with hands at the appropriate width for Barbell Rear Delt Raise. 2. Raise your arms out to the sides and back, focusing on rear delts. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', 'Shoulder Horizontal Abduction', 'Pull', 'Isolation', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Overhand (Pronated)', 'Wide', 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'rear_delt', 'Rear Delt Raise', 'shoulder_press, lateral_raise, face_pull, bent_over_row', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('d3015f4f-7e30-47d7-8283-ba6f56c610b2', 'Toe Side Walk (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted stepping exercise. The band creates increasing tension as it stretches, challenging the lockout. Strong legs are the foundation for athletic performance and functional fitness.', '107611201', '107611201-Resistance-Band-Toe-Side-Walk_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Secure the resistance band appropriately for Resistance Band Toe Side Walk. 2. Set up in the starting position for Resistance Band Toe Side Walk. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'walking', 'Toe Side Walk', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d32a4121-c793-424b-8ef9-0c50fcb84312', 'Standing Single Arm Row - Reverse Grip (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Standing Single Arm Reverse Grip Row is a rowing exercise that builds thickness in your upper back. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. The cable setup allows you to adjust the angle of resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '106521201', '106521201-Cable-Standing-Single-Arm-Reverse-grip-Row-(male).mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Single Arm Reverse Grip Row. 2. Stand with feet about shoulder-width apart. 3. Use a reverse grip (opposite of the standard grip for this exercise). 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps on one side, then switch to the other side. 8. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Single Arm Row - Reverse Grip', 'Standing Single Arm Row - Reverse Grip', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('d33f75bc-667c-4ed0-bf71-f42215d0c438', 'Seated Shrug - Alternating', 'Back', 'Bodyweight', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'The Bodyweight Seated Alternating Shrug is a shrugging exercise that develops back strength and muscle. Being seated provides stability, allowing you to focus on the working muscles. A strong back improves posture, prevents injury, and balances pressing movements.', '94021201', '94021201-Bodyweight-Sitting-Alternating-Shrug-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Alternate between sides/arms/legs with each repetition. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'shrug', 'Seated Shrug - Alternating', 'deadlift, bent_over_row, face_pull', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d34b18fd-020d-46c7-8c22-40ebc5bc6d3d', 'Elevated Knee Tuck V Tuck', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Elevanted Knee Tuck V Tuck, focusing on your abs. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '73341201', '73341201-Elevanted-Knee-Tuck-V-Tuck-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Set up in the starting position for Elevanted Knee Tuck V Tuck. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Elevanted Knee Tuck V Tuck', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d353e754-21d6-48d7-97c6-a27e35ce8d08', 'Bent Over Single Arm Row - Wide Grip (Machine)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Lever Bent Over Single Arm Wide Grip Row (with Che is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The bent over position requires core engagement to maintain a neutral spine. The fixed path allows you to focus purely on muscular effort. A strong back improves posture, prevents injury, and balances pressing movements.', '65171201', '65171201-Lever-Bent-Over-Single-Arm-Wide-Grip-Row-(with-che.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Bent Over Single Arm Wide Grip Row (with Che. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Use a wide grip (wider than shoulder-width) for this variation. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps on one side, then switch to the other side. 8. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 73, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Bent Over Single Arm Wide Grip Row (with Che', 'Lever Bent Over Single Arm Row (with Che - Wide Grip', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('d356a63b-186a-454d-8105-ecc4fe0c4c32', 'Stationary Bike Walk (Stationary Bike)', 'Legs', 'Stationary Bike', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Stationary Bike Walk is a cardiovascular exercise that improves endurance and heart health. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '7981201', '07981201-Stationary-Bike-Walk_Cardio.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Set up in the starting position for Stationary Bike Walk. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Stationary Bike Walk', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('d35dde7d-1088-4754-8bfe-24e7b587efd1', 'Standing Stacked Arm Chest Squeeze', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '94121201', '94121201-Standing-Stacked-Arm-Chest-Squeez-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Stacked Arm Chest Squeeze. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'chest_exercise', 'Standing Stacked Arm Chest Squeeze', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d36ed2cf-1ddd-431b-9dcd-ec107cb41342', 'Standing 90 Degrees Arms Rotation', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'This rotation exercise focuses on your pectorals for improved chest strength and development. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '105691201', '105691201-Standing-90-degrees-Arms-Rotation-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Stand tall with your feet firmly planted. 2. Rotate your torso through the movement pattern for Standing 90 Degrees Arms Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing 90 Degrees Arms Rotation', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d36f5082-71ce-4461-bc22-ef05568c85ce', 'High Pulley Straight Bar Overhead Triceps Extension (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'The Cable High Pulley Straight Bar Overhead Triceps Extension targets your triceps through a pulling motion. Cables provide constant tension throughout the full range of motion. Dedicated arm training builds both strength and muscular definition.', '90031201', '90031201-Cable-High-Pulley-Straight-Bar-Overhead-Triceps-Ex.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled. A solid choice for arms day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'tricep_extension', 'High Pulley Straight Bar Overhead Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('d36f5973-81c1-426a-b5ee-30ce2b0fc26b', 'Arm Extension Torso Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'This dynamic extension movement gets your heart rate up while developing explosive strength. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '89221201', '89221201-Arm-Extension-Torso-Twist-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Extend through the target joint(s) for Arm Extension Torso Twist. 2. Set up in the starting position for Arm Extension Torso Twist. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'russian_twist', 'Arm Extension Torso Twist', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d379bd5b-90a7-4fca-82a4-eb663485a3d2', 'Seated Forearms Stretch (Chair)', 'Arms', 'Chair', '{"Forearms"}'::text[], '{}'::text[], 'Designed to lengthen your forearms, the Seated Forearms Stretch On A Chair helps improve mobility and prevent stiffness. Your wrists work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '91701201', '91701201-Sitting-Forearms-Stretch-on-a-Chair-(female)_Stret.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Forearms Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Forearms Stretch On A Chair', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d397ebd0-055c-4513-a1f6-b89ec19021c2', 'Incline Cross Raise (Dumbbell) - Alternating', 'Full Body', 'Dumbbells, Incline Bench', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'This dynamic raising movement gets your heart rate up while developing explosive strength. You''ll also feel your shoulders, core working to support the movement. The incline angle shifts emphasis toward the upper portion of the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Great for improving athletic performance, burning calories, and building conditioning.', '103921201', '103921201-Dumbbell-Incline-Alternating-Cross-Raise_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Alternating Cross Raise. 2. Raise the weight in the prescribed direction for Dumbbell Incline Alternating Cross Raise. 3. Lower with control, maintaining tension throughout. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'boxing', 'Incline Cross Raise - Alternating', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d3a05b40-8d6d-4514-b25e-8af0ffada336', 'Suitcase Hold (Kettlebell)', 'Core', 'Kettlebell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kettlebell Suitcase Hold is a core movement exercise that primarily targets your abs. Kettlebells are excellent for building functional, real-world strength. Core strength is foundational for athletic performance and injury prevention.', '75331201', '75331201-Kettlebell-Suitcase-Hold-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Select an appropriately weighted kettlebell for Kettlebell Suitcase Hold. 2. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'general_exercise', 'Suitcase Hold', 'squat, bench_press, deadlift', FALSE, 'kettlebell', TRUE, 3, 90, 4, 75, 88, 88, 78),
('d3a49a78-50fc-4c29-be47-88dd970f9de4', 'Standing Gluteus Medius Press (Against Wall)', 'Core', 'Wall', '{"Glutes"}'::text[], '{"Hip Flexors"}'::text[], 'The Standing Gluteus Medius Press Against Wall is a core pressing exercise that primarily targets your core. Performing this standing challenges your balance and core engagement. Core strength is foundational for athletic performance and injury prevention.', '100051201', '100051201-Standing-Gluteus-Medius-Press-against-Wall-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Position yourself at the appropriate distance from a wall. 2. Begin in a standing position with good posture. 3. Execute the pressing motion for Standing Gluteus Medius Press Against Wall, extending through the target muscles. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 64, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Gluteus Medius Press Against Wall', 'lateral_raise, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d3a9f90b-4edc-495a-84b5-85fe8a687949', 'Hollow Rock', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts. Works well as both a primary exercise or accessory movement.', '56491201', '56491201-Hollow-Rock-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Set up in the starting position for Hollow Rock. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hollow_hold', 'Hollow Rock', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('d3ae7b05-6bb5-4f64-a0bf-b8e2a5458e65', 'Backward Neck Stretch', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'The Backward Neck Stretch provides a deep stretch for your neck, ideal for recovery and mobility work. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '76951201', '76951201-Backward-Neck-Stretch-(male)_Neck_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Move into the stretch position for Backward Neck Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'neck_stretch', 'Backward Neck Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d3b3add9-e988-4850-b5e3-4e00d9bf0234', 'Pick And Carry', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Pick And Carry is an explosive exercise that combines cardiovascular training with dynamic movement movements. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '52961201', '52961201-Pick-and-Carry_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Set up in the starting position for Pick And Carry. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Pick And Carry', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('d3b54220-816b-4cda-9acb-3b49f6da1c68', 'Seated Knee Up Rotation Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Seated Knee Up Rotation Stretch is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '19331201', '19331201-Seated-Knee-Up-Rotation-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Knee Up Rotation Stretch. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Knee Up Rotation Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d3c4b92e-26de-4fef-b463-cb8716637ba9', 'Mini Squat (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Leg training boosts metabolism and builds functional, real-world strength.', '84181201', '84181201-Mini-Squat-with-a-Chair-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'squat', 'Mini Squat With A Chair', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d3c7be63-33b0-45b7-a090-893ae34d83da', 'Supine Windshield Wipers', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Work your side abdominals with this movement exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '67051201', '67051201-Supine-Windshield-Wipers-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Lie face up (supine position) for Supine Windshield Wipers. 2. Set up in the starting position for Supine Windshield Wipers. 3. Execute the movement with proper form, focusing on your obliques. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Supine Windshield Wipers', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d3cb0070-eaaf-4766-b277-7d0e8dd0c5f2', 'Seated Thoracic Spine Flexion', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your thoracic spine, promoting flexibility and reducing muscle tightness. Your shoulders work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Include this in your routine for better mobility and reduced muscle tension.', '93331201', '93331201-Sitting-Thoracic-Spine-Flexion-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Thoracic Spine Flexion. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'spinal_stretch', 'Seated Thoracic Spine Flexion', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d3cd345f-7ed3-4d5e-a7a1-f8ae2d7d07cc', 'Weighted Sissy Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '8511201', '08511201-Weighted-Sissy-Squat_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Weighted Sissy Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d3ed0b2d-8726-4b3e-b0c2-3b02e06e04b3', 'Duck Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this stepping movement focusing on your full body. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '96451201', '96451201-Duck-Walk-(VERSION-2)-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Set up in the starting position for Duck Walk. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Duck Walk', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d3fdbd6d-99f8-4617-a8f3-6edaf42af5a7', 'Leg Under And Above Shoulders Bridge Pose', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '93321201', '93321201-Leg-Under-and-Above-Shoulders-Bridge-Pose-(female).mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'yoga', 'Leg Under And Above Shoulders Bridge Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d4023d47-c937-40e3-8be2-7f1b97fb4f81', 'Squat Step Out (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '80821201', '80821201-Resistance-Band-Squat-Step-Out-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Secure the resistance band appropriately for Resistance Band Squat Step Out. 2. Set up a box or step platform at the appropriate height. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'step_up', 'Squat Step Out', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d407c7cc-9a1e-46ef-b3c2-d9902059b88f', 'Standing Hands Up Side Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build power and athleticism with this high-intensity crunching exercise that challenges your entire body. The abs assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '89291201', '89291201-Standing-Hands-Up-Side-Crunch-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand with feet about shoulder-width apart. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Standing Hands Up Side Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d4090824-e4cf-4b8d-8583-8ecbb0ef86df', 'Lying Glute Stretch', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this stretching movement focused on hip extension. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '10561201', '10561201-Lying-Glute-Stretch_Hips-(female).mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Glute Stretch. 2. Set up in the starting position for Lying Glute Stretch. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'glute_stretch', 'Lying Glute Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d411e0ff-e41f-4b8e-bd20-2ece437bf010', 'Dynamic Knee Drop', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Dynamic Knee Drop is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '84971201', '84971201-Dynamic-Knee-Drop-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Move into the stretch position for Dynamic Knee Drop. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Dynamic Knee Drop', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d41ab2fa-6e24-4b80-b82e-5a9661581896', 'Lying Single Leg Lift', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '77341201', '77341201-Lying-Single-Leg-Lift-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Single Leg Lift. 2. Complete all reps on one side, then switch to the other side. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'leg_exercise', 'Lying Single Leg Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d4205b1a-4b87-462c-882f-6f57f618780e', 'Standing Hand To Big Toe Yoga Pose Utthita Hasta P', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Hand To Big Toe Yoga Pose Utthita Hasta P provides a deep stretch for your full body, ideal for recovery and mobility work. Performing this standing challenges your balance and core engagement. Flexibility work like this enhances performance and prevents stiffness.', '76071201', '76071201-Standing-Hand-to-Big-Toe-Yoga-Pose-Utthita-Hasta-P.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Move into the stretch position for Standing Hand To Big Toe Yoga Pose Utthita Hasta P. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Standing Hand To Big Toe Yoga Pose Utthita Hasta P', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d42e6f1d-88ed-4ce9-aaac-232c4aa4b3a6', 'Plank Side Jump', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '96771201', '96771201-Plank-Side-Jump-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears. This exercise is excellent for abs development. Variation: Plank Side Jump.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'plank', 'Plank Side Jump', 'side_plank, dead_bug, hollow_hold', FALSE, 'bodyweight', TRUE, 3, 60, 4, 70, 88, 95, 65),
('d4335430-6260-4b4a-92ec-f08b6580baea', 'Standing Palms In Press (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. The standing position engages your core for stability. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '4271201', '04271201-Dumbbell-Standing-Palms-In-Press_Shoulders-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Palms In Press. 2. Begin in a standing position with good posture. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 84, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Palms In Press', 'lateral_raise, front_raise, rear_delt_fly, upright_row', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('d4358b9b-29cb-4562-a1d6-f1075309b0e4', 'Single Leg Glute Bridge (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. Secondary activation of your hamstrings provides additional muscle engagement. The band creates increasing tension as it stretches, challenging the lockout. Strong legs are the foundation for athletic performance and functional fitness.', '25561201', '25561201-Resistance-Band-One-Leg-Glute-Bridge-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band One Leg Glute Bridge. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Single Leg Glute Bridge', 'hip_thrust, romanian_deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d439966d-9da0-4929-af00-f1853f7f1c4f', 'Front Raise Rope (Cable)', 'Shoulders', 'Cables', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. The cable setup allows you to adjust the angle of resistance. Shoulder development enhances both performance and upper body aesthetics.', '65431201', '65431201-Cable-Front-Raise-(rope-attachment)-(female)_Shoul.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'front_raise', 'Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('d43d8fc7-4c50-4992-96e3-528c174ea96d', 'Standing Knee Raise Back Kick', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Standing Knee Raise Back Kick builds reactive power and improves conditioning. You''ll also feel your hip flexors working to support the movement. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '84111201', '84111201-Standing-Knee-Raise-Back-Kick-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Raise the weight in the prescribed direction for Standing Knee Raise Back Kick. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Standing Knee Raise Back Kick', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d44d0527-6c5a-4e02-9a54-14fc933b8424', 'Sumo Squat (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '40051201', '40051201-Smith-Sumo-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Sumo Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'squat', 'Smith Sumo Squat', 'Sumo Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('d45d1813-5df1-4148-beb5-57eb0f641c4a', 'Sumo Deadlift (Barbell)', 'Legs', 'Barbell', '{"Glutes"}'::text[], '{"Quads","Lower Back","Inner Thighs"}'::text[], 'The Barbell Sumo Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength.', '1171201', '01171201-Barbell-Sumo-Deadlift_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Grip a barbell with hands at the appropriate width for Barbell Sumo Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'deadlift', 'Sumo Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('d460bf63-0fc2-45c2-950f-6cb2dde04344', 'Reverse Woodchop (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Cable Reverse Woodchop targets your obliques through a movement motion, building rotational core strength. Cables provide constant tension throughout the full range of motion. Building core stability helps with everything from heavy deadlifts to daily activities.', '81931201', '81931201-Cable-Reverse-Woodchop-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Adjust the cable machine to the correct height and attachment for Cable Reverse Woodchop. 2. Set up in the starting position for Cable Reverse Woodchop. 3. Execute the movement with proper form, focusing on your obliques. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'woodchop', 'Reverse Woodchop', 'russian_twist, pallof_press, cable_crunch', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('d46ab0e3-ce2a-4a45-a005-894e26b1339c', 'Seated Single Arm Row (Cable) - Alternating', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your biceps, rear delts provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Cables provide constant tension throughout the full range of motion. Back development is crucial for pulling strength and overall upper body function.', '2141201', '02141201-Cable-Seated-One-Arm-Alternate-Row_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated One Arm Alternate Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Alternate between sides/arms/legs with each repetition. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'arm_exercise', 'Seated Single Arm Row - Alternating', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('d4702757-baa0-4c25-bc22-564d63779ec6', 'Reverse Lunge (leg Kick)', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength. Excellent for pre-exhausting the target muscle before compound lifts.', '6761201', '06761201-Reverse-Lunge-(leg-kick)-(female)_Thighs-FIX2_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Reverse Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d470b708-3ac8-4856-bb32-40e78049d4e9', 'Twisting Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{}'::text[], 'The Twisting Crunch targets your obliques through a crunching motion, building rotational core strength. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '60161201', '60161201-Twisting-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout. This exercise is excellent for obliques development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Twisting Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d474112b-ffcd-47d0-8224-c115723dc6aa', 'Walking Calf Raise', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'The Bodyweight Walking Calf Raise isolates your calf muscles through a raising motion. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '57001201', '57001201-Bodyweight-Walking-Calf-Raise_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Lower your heels below the platform to get a full stretch. 2. Rise up onto your toes as high as possible, squeezing your calves. 3. Lower with control and repeat. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Stretch', 80, 5, 7, FALSE, TRUE, 'calf_raise', 'Walking Calf Raise', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d4800981-30f7-47e2-84b8-603e4818a7fc', 'Row - Close Grip (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Band Close Grip Row is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Resistance bands provide accommodating resistance that increases through the range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '41451201', '41451201-Band-Close-Grip-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Secure the resistance band appropriately for Band Close Grip Row. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', 'Pull', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, 'Neutral', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'general_exercise', 'Row - Close Grip', 'Row - Close Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d48811c4-623d-43dd-8b15-0077fad0988b', 'Wheel Pose Urdhva Dhanurasana', 'Full Body', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Shoulders","Quads"}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Excellent for pre-exhausting the target muscle before compound lifts.', '14931201', '14931201-Wheel-Pose-Urdhva-Dhanurasana-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Move into the stretch position for Wheel Pose Urdhva Dhanurasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Wheel Pose Urdhva Dhanurasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d488987b-ce3d-4cec-a297-262d0d2b3ed9', 'Prayer Push Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity pushing exercise that challenges your entire body. Secondary activation of your quads, calves provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '55901201', '55901201-Prayer-Push-Jump-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Set up in the starting position for Prayer Push Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 35, 9, 8, TRUE, TRUE, 'boxing', 'Prayer Push Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d48a597a-6210-4a6e-98a2-58494d57f566', 'Standing Ankle Circles', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Standing Ankle Circles isolates your calf muscles through a movement motion. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '81881201', '81881201-Standing-Ankle-Circles-(VERSION-2)-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Ankle Circles. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Ankle Circles', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d48d6e0d-8b6f-43d5-9b1c-8768a5ce28aa', 'Kneeling Ankle Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Kneeling Ankle Stretch isolates your calf muscles through a stretching motion. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '67321201', '67321201-Kneeling-Ankle-Stretch-(male)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Kneeling Ankle Stretch. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Kneeling Ankle Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d48dbf7c-2636-487a-b5d8-71b81f735f22', 'Incline Push Up - Close Grip (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'This pushing movement isolates your triceps for improved arm development. You''ll also feel your chest, front delts working to support the movement. The incline angle shifts emphasis toward the upper portion of the target muscles. Dedicated arm training builds both strength and muscular definition.', '71361201', '71361201-Incline-Close-Grip-Push-Up-with-Chair_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Keep your body in a straight line from head to heels throughout. 4. Lower your chest toward the floor by bending your elbows. 5. Push through your palms to return to the starting position. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'push_up', 'Incline Push Up With Chair - Close Grip', 'Incline Push Up With Chair - Close Grip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d498bff9-3cc6-43bd-a77f-460994ee11da', 'Shuffle Diagonal Reaches', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Shuffle Diagonal Reaches builds reactive power and improves conditioning. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '67831201', '67831201-Shuffle-Diagonal-Reaches-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Set up in the starting position for Shuffle Diagonal Reaches. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'shuffle', 'Shuffle Diagonal Reaches', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d4a0403a-15e6-402f-8b41-7d287208d99d', 'Handstand Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your delts with the Handstand Push Up, an effective shoulder pushing exercise. You''ll also feel your triceps, front delts working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '4711201', '04711201-Handstand-Push-Up_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'yoga', 'Handstand Push Up', 'bench_press, chest_fly, dip, tricep_pushdown', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d4a05562-78b5-4e7f-8fe4-55f1332945cd', 'Hang Power Clean (Barbell)', 'Full Body', 'Barbell', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. Secondary activation of your quads, glutes, traps provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Full body exercises are time-efficient and build functional, real-world strength.', '57041201', '57041201-Barbell-Hang-Power-Clean_Weightlifting_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Grip a barbell with hands at the appropriate width for Barbell Hang Power Clean. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Perform the concentric (lifting) phase explosively with maximum effort. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 9, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'clean', 'Hang Power Clean', 'clean, hang_clean, deadlift', FALSE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('d4acea20-69da-4f64-b40a-1394b5be95a9', 'Run (Treadmill)', 'Full Body', 'Treadmill', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Can be modified for beginners or progressed for advanced athletes.', '21971201', '21971201-Run-on-Treadmill-(female)_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Set up in the starting position for Run On Treadmill. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'treadmill', 'Run On Treadmill', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('d4ada8f1-345a-420d-b736-70d65a3ed4df', 'Stepjack Front Raise', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'This dynamic raising movement gets your heart rate up while developing explosive strength. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '56261201', '56261201-Stepjack-Front-Raise-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'front_raise', 'Stepjack Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d4baa964-0557-4beb-8749-065a84d47c02', 'Standing Bicep Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. The forearms assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '2941201', '02941201-Dumbbell-Biceps-Curl_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'bicep_curl', 'Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d4bcbccf-f9b1-42c1-8e75-1e7e38bbb4a6', 'Seated Air Bike (Chair)', 'Core', 'Air Bike, Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Being seated provides stability, allowing you to focus on the working muscles. A strong core improves posture, protects your spine, and enhances all other lifts. This variation is excellent for building mind-muscle connection.', '82051201', '82051201-Sitting-Air-Bike-on-a-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 20, 9, 8, FALSE, TRUE, 'cycling', 'Seated Air Bike On A Chair', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('d4c8a7c6-3d93-4222-988c-5e3729144b38', 'Seated Good Morning (Chair)', 'Back', 'Chair', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'This movement movement works your hamstrings for balanced leg development. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Lower body strength improves everything from walking to heavy compound lifts.', '104961201', '104961201-Seated-Good-Morning-on-Chair-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'back_extension', 'Seated Good Morning On Chair', 'romanian_deadlift, back_extension, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d4cc44f8-c02f-4d7e-975d-ab199b1b9f2d', 'High Knee Skips', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Secondary activation of your hip flexors provides additional muscle engagement. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '4771201', '04771201-High-Knee-Skips-(female)_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up in the starting position for High Knee Skips. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'High Knee Skips', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d4d7b731-6ae7-403f-94d0-2d04f3e738fa', 'Butt Kick with Row', 'Back', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Elevate your training with this rowing exercise that develops speed, power, and coordination. Secondary activation of your hamstrings provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '57081201', '57081201-Butt-Kick-with-Row-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control. An effective movement for your plyometrics routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_kickback', 'Butt Kick With Row', 'high_knees, jumping_jack, running', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d4e08293-4203-48ee-afbe-8b10258263de', 'Arm Crossover Chest Out', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. You''ll also feel your shoulders, core working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '66301201', '66301201-Arm-Crossover-Chest-Out-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Set up in the starting position for Arm Crossover Chest Out. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', 'Push', NULL, 'Compound', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Arm Crossover Chest Out', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d4f6e57b-9358-44e2-b4be-b15ca6ae5cd3', 'Standing Single Arm Triceps Stret (Resistance Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. The standing position engages your core for stability. The band creates increasing tension as it stretches, challenging the lockout. Full body exercises are time-efficient and build functional, real-world strength.', '107411201', '107411201-Resistance-Band-Standing-Single-Arm-Triceps-Stret.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Secure the resistance band appropriately for Resistance Band Standing Single Arm Triceps Stret. 2. Stand with feet about shoulder-width apart. 3. Complete all reps on one side, then switch to the other side. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Single Arm Triceps Stret', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d5018f93-745b-44e4-8f3e-699a78a88299', 'Decline Chest Press (Plate Machine)', 'Chest', 'Machine', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Lever Decline Chest Press is a pressing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. Declining shifts the emphasis to hit the muscles from a different angle. The machine guides your movement path for safer, more controlled repetitions. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '13001201', '13001201-Lever-Decline-Chest-Press_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Decline Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', 'Press', 'Push', NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 81, 7, 8, TRUE, TRUE, 'decline_press', 'Lever Decline Chest Press', 'bench_press, incline_bench_press, chest_fly, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('d505dbe5-49ac-489c-81e1-a704efd306de', 'Lying Bicep Curl', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '90001201', '90001201-Lying-Bicep-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'Lying Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d509ba01-12d0-4b12-ac71-e1fa28d74858', 'Seated Upright Circle Shift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Seated Upright Circle Shift is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '81221201', '81221201-Seated-Upright-Circle-Shift-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Upright Circle Shift. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Upright Circle Shift', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d509c86a-4510-4a67-ba2b-eb795a477cad', 'Single Leg Deadlift Lunge', 'Legs', 'Bodyweight', '{"Quads","Glutes","Hamstrings"}'::text[], '{"Traps"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. You''ll also feel your glutes, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '65341201', '65341201-Single-Leg-Deadlift-Lunge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps on one side, then switch to the other side. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'deadlift', 'Single Leg Deadlift Lunge', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d52d7e5e-12a2-4a9b-b41b-7f566af52e9c', 'Hip Roll Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Hip Roll Plank, focusing on your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '43851201', '43851201-Hip-Roll-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form. Great for building strength in your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Hip Roll Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('d533e8ca-960e-4a15-8bc7-f954143829e1', 'Pulsing Side Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '61631201', '61631201-Pulsing-Side-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pulse', 'Pulsing Side Lunge', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d5357b09-d491-4997-ad5e-feee8a9fb20a', 'Lying Curl (Cable)', 'Legs', 'Cables', '{"Hamstrings"}'::text[], '{"Forearms"}'::text[], 'The Cable Lying Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '1831201', '01831201-Cable-Lying-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lying Curl. 2. Lie down in the appropriate position for Cable Lying Curl. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'leg_curl', 'Lying Curl', 'romanian_deadlift, hip_thrust', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('d543a4e5-471d-41e1-b68c-6809edd7f74a', 'Plank Knee Tuck - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. You''ll also feel your shoulders, lower back working to support the movement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '75311201', '75311201-Plank-Alternate-Knee-Tuck-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank Knee Tuck - Alternating', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('d5450128-3569-4799-a4d4-2cf3234cdf3f', 'Standing Up Raise Side Open Arms', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your delts. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '85591201', '85591201-Standing-Up-Raise-Side-Open-Arms-(female)_Shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand with feet about shoulder-width apart. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'arm_exercise', 'Standing Up Raise Side Open Arms', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d561360e-de3f-4bc5-85d0-af7d4ef0435f', 'Seated Hands To Feet Hold', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '81251201', '81251201-Seated-Hands-to-Feet-Hold-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Hands To Feet Hold. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Hands To Feet Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('d564717f-4ce7-4ea4-8d10-139cad5e9f2e', 'Straight Leg Deadlift (Dumbbell)', 'Back', 'Dumbbells', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Dumbbell Straight Leg Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Lower body strength improves everything from walking to heavy compound lifts.', '4341201', '04341201-Dumbbell-Straight-Leg-Deadlift_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Straight Leg Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Straight Leg Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('d575f0a0-3343-4385-8fdb-26ff9b99832c', 'Fly With Chest Supported (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. Secondary activation of your front delts provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. A well-developed chest contributes to upper body strength and aesthetics.', '38681201', '38681201-Cable-Fly-with-Chest-Supported_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Adjust the cable machine to the correct height and attachment for Cable Fly With Chest Supported. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_exercise', 'Fly With Chest Supported', 'bench_press, incline_bench_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('d5a0a0e7-f944-46ba-87a2-0880f3abef8a', 'Leg Lift Tap Arms Circle - Alternating', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. Works well as both a primary exercise or accessory movement. Consistency with this movement will yield noticeable results.', '89031201', '89031201-Alternate-Leg-Lift-Tap-Arms-Circle-(male)_Plyometr.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate Leg Lift Tap Arms Circle. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Leg Lift Tap Arms Circle - Alternating', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d5b916e2-3c73-4884-b6ab-e1e10dd40376', 'Pike Push Up From Deficit (Step Platform)', 'Chest', 'Step Platform', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise works your delts for improved shoulder strength and aesthetics. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '77481201', '77481201-Pike-Push-up-from-deficit-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Pike Push Up From Deficit', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d5c0fd7d-dea1-4f11-892d-5a072acbdf13', 'Elevated Mountain Climber With Hands On A Bench (Step Platform)', 'Core', 'Step Platform', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'Strengthen your midsection with this climbing movement that works your abs. Your hip flexors, shoulders work as secondary movers, adding to the training stimulus. Building core stability helps with everything from heavy deadlifts to daily activities.', '83461201', '83461201-Elevated-Mountain-Climber-with-Hands-on-a-Bench-(m.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. From plank position, drive one knee toward your chest. 2. Quickly switch legs, bringing the other knee forward. 3. Continue alternating at a quick pace while maintaining plank form. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'mountain_climber', 'Elevated Mountain Climber With Hands On A Bench', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d5c303c4-61b9-4194-ad9c-9fd66a7c164e', 'Twist Crunch Legs Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{}'::text[], 'Build rotational power and define your waistline with the Twist Crunch Legs Up. The hip flexors assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '8191201', '08191201-Twist-Crunch-Legs-Up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Twist Crunch Legs Up', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d5c4f381-0ec7-4bde-80aa-154be872843c', 'Standing Switching Vertical Stacked Hand', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This full-body movement exercise challenges multiple muscle groups simultaneously. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Compound movements like this develop coordination, power, and overall fitness.', '94821201', '94821201-Standing-Switching-Vertical-Stacked-Hand-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Switching Vertical Stacked Hand. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Switching Vertical Stacked Hand', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d5ca6110-4ce3-4f57-afff-cab79cad5bac', 'Seated Half Bicep Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. The seated position helps isolate the target muscles by removing momentum. The dumbbell variation provides freedom of movement and greater range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '105161201', '105161201-Dumbbell-Seated-Upper-Half-Biceps-Curl_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Upper Half Biceps Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'bicep_curl', 'Seated Upper Half Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d5cd46a8-8c0a-4219-b61e-ef3311b60edd', 'Standing Serratus Training (Against Wall)', 'Full Body', 'Wall', '{"Full Body"}'::text[], '{}'::text[], 'Build a stronger chest with this movement movement that develops pressing power. The standing position engages your core for stability. A well-developed chest contributes to upper body strength and aesthetics.', '92001201', '92001201-Standing-Serratus-Training-on-the-Wall-(female)_Ch.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Position yourself at the appropriate distance from a wall. 2. Begin in a standing position with good posture. 3. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum. This exercise is excellent for full body development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 44, 7, 8, TRUE, TRUE, 'serratus', 'Standing Serratus Training On The Wall', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d5d7eccc-c83d-4226-a66d-2cb8513f9faa', 'Butterfly Forward Leaning', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target your adductors with this flying stretch that helps restore range of motion. You''ll also feel your hips working to support the movement. Include this in your routine for better mobility and reduced muscle tension. Progress gradually by increasing resistance over time.', '95261201', '95261201-Butterfly-Forward-Leaning-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'groin_stretch', 'Butterfly Forward Leaning', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d5ddf3fe-801d-49ba-ad92-921857b2dbec', 'Arm Curl To Ears (TRX)', 'Arms', 'TRX', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Suspender Arm Curl To Ears is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Suspension training adds instability, increasing core activation throughout. Arm strength supports grip, pulling, and pushing in compound movements.', '11081201', '11081201-Suspender-Arm-Curl-to-Ears-(female)_Upper-arms.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Arm Curl To Ears. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'bicep_curl', 'Suspender Arm Curl To Ears', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('d5df7fa0-f6e7-4c66-b371-3b8aacf73f8d', 'Standing Wide Good Morning (advanced)', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'Target your hamstrings with this movement stretch that helps restore range of motion. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Include this in your routine for better mobility and reduced muscle tension.', '88691201', '88691201-Standing-Wide-Good-Morning-(advanced)-(female)_Str.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Begin in a standing position with good posture. 2. Move into the stretch position for Standing Wide Good Morning. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_extension', 'Standing Wide Good Morning', 'romanian_deadlift, back_extension, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d5e3083f-0309-48e8-b320-97e21f9cbb0f', 'Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, lats working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '8611201', '08611201-Cable-Seated-Row_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'cable_row', 'Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('d5f054c5-c7ab-4240-93d7-15ad3f4ababe', 'Cobra To Child Pose', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Cobra To Child Pose provides a deep stretch for your back, ideal for recovery and mobility work. The hips assist throughout the movement, making this a well-rounded exercise. Include this in your routine for better mobility and reduced muscle tension.', '79121201', '79121201-Cobra-to-Child-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Move into the stretch position for Cobra To Child Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Cobra To Child Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d600cc69-37fd-4128-8c94-7681fb7a05bd', 'Standing Butt Kick Kickback', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Rear Delts"}'::text[], 'The Standing Butt Kick Kickback is an explosive exercise that combines cardiovascular training with dynamic kicking movements. Your hamstrings work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '97831201', '97831201-Standing-Butt-Kick-Kickback-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand with feet about shoulder-width apart. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'glute_kickback', 'Standing Butt Kick Kickback', 'high_knees, jumping_jack, running', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d60750b0-d11d-49df-a79d-6e19c03a73ad', 'Seated Front Leg Lift Under Knee Tap (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. The seated position helps isolate the target muscles by removing momentum. Great for improving athletic performance, burning calories, and building conditioning.', '90801201', '90801201-Sitting-Front-Leg-Lift-Under-Knee-Tap-on-a-Chair-(.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Keep tension on the target muscles throughout. Great for building strength in your full body.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'leg_exercise', 'Seated Front Leg Lift Under Knee Tap On A Chair (', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d62b9543-39e6-48e9-b221-b6dd96d47a80', 'Step Up (Kettlebell)', 'Legs', 'Kettlebell, Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this stepping exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The kettlebell''s offset center of mass increases the stability challenge. Strong legs are the foundation for athletic performance and functional fitness.', '44401201', '44401201-Kettlebell-Step-up-(VERSION-2)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Select an appropriately weighted kettlebell for Kettlebell Step Up. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'step_up', 'Step Up', 'lunge, split_squat, squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('d6323db2-b6dd-4c27-88a6-686a6d3a9f3a', 'Landmine Standing Side Bend (Landmine)', 'Core', 'Landmine Attachment, Barbell', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Landmine Standing Side Bend is a core movement exercise that primarily targets your abs. Your abs work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. Building core stability helps with everything from heavy deadlifts to daily activities.', '80221201', '80221201-Landmine-Standing-Side-Bend-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Landmine Standing Side Bend. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'side_bend', 'Landmine Standing Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('d6367c78-4f72-41cf-972e-0dda95f7ce30', 'Standing Single Arm Shoulder Flexion (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{}'::text[], 'Develop functional strength with the Resistance Band Standing Single Arm Shoulder Flexion, a comprehensive flexion exercise. Performing this standing challenges your balance and core engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Full body exercises are time-efficient and build functional, real-world strength.', '64391201', '64391201-Resistance-Band-Standing-Single-Arm-Shoulder-Flexi.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Standing Single Arm Shoulder Flexion. 2. Begin in a standing position with good posture. 3. Complete all reps on one side, then switch to the other side. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Single Arm Shoulder Flexion', 'lateral_raise, shoulder_press, front_raise', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d63a73e0-6152-4eeb-970b-3e83a5938e90', 'Single Leg Floor Calf Raise (Smith Machine)', 'Legs', 'Smith Machine', '{Calves}'::text[], '{Soleus}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '26721201', '26721201-Smith-One-Leg-Floor-Calf-Raise-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith One Leg Floor Calf Raise. 2. Position yourself on the floor for Smith One Leg Floor Calf Raise. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'calf_raise', 'Smith Single Leg Floor Calf Raise', 'One Leg Floor Calf Raise', FALSE, 'barbell', FALSE, 3, 60, 2, 80, 75, 20, 88),
('d63d58f3-90df-4927-b7fa-22c268e4830b', 'Lying Bent Leg Circle - Alternating', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Lying Alternate Bent Leg Circle is a lower body movement exercise that targets your delts. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '79051201', '79051201-Lying-Alternate-Bent-Leg-Circle-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Alternate Bent Leg Circle. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Lying Bent Leg Circle - Alternating', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d643acd5-9185-469e-91ff-d434c5b69016', 'Downward Punch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. The shoulders assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '51091201', '51091201-Downward-Punch-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Set up in the starting position for Downward Punch. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Downward Punch', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d6462f3b-ebe4-4848-9f1b-a65f69522e44', 'Forward Backward Duck Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this stepping movement focusing on your full body. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '94661201', '94661201-Forward-Backward-Duck-Walk-(VERSION-2)-(female)_Hi.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up in the starting position for Forward Backward Duck Walk. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Forward Backward Duck Walk', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d648a089-9f38-4a9d-aa95-79f340a6a498', 'Seated Overhead Press (Barbell)', 'Shoulders', 'Barbell, Flat Bench', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Barbell Seated Overhead Press, an effective shoulder pressing exercise. Your triceps work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Using a barbell provides stability for progressive overload. Strong shoulders improve overhead strength and support nearly all upper body movements.', '911201', '00911201-Barbell-Seated-Overhead-Press_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Overhead Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Seated', NULL, 'Overhand', 'Standard', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 99, 7, 9, TRUE, FALSE, 'shoulder_press', 'Seated Overhead Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('d64d7349-36b2-4933-b8f7-7ca247b0aa52', 'Straight Leg Kickback (kneeling)', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Rear Delts"}'::text[], 'This kicking exercise isolates your glutes for improved hip strength and power. Secondary activation of your hamstrings provides additional muscle engagement. Kneeling helps eliminate lower body momentum from the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '14771201', '14771201-Straight-Leg-Kickback-(kneeling)_Hips-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Straight Leg Kickback', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d650ded0-30d6-4459-a376-f838708b05d7', 'Twist Turn Slam', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'This dynamic twisting movement gets your heart rate up while developing explosive strength. You''ll also feel your abs working to support the movement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '55461201', '55461201-Twist-Turn-Slam-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Rotate your torso through the movement pattern for Twist Turn Slam. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Twist Turn Slam', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d65b858a-c806-4ed5-b7d8-165c24985567', 'Triceps Extension - Pulldown (Machine)', 'Arms', 'Tricep Extension Machine', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. The fixed path allows you to focus purely on muscular effort. Dedicated arm training builds both strength and muscular definition.', '36141201', '36141201-Lever-Triceps-Extension-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lever Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('d67ad70d-1874-474c-9de7-72b60bef967f', 'Glute Bridge Walk', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This bridging exercise isolates your glutes for improved hip strength and power. Your hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '65701201', '65701201-Glute-Bridge-Walk-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout. Ideal for glutes strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Walk', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d68200bd-295c-4701-b403-a5123552db56', 'Lying Toe Touch Floor - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '60911201', '60911201-Lying-Alternate-Toe-Touch-Floor-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Position yourself on the floor for Lying Alternate Toe Touch Floor. 2. Lie down in the appropriate position for Lying Alternate Toe Touch Floor. 3. Alternate between sides/arms/legs with each repetition. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'toe_touch', 'Lying Toe Touch Floor - Alternating', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d6821f99-c7d3-4fc4-9f71-44d52e163f3b', 'Standing Balance Side To Front Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Standing Balance Side To Front Leg Raise is an explosive exercise that combines cardiovascular training with dynamic raising movements. You''ll also feel your hip flexors working to support the movement. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '77401201', '77401201-Standing-Balance-Side-to-Front-Leg-Raise-(male)_Pl.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Stand with feet about shoulder-width apart. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Standing Balance Side To Front Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('d6a202ad-3729-451a-9d07-34f06554bdee', 'JM Bench Press (EZ Bar)', 'Chest', 'EZ Bar, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The EZ Barbell JM Bench Press is an arm pressing exercise targeting your chest. You''ll also feel your triceps, front delts working to support the movement. Barbells enable bilateral loading for building raw strength. Dedicated arm training builds both strength and muscular definition.', '4501201', '04501201-EZ-Barbell-JM-Bench-Press_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'bench_press', 'EZ JM Bench Press', 'EZ JM Bench Press', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('d6a307be-7f63-40ce-8922-90a350c08688', 'Preacher Curl - Reverse Grip (EZ Bar)', 'Arms', 'EZ Bar, Preacher Bench', '{"Biceps"}'::text[], '{}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. The forearms assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. Arm strength supports grip, pulling, and pushing in compound movements. Keep your core engaged throughout the exercise.', '4521201', '04521201-EZ-Barbell-Reverse-grip-Preacher-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Reverse Grip Preacher Curl. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'preacher_curl', 'EZ Preacher Curl - Reverse Grip', 'EZ Preacher Curl - Reverse Grip', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('d6b91631-5c52-4713-a1be-a2521076aee5', 'Chest Dip On High Parallel Bars - Wide Grip (Dip Bars)', 'Chest', 'Dip Bars', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This dipping exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts work as secondary movers, adding to the training stimulus. Chest strength improves pushing power for sports, daily tasks, and other lifts. Progress gradually by increasing resistance over time.', '23631201', '23631201-Wide-Grip-Chest-Dip-on-High-Parallel-Bars_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Chest Dip On High Parallel Bars - Wide Grip', 'Chest Dip On High Parallel Bars - Wide Grip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d6c3916c-78b2-4301-a5ff-28e4ab21a8ea', 'Kneeling Leg External Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build leg strength with this rotation movement focusing on your rotator cuff. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '77641201', '77641201-Kneeling-Leg-External-Rotation-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Rotate your torso through the movement pattern for Kneeling Leg External Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Kneeling Leg External Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d6d8d255-9d89-49e7-9d6a-0b34c481a443', 'Inner Thigh Tap To Chest Open', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements. A staple exercise that belongs in most training programs.', '80321201', '80321201-Inner-Thigh-Tap-to-Chest-Open-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Set up in the starting position for Inner Thigh Tap To Chest Open. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_adduction', 'Inner Thigh Tap To Chest Open', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d6e734cb-6da5-4318-b4eb-8a1f618c35fa', 'Standing Arms Flinging', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Standing Arms Flinging, an effective shoulder movement exercise. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '32601201', '32601201-Standing-Arms-Flinging-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Arms Flinging. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Arms Flinging', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d714897e-9122-4db0-90a2-bf53667146d4', 'Lying Bent Arms Pullover (EZ Bar)', 'Chest', 'EZ Bar, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger back with this pulling movement targeting your chest. The lats, triceps assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. Back development is crucial for pulling strength and overall upper body function.', '70841201', '70841201-EZ-Bar-Lying-Bent-Arms-Pullover-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip the EZ bar on the angled portions for a comfortable wrist position. 2. Lie down in the appropriate position for EZ Bar Lying Bent Arms Pullover. 3. With arms slightly bent, lower the weight behind your head in an arc. 4. Pull the weight back over your chest, squeezing your lats and chest. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'pullover', 'EZ Bar Lying Bent Arms Pullover', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('d7167f96-3920-4cc2-b21e-8ef1d8ec2931', 'Standing Hand Out Cross Kick', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity kicking exercise that challenges your entire body. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '84081201', '84081201-Standing-Hand-Out-Cross-Kick-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Hand Out Cross Kick. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'boxing', 'Standing Hand Out Cross Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d72843a6-7ac1-450f-9268-ae092454371d', 'Single Arm Twisted Clean And Press (Barbell)', 'Full Body', 'Barbell', '{"Full Body"}'::text[], '{"Shoulders","Quads","Hamstrings"}'::text[], 'This full-body pressing exercise challenges multiple muscle groups simultaneously. The shoulders, legs assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. Full body exercises are time-efficient and build functional, real-world strength.', '28141201', '28141201-Barbell-One-Arm-Twisted-Clean-and-Press_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Grip a barbell with hands at the appropriate width for Barbell One Arm Twisted Clean And Press. 2. Execute the pressing motion for Barbell One Arm Twisted Clean And Press, extending through the target muscles. 3. Complete all reps on one side, then switch to the other side. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'russian_twist', 'Single Arm Twisted Clean And Press', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('d72baff4-611c-4941-9f12-dea72b58b38a', 'Side Bend (Dumbbell)', 'Core', 'Dumbbells', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. You''ll also feel your abs working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Building core stability helps with everything from heavy deadlifts to daily activities.', '4071201', '04071201-Dumbbell-Side-Bend_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Bend. 2. Set up in the starting position for Dumbbell Side Bend. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'side_bend', 'Side Bend', 'russian_twist, woodchop, oblique_crunch', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('d74f3777-73b8-4697-80ad-98f2ebbd777c', 'Chest Press - Close Grip (TRX)', 'Chest', 'TRX', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Suspender Close Grip Chest Press is a pressing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. Suspension training adds instability, increasing core activation throughout. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '11111201', '11111201-Suspender-Close-grip-Chest-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Close Grip Chest Press. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'bench_press', 'Suspender Chest Press - Close Grip', 'Suspender Chest Press - Close Grip', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('d759f396-b479-42d4-9906-872005793d2a', 'Upright Row (Cable)', 'Shoulders', 'Cables', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'Build stronger shoulders with this rowing movement focusing on your delts. Your traps work as secondary movers, adding to the training stimulus. The cable setup allows you to adjust the angle of resistance. Shoulder development enhances both performance and upper body aesthetics.', '22321201', '22321201-Cable-Upright-Row-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Upright Row. 2. Pull the weight straight up along your body, leading with your elbows. 3. Raise until elbows reach shoulder height, then lower with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'upright_row', 'Upright Row', 'lateral_raise, shoulder_press, shrug', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('d7709dd5-0aee-446e-9d67-984a5ca9021e', 'Standing Up Straight Crossovers (Cable)', 'Full Body', 'Cables', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Secondary activation of your shoulders, core provides additional muscle engagement. Performing this standing challenges your balance and core engagement. Cables provide constant tension throughout the full range of motion. Great for improving athletic performance, burning calories, and building conditioning.', '12691201', '12691201-Cable-Standing-Up-Straight-Crossovers_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Up Straight Crossovers. 2. Begin in a standing position with good posture. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'chest_fly', 'Standing Up Straight Crossovers', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('d776cac2-95fb-42a4-9701-b4c3eb088e55', 'Ring Inverted Row - Neutral Grip (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps assist throughout the movement, making this a well-rounded exercise. A strong back improves posture, prevents injury, and balances pressing movements. Can be modified for beginners or progressed for advanced athletes.', '76491201', '76491201-Ring-Neutral-Grip-Inverted-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Use a neutral grip with palms facing each other. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Ring Inverted Row - Neutral Grip', 'Ring Inverted Row - Neutral Grip', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('d77ab7f4-e583-4985-93bc-84ff5a6ff522', 'Deadlift (Cable)', 'Back', 'Cables', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. The cable setup allows you to adjust the angle of resistance. Leg training boosts metabolism and builds functional, real-world strength.', '1571201', '01571201-Cable-Deadlift_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 95, 7, 8, TRUE, TRUE, 'woodchop', 'Deadlift', 'romanian_deadlift, leg_curl, back_extension, hip_thrust, good_morning', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('d77ba52a-f066-4dee-918d-a005f7a96c2d', 'Outward Hand Wave', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Outward Hand Wave is an explosive exercise that combines cardiovascular training with dynamic movement movements. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '68951201', '68951201-Outward-Hand-Wave-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Set up in the starting position for Outward Hand Wave. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Outward Hand Wave', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d7898e2f-1f8a-4232-94ef-72343644fc28', 'Straight Arm Double Knee Drive', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning. Quality repetitions are more important than quantity.', '66641201', '66641201-Straight-Arm-Double-Knee-Drive-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Set up in the starting position for Straight Arm Double Knee Drive. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Straight Arm Double Knee Drive', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d7963124-beee-440d-a3f3-693440064aaf', 'Side And Front In Out', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts. Aim for full range of motion on every rep.', '68031201', '68031201-Side-and-Front-In-Out_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Set up in the starting position for Side And Front In Out. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side And Front In Out', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d7985b87-2448-4a9b-adb0-eccfa1af67ed', 'Standing Balance Single Crossover Pendulum Leg', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'The Standing Balance Single Crossover Pendulum Leg is an explosive exercise that combines cardiovascular training with dynamic movement movements. The shoulders, core assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '65901201', '65901201-Standing-Balance-Single-Crossover-Pendulum-Leg-(ma.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Balance Single Crossover Pendulum Leg. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'chest_fly', 'Standing Balance Single Crossover Pendulum Leg', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d7a7f81c-3406-4e99-a581-cf75798f4c9b', 'Leg Front Lift Jack', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Leg Front Lift Jack builds reactive power and improves conditioning. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '57121201', '57121201-Leg-Front-Lift-Jack-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Set up in the starting position for Leg Front Lift Jack. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'leg_exercise', 'Leg Front Lift Jack', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d7b10260-fd9d-4df7-b8bb-dd3d80a21e7d', 'Lying Leg Curl (Machine)', 'Legs', 'Leg Curl Machine', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Secondary activation of your calves provides additional muscle engagement. Performing this lying down removes momentum for stricter form. The machine guides your movement path for safer, more controlled repetitions. Leg training boosts metabolism and builds functional, real-world strength.', '22231201', '22231201-Lever-Lying-Leg-Curl-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Lying Leg Curl. 2. Lie down in the appropriate position for Lever Lying Leg Curl. 3. Curl your heels toward your glutes by bending at the knees. 4. Squeeze your hamstrings at peak contraction. 5. Extend legs back out with control. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 88, 7, 8, TRUE, TRUE, 'leg_curl', 'Lever Lying Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('d7b9b7b2-fd5d-46d9-add0-4fee7f834366', 'Hamstring Curl Jack (Gymnastic Rings) - Alternating', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'This dynamic curling movement gets your heart rate up while developing explosive strength. Secondary activation of your forearms provides additional muscle engagement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '85761201', '85761201-Alternating-Hamstring-Curl-Jack-(male)_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', 'Curl', 'Pull', NULL, NULL, NULL, 1, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 58, 9, 8, TRUE, TRUE, 'leg_curl', 'Hamstring Curl Jack - Alternating', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', FALSE, 3, 60, 4, 68, 85, 85, 70),
('d7c967e7-01bf-4966-bc22-cc85868892c9', 'Standing Hip Frontal Rotation Raise - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Develop functional strength with the Standing Hip Frontal Rotation Alternate Raise, a comprehensive raising exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Compound movements like this develop coordination, power, and overall fitness.', '78421201', '78421201-Standing-Hip-Frontal-Rotation-Alternate-Raise-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'glute_exercise', 'Standing Hip Frontal Rotation Raise - Alternating', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d7d0b832-fbee-4712-87db-926b1292b659', 'Single Leg Transverse Bend', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your hip flexors. You''ll also feel your core working to support the movement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '17031201', '17031201-Single-Leg-Transverse-Bend-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for Single Leg Transverse Bend. 3. Execute the movement with proper form, focusing on your hip flexors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'leg_exercise', 'Single Leg Transverse Bend', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d7d81c4c-445a-45e8-a301-47ed9cd04164', 'Slight Squat Tip Toes', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements. Focus on controlled form throughout each repetition.', '84061201', '84061201-Slight-Squat-Tip-Toes-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep. A solid choice for plyometrics day.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'calf_raise', 'Slight Squat Tip Toes', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d7eb53c3-4ae2-40c4-b944-eb30c689fd7f', 'Lying Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '49751201', '49751201-Lying-Leg-Raise-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Leg Raise. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d7efc1a7-e074-4a9f-a885-e4d347c73d2e', 'Anti Rotation Dead Bug (Resistance Band)', 'Core', 'Resistance Band, Anchor Point', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This rotation movement focuses on your obliques for a complete core workout. The hip flexors assist throughout the movement, making this a well-rounded exercise. The band creates increasing tension as it stretches, challenging the lockout. Building core stability helps with everything from heavy deadlifts to daily activities.', '38661201', '38661201-Resistance-Band-Anti-Rotation-Dead-Bug_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Secure the resistance band appropriately for Resistance Band Anti Rotation Dead Bug. 2. Rotate your torso through the movement pattern for Resistance Band Anti Rotation Dead Bug. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'dead_bug', 'Anti Rotation Dead Bug', 'woodchop, plank, dead_bug', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d7f6d0a5-fcad-4fd0-a6f4-b0c775436473', 'Lying 90 To 90 Switch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Target your hips with this movement stretch that helps restore range of motion. You''ll also feel your glutes working to support the movement. The lying position provides back support and helps isolate the target muscles. Include this in your routine for better mobility and reduced muscle tension.', '82501201', '82501201-Lying-90-to-90-Switch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying 90 To 90 Switch. 2. Move into the stretch position for Lying 90 To 90 Switch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying 90 To 90 Switch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d7f7633a-27c5-496b-8868-e5d76bf6b6bb', 'Push Up Plus', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts. Start with lighter weight to master the movement pattern.', '31461201', '31461201-Push-Up-Plus-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Keep your core engaged for stability. This exercise is excellent for chest development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Push Up Plus', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d80257b1-0f08-4ced-a886-92cab63a4eb5', 'Triangle Pose Trikonasana', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Triangle Pose Trikonasana helps improve mobility and prevent stiffness. Flexibility work like this enhances performance and prevents stiffness.', '9621201', '09621201-Triangle-Pose-Trikonasana-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Move into the stretch position for Triangle Pose Trikonasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Triangle Pose Trikonasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d8026e1f-2098-4a89-a289-b7dc5b5c60f9', 'Lying Quarter Hip Raise', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '92841201', '92841201-Lying-Quarter-Hip-Raise-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Quarter Hip Raise. 2. Raise the weight in the prescribed direction for Lying Quarter Hip Raise. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_exercise', 'Lying Quarter Hip Raise', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d8042790-2b0c-4419-a22c-514703ea3ac5', 'Squat Hips (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength.', '66231201', '66231201-Barbell-Squat---Hips-(WRONG-RIGHT)-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Squat Hips. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Squat Hips', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('d80cbff7-09f2-4c95-8783-d2d1bd0acf3a', 'Seated Elbows Tucked Open (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Elbows Tucked Open On A Chair is a movement exercise that builds thickness in your upper back. Secondary activation of your rear delts provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. A strong back improves posture, prevents injury, and balances pressing movements.', '91021201', '91021201-Sitting-Elbows-Tucked-Open-on-a-Chair-(female)_Bac.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep. A solid choice for back day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Elbows Tucked Open On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d80dba05-280c-45fb-8923-767b7664fb4a', 'Back Leg Lift (Wall Supported)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your hip abductors. Strong legs are the foundation for athletic performance and functional fitness.', '93551201', '93551201-Wall-Supported-Back-Leg-Lift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for Wall Supported Back Leg Lift. 3. Execute the movement with proper form, focusing on your hip abductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'back_exercise', 'Wall Supported Back Leg Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d824baf1-db24-4fd1-a1e6-19b2dcccebe0', 'Lying Single Leg Hamstring Stretch Against Wall (Gymnastic Rings)', 'Legs', 'Gymnastic Rings, Wall', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Target your hamstrings with this stretching stretch that helps restore range of motion. Secondary activation of your lower back provides additional muscle engagement. Performing this lying down removes momentum for stricter form. Include this in your routine for better mobility and reduced muscle tension.', '76221201', '76221201-Lying-Single-Leg-Hamstring-Stretch-against-Wall-(m.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Position yourself at the appropriate distance from a wall. 2. Lie down in the appropriate position for Lying Single Leg Hamstring Stretch Against Wall. 3. Move into the stretch position for Lying Single Leg Hamstring Stretch Against Wall. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 6. Switch sides and repeat for equal time. 7. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Lying Single Leg Hamstring Stretch Against Wall', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('d826ccb9-45c4-4186-8855-3ce1426bc7dc', 'Deep Frog Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength. Can be modified for beginners or progressed for advanced athletes.', '78911201', '78911201-Deep-Frog-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Maintain a neutral spine throughout. This exercise is excellent for quads development.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Deep Frog Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d83ec56a-23d3-41d1-8dd1-bd1009939392', 'Split Jump (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity jumping exercise that challenges your entire body. Your quads, calves work as secondary movers, adding to the training stimulus. The dumbbell variation provides freedom of movement and greater range of motion. Plyometric training builds explosive power that transfers to sports and daily activities.', '15541201', '15541201-Dumbbell-Split-Jump_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Split Jump. 2. Set up in the starting position for Dumbbell Split Jump. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 62, 9, 8, TRUE, TRUE, 'lunge_jump', 'Split Jump', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 60, 4, 92, 90, 92, 90),
('d8439621-be37-43a7-a233-66b86f75ed90', 'Kneeling Hip Flexor Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'This stretch specifically works on your hip flexors, promoting flexibility and reducing muscle tightness. Kneeling helps eliminate lower body momentum from the movement. Include this in your routine for better mobility and reduced muscle tension. This is a great exercise for all fitness levels with proper scaling.', '10531201', '10531201-Kneeling-Hip-Flexor-Stretch_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Hip Flexor Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Kneeling Hip Flexor Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d848f992-ca46-4a29-a533-648810ddf290', 'Concentration Curl (Kettlebell)', 'Arms', 'Kettlebell', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. Kettlebells are excellent for building functional, real-world strength. Arm strength supports grip, pulling, and pushing in compound movements.', '58561201', '58561201-Kettlebell-Concentration-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Select an appropriately weighted kettlebell for Kettlebell Concentration Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'concentration_curl', 'Concentration Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('d8505141-60d7-4ed6-a796-1a23fabe331d', 'Donkey Diagonal Kickback (Cable)', 'Legs', 'Cables', '{"Glutes","Hamstrings"}'::text[], '{"Rear Delts"}'::text[], 'This kicking exercise isolates your glutes for improved hip strength and power. The hamstrings assist throughout the movement, making this a well-rounded exercise. Cable resistance creates smooth, continuous muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '73831201', '73831201-Cable-Donkey-Diagonal-Kickback-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Adjust the cable machine to the correct height and attachment for Cable Donkey Diagonal Kickback. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Donkey Diagonal Kickback', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('d86c813a-16b1-4c3f-b800-7533f3e208b5', 'Standing Forward Bent Twist Toe Touch - Alternating', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Standing Forward Bent Alternating Twist Toe Touch is a core twisting exercise that primarily targets your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '103581201', '103581201-Standing-Forward-Bent-Alternating-Twist-Toe-Touch.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Standing Forward Bent Alternating Twist Toe Touch. 3. Control the rotation in both directions—avoid using momentum. 4. Alternate between sides/arms/legs with each repetition. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'toe_touch', 'Standing Forward Bent Twist Toe Touch - Alternating', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d86eb551-0d55-4a11-b87d-4d83cfc7d51e', 'Rollout (Barbell)', 'Core', 'Barbell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Barbell Rollout is a lower body movement exercise that targets your abs. You''ll also feel your lats, shoulders working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '841201', '00841201-Barbell-Rollout_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Grip a barbell with hands at the appropriate width for Barbell Rollout. 2. Set up in the starting position for Barbell Rollout. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'ab_rollout', 'Rollout', 'plank, crunch, dead_bug', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('d88863a8-b038-4bf1-bf98-a793d2e8f8c8', '45 Degree Hyperextension Arms Crossed (Hyperextension Bench)', 'Back', 'Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger glutes with this extension movement focused on hip extension. Secondary activation of your hamstrings, lower back provides additional muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '14651201', '14651201-45-degree-hyperextension-(arms-in-front-of-chest)-(Side-view)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Raise your torso by extending at the lower back/hips. 2. Lower with control, maintaining tension. 3. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', 'Hip Hinge / Trunk Extension', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', '45 Degree Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d890cf8f-a23a-4d30-93fe-5c5562abf173', 'Overhead Shoulder Press (Resistance Band)', 'Shoulders', 'Resistance Band', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Resistance Band Overhead Shoulder Press provides a deep stretch for your delts, ideal for recovery and mobility work. You''ll also feel your triceps working to support the movement. The band creates increasing tension as it stretches, challenging the lockout. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '80871201', '80871201-Resistance-Band-Overhead-Shoulder-Press-(female)_S.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Overhead Shoulder Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'shoulder_press', 'Overhead Shoulder Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d89a0557-3f98-4411-b161-2e3ecabfca52', 'Single Arm Clean And Jerk (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. Secondary activation of your quads, glutes, traps provides additional muscle engagement. Kettlebells are excellent for building functional, real-world strength. Strong shoulders improve overhead strength and support nearly all upper body movements.', '5371201', '05371201-Kettlebell-One-Arm-Clean-and-Jerk_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Select an appropriately weighted kettlebell for Kettlebell One Arm Clean And Jerk. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'clean', 'Single Arm Clean And Jerk', 'clean, jerk, thruster', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('d8a4b6f5-2043-4e65-b30c-3ea3c8c8e58a', 'Deep Knee Bend', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this movement movement that develops leg drive and power. Secondary activation of your glutes provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '82201201', '82201201-Deep-Knee-Bend-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Set up in the starting position for Deep Knee Bend. 2. Execute the movement with proper form, focusing on your quads. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Deep Knee Bend', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d8c3e297-2bd5-4bd4-8c83-e9588f0b0e2d', 'Lying Isometric Knee Flexion', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Isometric Knee Flexion is a lower body flexion exercise that targets your core. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '100091201', '100091201-Lying-Isometric-Knee-Flexion-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Isometric Knee Flexion. 2. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Isometric Knee Flexion', 'squat, leg_extension, lunge', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('d8dee4af-430a-4bdd-8319-e65a98da99e0', 'Leg Pull - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Alternate Leg Pull is a core pulling exercise that primarily targets your abs. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '55381201', '55381201-Alternate-Leg-Pull-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate Leg Pull. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Leg Pull - Alternating', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d8e28d53-7759-4994-9d14-2d69fc4a2736', 'Seated Sky Look', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '49471201', '49471201-Seated-Sky-Look_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Sky Look. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Sky Look', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d8ea4171-f77b-4150-8281-75dfa4bd263c', 'Chin Ups Narrow Parallel Grip (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This rowing exercise emphasizes your lats for improved back development. Your biceps work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '36001201', '36001201-Chin-ups-(narrow-parallel-grip)-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Use a close/narrow grip (hands closer than shoulder-width). 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Chin Ups', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d8eaf087-f9c8-400d-bf20-2ba9f702ab28', 'Stepback Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'A challenging plyometric exercise, the Stepback Row builds reactive power and improves conditioning. The quads assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities.', '88371201', '88371201-Stepback-Row-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'back_exercise', 'Stepback Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d8eb2be0-559a-44c8-8d20-2ebeafe0cb8b', 'Standing Hip Frontal Rotation With Shoulders Adduc', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Develop functional strength with the Standing Hip Frontal Rotation With Shoulders Adduc, a comprehensive rotation exercise. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Compound movements like this develop coordination, power, and overall fitness.', '53191201', '53191201-Standing-Hip-Frontal-Rotation-with-Shoulders-Adduc.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Rotate your torso through the movement pattern for Standing Hip Frontal Rotation With Shoulders Adduc. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Hip Frontal Rotation With Shoulders Adduc', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d8f2dbfc-28d9-4c4b-a15f-6771028e1146', 'Front Shoulder Raise (Cable)', 'Shoulders', 'Cables', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. Cable resistance creates smooth, continuous muscle engagement. Shoulder development enhances both performance and upper body aesthetics.', '1641201', '01641201-Cable-Front-Shoulder-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Adjust the cable machine to the correct height and attachment for Cable Front Shoulder Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'shoulder_exercise', 'Front Shoulder Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('d8ff87be-bc58-4215-b4ae-c8bf8c360e71', 'Standing Back Achilles Stretch (Resistance Band)', 'Legs', 'Resistance Band', '{"Calves"}'::text[], '{}'::text[], 'Designed to lengthen your back, the Resistance Band Standing Back Achilles Stretch helps improve mobility and prevent stiffness. Performing this standing challenges your balance and core engagement. Bands are joint-friendly and portable, perfect for any training environment. Flexibility work like this enhances performance and prevents stiffness.', '29991201', '29991201-Resistance-Band-Standing-Back-Achilles-Stretch_Cal.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Secure the resistance band appropriately for Resistance Band Standing Back Achilles Stretch. 2. Stand tall with your feet firmly planted. 3. Move into the stretch position for Resistance Band Standing Back Achilles Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 47, 2, 6, FALSE, TRUE, 'calf_stretch', 'Standing Back Achilles Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'band', TRUE, 1, 30, 2, 60, 85, 90, 50),
('d90a4f32-dccc-4621-917b-16617f17d0b5', 'Weighted Chain Sumo Deadlift', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Lower Back","Inner Thighs"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '59101201', '59101201-Weighted-Chain-Sumo-Deadlift_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Hinge at hips and bend knees to grip the weight. 2. Drive through your heels, extending hips and knees to stand. 3. Lower by reversing the movement with control. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'deadlift', 'Weighted Chain Sumo Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d90afd68-6f9d-4ec2-b8e2-63b7262f77ec', 'Lying Single Arm Press (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Performing this lying down removes momentum for stricter form. Using dumbbells requires more stabilization than barbell variations. A well-developed chest contributes to upper body strength and aesthetics.', '26801201', '26801201-Dumbbell-Lying-One-Arm-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Lie down in the appropriate position for Dumbbell Lying One Arm Press. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'arm_exercise', 'Lying Single Arm Press', 'bicep_curl, tricep_extension, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('d92894de-2f34-49c9-bbdd-03df5f9dee43', 'Squat Tuck Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Squat Tuck Jump is a cardiovascular exercise that improves endurance and heart health. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '71711201', '71711201-Squat-Tuck-Jump-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Explode upward from the bottom, jumping as high as possible. 4. Land softly with bent knees and immediately descend into the next rep. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'tuck_jump', 'Squat Tuck Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d937a948-0de6-438d-87b1-dff0c1614be8', 'Half Plyo Squat Twist', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build rotational power and define your waistline with the Half Plyo Squat Twist. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '97211201', '97211201-Half-Plyo-Squat-Twist-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Control the movement—avoid using momentum. Works well for obliques activation.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'squat', 'Half Plyo Squat Twist', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d940619e-5704-49d7-b7c3-c3768cca529e', 'Corkscrew', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Flexibility work like this enhances performance and prevents stiffness. A staple exercise that belongs in most training programs.', '28411201', '28411201-Corkscrew_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Move into the stretch position for Corkscrew. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Corkscrew', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d94de77b-f4b5-4ee9-8426-76e2b93b8198', 'Shrug (Machine)', 'Back', 'Shrug Machine', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'The Lever Shrug (plate Loaded) is a shrugging exercise that develops back strength and muscle. The fixed path allows you to focus purely on muscular effort. A strong back improves posture, prevents injury, and balances pressing movements.', '31071201', '31071201-Lever-Shrug-(plate-loaded)-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'shrug', 'Lever Shrug', 'deadlift, bent_over_row, face_pull', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('d95c6a42-d352-4527-82f9-2e45417626db', 'Mountain Climber Low Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Mountain Climber Low Lunge is a core lunging exercise that primarily targets your abs. The hip flexors, shoulders assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '74511201', '74511201-Mountain-Climber-Low-Lunge-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber Low Lunge', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d965e62e-40a2-4f6b-ab3b-0a667a22befb', 'Standing Straight Arms Pulldown (Resistance Band)', 'Back', 'Resistance Band, Anchor Point', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Secondary activation of your biceps, upper back provides additional muscle engagement. The standing position engages your core for stability. Resistance bands provide accommodating resistance that increases through the range of motion. Back development is crucial for pulling strength and overall upper body function.', '92981201', '92981201-Resistance-Band-Standing-Straight-Arms-Pulldown-(f.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Standing Straight Arms Pulldown. 2. Begin in a standing position with good posture. 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Standing Straight Arms Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('d9679e82-9127-4649-bcc0-0df9cad5cc13', 'Bench Reverse Crunch Circle', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Bench Reverse Crunch Circle is a core crunching exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. A strong core improves posture, protects your spine, and enhances all other lifts.', '43331201', '43331201-Bench-Reverse-Crunch-Circle_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Lift your hips off the floor by contracting your lower abs. 2. Bring your knees toward your chest, then lower with control. 3. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Bench Reverse Crunch Circle', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d96b4a20-9521-4e9a-9629-c7ded90b3e5c', 'Double Palm Tap Russian Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '88571201', '88571201-Double-Palm-Tap-Russian-Twist-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Rotate your torso through the movement pattern for Double Palm Tap Russian Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Double Palm Tap Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d9854ef4-cdd5-4760-ba32-5f4460c41f53', 'V Step And Back', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the V Step And Back builds reactive power and improves conditioning. You''ll also feel your quads working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '77591201', '77591201-V-Step-and-Back-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for V Step And Back. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'V Step And Back', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d992395f-227e-424e-876b-d414812c7885', 'Side Walk Double Leg Lift', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Side Walk Double Leg Lift builds reactive power and improves conditioning. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '56821201', '56821201-Side-Walk-Double-Leg-Lift-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Set up in the starting position for Side Walk Double Leg Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Side Walk Double Leg Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d9946027-e526-4129-aa4a-4a6501134d29', 'Standing Glute Kickback - Alternating', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Rear Delts"}'::text[], 'This kicking exercise isolates your glutes for improved hip strength and power. The hamstrings assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '74351201', '74351201-Standing-Alternate-Glute-Kickback-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand tall with your feet firmly planted. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Alternate between sides/arms/legs with each repetition. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'glute_kickback', 'Standing Glute Kickback - Alternating', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d9974938-f0a2-4c8a-8e5a-b089e121cd89', 'Russian Twist With Legs Floor Off (Dumbbell)', 'Core', 'Dumbbells', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Dumbbell Russian Twist With Legs Floor Off targets your obliques through a twisting motion, building rotational core strength. The abs assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Core strength is foundational for athletic performance and injury prevention.', '47501201', '47501201-Dumbbell-Russian-Twist-with-Legs-Floor-Off_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Russian Twist With Legs Floor Off. 2. Position yourself on the floor for Dumbbell Russian Twist With Legs Floor Off. 3. Rotate your torso through the movement pattern for Dumbbell Russian Twist With Legs Floor Off. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'russian_twist', 'Russian Twist With Legs Floor Off', 'crunch, plank, leg_raise, wood_chop', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d9a211aa-f4f6-48d1-a121-0f5894e708f9', 'Triceps Press (TRX)', 'Arms', 'TRX', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This pressing movement isolates your triceps for improved arm development. Suspension training adds instability, increasing core activation throughout. Dedicated arm training builds both strength and muscular definition.', '83671201', '83671201-Suspender-Triceps-Press-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Triceps Press. 2. Keep your upper arms stationary and extend at the elbow. 3. Squeeze your triceps at full extension, then control the return. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'arm_exercise', 'Suspender Triceps Press', 'bicep_curl, tricep_pushdown, skull_crusher, dip', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('d9a5531b-9197-4a7b-9a7e-a4697a05d480', 'Lying Leg Press (Resistance Band, Machine)', 'Legs', 'Leg Press Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pressing movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes provides additional muscle engagement. Performing this lying down removes momentum for stricter form. Bands are joint-friendly and portable, perfect for any training environment. Leg training boosts metabolism and builds functional, real-world strength.', '81421201', '81421201-Resistance-Band-Lying-Leg-Press-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Secure the resistance band appropriately for Resistance Band Lying Leg Press. 2. Lie down in the appropriate position for Resistance Band Lying Leg Press. 3. Position your feet on the platform and release the safety. 4. Lower the weight by bending your knees, then press back up powerfully. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Lying', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'leg_press', 'Lying Leg Press', 'squat, hack_squat, lunge', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('d9a93bef-4771-4f5f-b9fc-d5584d495265', 'Single Arm Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. The forearms assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition. Keep your core engaged throughout the exercise.', '104581201', '104581201-Dumbbell-Single-Arm-Wrist-Curl-(male)_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'wrist_curl', 'Single Arm Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('d9b0f749-f25a-4170-a520-394b474a4db5', 'Overhead Knee Raise Jack', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Overhead Knee Raise Jack builds reactive power and improves conditioning. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '97741201', '97741201-Overhead-Knee-Raise-Jack-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Raise the weight in the prescribed direction for Overhead Knee Raise Jack. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'leg_raise', 'Overhead Knee Raise Jack', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('d9ba245b-cfbf-43ff-89da-0ad30a58bf66', 'Stiff Legged Deadlift (EZ Bar)', 'Legs', 'EZ Bar', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'The EZ Barbell Stiff Legged Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '88201201', '88201201-EZ-Barbell-Stiff-Legged-Deadlift_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Stiff Legged Deadlift. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'EZ Stiff Legged Deadlift', 'EZ Stiff Legged Deadlift', TRUE, 'ez_bar', FALSE, 4, 120, 6, 95, 80, 65, 95),
('d9c42455-4277-415d-b8e0-bd3dce501933', 'Diamond Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Diamond Push Up targets your triceps through a pushing motion. The chest assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Dedicated arm training builds both strength and muscular definition.', '2831201', '02831201-Diamond-Push-up_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Diamond Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d9d25e26-e454-44a0-9700-3be9f0d07d25', 'Rear Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. You''ll also feel your biceps, upper back working to support the movement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '6701201', '06701201-Rear-Pull-up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Rear Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('d9e51cdd-4d48-49e1-a4a0-4558b5b8a82b', 'Seated Finger Stretch (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'The Seated Finger Stretch On A Chair provides a deep stretch for your full body, ideal for recovery and mobility work. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '91671201', '91671201-Sitting-Finger-Stretch-on-a-Chair-(female)_Hands_.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Finger Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Finger Stretch On A Chair', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('d9ee5c4c-9a8e-41e4-8936-bf8a4c45a29f', 'Single Arm Shoulder Press (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Dumbbell One Arm Shoulder Press is a pressing exercise that targets your delts for shoulder development. Secondary activation of your triceps provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '23811201', '23811201-Dumbbell-One-Arm-Shoulder-Press-(version-2)-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'shoulder_press', 'Single Arm Shoulder Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('d9f22013-c69b-4bda-b827-e43ca31d9772', 'Standing Turn And Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Standing Turn And Knee Raise is an explosive exercise that combines cardiovascular training with dynamic raising movements. The hip flexors assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '73331201', '73331201-Standing-Turn-and-Knee-Raise-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Stand with feet about shoulder-width apart. 2. Raise the weight in the prescribed direction for Standing Turn And Knee Raise. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Standing Turn And Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('d9f6a8e9-11ca-4b3e-af7a-83a2b9b855db', 'Opposite 2 Point Bench Press (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '80051201', '80051201-Dumbbell-Opposite-2-Point-Bench-Press-(male)_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Opposite 2 Point Bench Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'bench_press', 'Opposite 2 Point Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('d9fd6c88-65a1-481a-91b1-5aef03a31a8f', 'Lunge Twist', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '65291201', '65291201-Lunge-Twist-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Lunge Twist', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('da03aec4-d5ac-4b16-8715-0a97c3888586', 'Walking Shoulder Tap To Sky Push', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this pushing exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '99131201', '99131201-Walking-Shoulder-Tap-to-Sky-Push-(female)_Plyometr.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walking Shoulder Tap To Sky Push. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking Shoulder Tap To Sky Push', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('da0656f6-3bc6-4f00-938b-2111f0763b17', 'Lying Figure 4 Twisting Torso Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your glutes area and enhance overall flexibility. Your hips work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. Flexibility work like this enhances performance and prevents stiffness.', '96751201', '96751201-Lying-Figure-4-Twisting-Torso-Stretch-(male)_Stret.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Lie down in the appropriate position for Lying Figure 4 Twisting Torso Stretch. 2. Rotate your torso through the movement pattern for Lying Figure 4 Twisting Torso Stretch. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 32, 2, 6, FALSE, TRUE, 'stretch_general', 'Lying Figure 4 Twisting Torso Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('da22dc6d-f64a-4246-9a55-4c40ea0cbb7a', 'Roll Press Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This pressing exercise engages your abs for improved core stability and strength. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '66591201', '66591201-Roll-Press-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Execute the pressing motion for Roll Press Plank, extending through the target muscles. 2. Set up in the starting position for Roll Press Plank. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Roll Press Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('da4ef02a-48b7-439b-af4d-7b45f583a485', 'Split Stance Single Arm Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Split Stance Single Arm Row is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '75641201', '75641201-Cable-Split-Stance-Single-Arm-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Adjust the cable machine to the correct height and attachment for Cable Split Stance Single Arm Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Split Stance Single Arm Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('da5ed71c-0281-49c0-a60e-8bd0fd01deb9', 'Decline Crunch (Cable)', 'Core', 'Cables, Decline Bench', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Declining shifts the emphasis to hit the muscles from a different angle. Cables provide constant tension throughout the full range of motion. A strong core improves posture, protects your spine, and enhances all other lifts.', '69361201', '69361201-Cable-Decline-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Adjust the cable machine to the correct height and attachment for Cable Decline Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Complete all reps with control before resting.', 'Crunch', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 83, 5, 7, FALSE, TRUE, 'crunch', 'Decline Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('da74bd11-03d0-41cb-95dc-de6c3a034630', 'Roll Tensor Fasciae Latae', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Biceps"}'::text[], 'Build leg strength with this movement movement focusing on your upper back. The biceps assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '45981201', '45981201-Roll-Tensor-Fasciae-Latae_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Set up in the starting position for Roll Tensor Fasciae Latae. 2. Execute the movement with proper form, focusing on your upper back. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Roll Tensor Fasciae Latae', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('da7a4013-f068-4919-8a09-603aa1cfda39', 'Shoulders Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger back with this rotation movement targeting your delts. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '54551201', '54551201-Shoulders-Rotation-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Rotate your torso through the movement pattern for Shoulders Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Shoulders Rotation', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('da7dc30c-7316-4574-aaae-9fc0f2e59c9a', 'Bench Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Strong legs are the foundation for athletic performance and functional fitness. Perfect for including in both strength and hypertrophy programs.', '22251201', '22251201-Barbell-Bench-Squat-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', 'Squat', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand (Pronated)', 'Standard', 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Bench Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('da81e77b-3390-44d0-a5bc-ac32e62bd00c', 'Swing And Hops', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'A challenging plyometric exercise, the Swing And Hops builds reactive power and improves conditioning. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '77781201', '77781201-Swing-and-Hops-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Hinge at your hips, letting the weight swing back between your legs. 2. Explosively drive hips forward, propelling the weight forward/up. 3. Let gravity bring it back as you hinge for the next rep. 4. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'hop', 'Swing And Hops', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('da8543d6-34d6-489d-8479-ccf157506b01', 'Standing Calf Raise With Arms Circle', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '96611201', '96611201-Standing-Calf-Raise-with-Arms-Circle-(male)_Calves.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Stand tall with your feet firmly planted. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Calf Raise With Arms Circle', 'calf_raise, seated_calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('da86ca18-83e4-4d46-9274-e939396a4a47', 'Seated Quads Stretch - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your quads, the Seated Alternating Quads Stretch helps improve mobility and prevent stiffness. You''ll also feel your hip flexors working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Include this in your routine for better mobility and reduced muscle tension.', '96831201', '96831201-Sitting-Alternating-Quads-Stretch-(male)_Stretchin.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Alternating Quads Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Alternate between sides/arms/legs with each repetition. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Quads Stretch - Alternating', 'stretch_hip, stretch_hamstring', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('da876784-659a-436f-880e-7184056240d8', 'Straight Back Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. The biceps, lats assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Cable resistance creates smooth, continuous muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '2391201', '02391201-Cable-Straight-Back-Seated-Row_Back.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Adjust the cable machine to the correct height and attachment for Cable Straight Back Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'cable_row', 'Straight Back Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('da8b4606-f663-4f3b-a0b4-a31ad0479ed2', 'Hip Twist Rollout (Barbell)', 'Core', 'Barbell', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build leg strength with this twisting movement focusing on your abs. Your lats, shoulders work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. Strong legs are the foundation for athletic performance and functional fitness.', '103721201', '103721201-Barbell-Hip-Twist-Rollout_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Grip a barbell with hands at the appropriate width for Barbell Hip Twist Rollout. 2. Rotate your torso through the movement pattern for Barbell Hip Twist Rollout. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'ab_rollout', 'Hip Twist Rollout', 'plank, crunch, dead_bug', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('da8bea5e-6468-4f7c-98ea-68fe01465687', 'Reverse Lunge (leg Kick)', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'The Reverse Lunge (leg Kick) is a lunging exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '58121201', '58121201-Reverse-Lunge-(leg-kick)-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Reverse Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('daafe8be-330d-4e1a-9612-0813a6c86fa2', 'Prayer Push Hold', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '70521201', '70521201-Prayer-Push-Hold-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Hold the position for the prescribed time, maintaining tension. 2. Set up in the starting position for Prayer Push Hold. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 30, 7, 8, TRUE, TRUE, 'boxing', 'Prayer Push Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dab6e7fe-97d7-4d77-b4e7-8cc64ee8cdde', 'Seated Abs Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Seated Abs Twist. Your abs work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '96661201', '96661201-Sitting-Abs-Twist-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Abs Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Abs Twist', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('dabdb4fd-3f5d-4a30-bd40-49b5b878809d', 'Kneeling Torso Rotation Chest And Shoulder Stretch', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Use this stretch to open up your shoulders area and enhance overall flexibility. Secondary activation of your upper back provides additional muscle engagement. The kneeling position adds a core stability challenge. Flexibility work like this enhances performance and prevents stiffness.', '89891201', '89891201-Kneeling-Torso-Rotation-Chest-and-Shoulder-Stretch.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Rotate your torso through the movement pattern for Kneeling Torso Rotation Chest And Shoulder Stretch. 3. Control the rotation in both directions—avoid using momentum. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Kneeling Torso Rotation Chest And Shoulder Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('dabf0720-51cb-440c-8ad2-8a48dcb5f214', 'Single Arm Fly (Stability Ball, Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Cable One Arm Fly On Exercise Ball is a flying exercise that targets your chest muscles. The front delts assist throughout the movement, making this a well-rounded exercise. Cable resistance creates smooth, continuous muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12631201', '12631201-Cable-One-Arm-Fly-on-Exercise-Ball_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Fly On Exercise Ball. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'chest_fly', 'Single Arm Fly On Exercise Ball', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('dac51661-897c-4ded-ac94-60be78b3017d', 'Seated Dynamic Chest Stretch', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with this stretching stretch that helps restore range of motion. The shoulders assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '85651201', '85651201-Seated-Dynamic-Chest-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Dynamic Chest Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'chest_stretch', 'Seated Dynamic Chest Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('dacb369d-2c7d-4056-bad0-6c0559ccfa00', 'Calf Raise Internal External Arms Rotation', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'The Calf Raise Internal External Arms Rotation isolates your calf muscles through a raising motion. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '96551201', '96551201-Calf-Raise-Internal-External-Arms-Rotation-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Rotate your torso through the movement pattern for Calf Raise Internal External Arms Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'calf_raise', 'Calf Raise Internal External Arms Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65);
